func.func @main(%arg0: tensor<f32>, %arg1: tensor<7x7xf32>, %arg2: tensor<7xf32>, %arg3: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // Perform linear layer: x * weight^T + bias
  // %arg3: input tensor<6x7xf32>
  // %arg1: weight tensor<7x7xf32> (PyTorch Linear weight shape: out_features x in_features)
  // We need to transpose weight to shape 7x7 (same shape, but transpose to match dot dims)
  // Actually, PyTorch Linear weight shape is (out_features, in_features) = (7,7)
  // Input shape is (6,7)
  // So to do x * weight^T, we do dot_general with contracting dims input:1, weight:1
  // But weight is (7,7), so weight^T is (7,7), same shape, so transpose weight dims 0 and 1
  %weight_t = "stablehlo.transpose"(%arg1) {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>
  %dot = "stablehlo.dot_general"(%arg3, %weight_t) {dot_dimension_numbers = #stablehlo.dot<lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>} : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>
  // Add bias: broadcast bias from [7] to [6x7]
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %add_bias = stablehlo.add %dot, %bias_broadcast : tensor<6x7xf32>
  // Apply minimum with constant (broadcast scalar constant to [6x7])
  %const_broadcast = "stablehlo.broadcast_in_dim"(%arg0) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7xf32>
  %min = stablehlo.minimum %add_bias, %const_broadcast : tensor<6x7xf32>
  // Subtract constant (broadcast scalar constant to [6x7])
  %result = stablehlo.subtract %min, %const_broadcast : tensor<6x7xf32>
  return %result : tensor<6x7xf32>
}

