  // %arg2: linear.bias, shape [7]
  // We want to do dot_general with contracting dims: input last dim (1), weight last dim (1)
  // But weight needs to be transposed to shape [7,7] (actually already 7x7), but PyTorch weight shape is [out_features, in_features]
  // So to do x @ W^T, we do dot_general with lhs_contracting=[1], rhs_contracting=[1], but rhs is weight transposed.
  // Actually, PyTorch weight shape is [out_features, in_features] = [7,7]
  // Input shape: [6,7]
  // So x @ W^T = [6,7] @ [7,7]^T = [6,7] @ [7,7] = [6,7]
  // So we transpose weight to [7,7] (same shape), but transpose permutes dims [1,0]
  %weight_t = "stablehlo.transpose"(%arg1) {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>
  %linear = "stablehlo.dot_general"(%arg3, %weight_t) {dot_dimension_numbers = #stablehlo.dot<lhs_batching_dimensions = [], rhs_batching_dimensions = [], lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [1]>} : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>
  // Add bias: broadcast bias from [7] to [6,7]
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %linear_bias = stablehlo.add %linear, %bias_broadcast : tensor<6x7xf32>
  // Compute minimum with constant scalar %arg0 (tensor<f32>)
  // Broadcast constant scalar to [6,7]
  %const_broadcast = "stablehlo.broadcast_in_dim"(%arg0) {broadcast_dimensions = array<i64:>} : (tensor<f32>) -> tensor<6x7xf32>
  %min = stablehlo.minimum %linear_bias, %const_broadcast : tensor<6x7xf32>
  // Subtract constant scalar broadcasted
  %result = stablehlo.subtract %min, %const_broadcast : tensor<6x7xf32>
  return %result : tensor<6x7xf32>
}

