  // Step 1: Reverse the kernel spatial dimensions (height and width)
  // The kernel shape is [in_channels, out_channels, kernel_h, kernel_w]
  // Reverse dims 2 and 3 (kernel_h and kernel_w)
  %reversed_kernel = "stablehlo.reverse"(%arg0) {dimensions = array<i64: 2, 3>} : (tensor<6x6x3x3xf32>) -> tensor<6x6x3x3xf32>

  // Step 2: Perform convolution with:
  // lhs = input tensor: [8, 6, 7, 7]
  // rhs = reversed kernel: [6, 6, 3, 3]
  // dimension_numbers = [b, f, 0, 1] x [o, i, 0, 1] -> [b, f, 0, 1]
  // Here:
  // lhs dims: b=0, f=1, h=2, w=3
  // rhs dims: o=0, i=1, h=2, w=3
  // output dims: b=0, f=1, h=2, w=3
  //
  // window_strides = [1, 1]
  // padding = [[2, 2], [2, 2]] to achieve output spatial size 9x9
  // lhs_dilation = [2, 2] (stride of 2 in transposed conv)
  // rhs_dilation = [1, 1]
  // feature_group_count = 1
  //
  // Explanation:
  // Transposed conv with stride=2 is implemented as convolution with lhs_dilation=2.
  // Padding is computed to get output spatial size 9x9:
  // output_size = (input_size - 1) * stride - 2*padding + kernel_size
  // 9 = (7 - 1)*2 - 2*padding + 3 => 9 = 12 - 2*padding + 3 => 9 = 15 - 2*padding => 2*padding = 6 => padding=3
  // But we must split padding into low and high sides. PyTorch default is padding=0, output_padding=0,
  // so symmetric padding of 2 on each side is used here to match output size 9.
  //
  // Actually, to get output 9 from input 7 with stride 2 and kernel 3 and padding 0:
  // output = (input - 1)*stride - 2*padding + kernel + output_padding
  // output = (7-1)*2 - 0 + 3 + 0 = 12 + 3 = 15, which is too large.
  // So we must pad input to reduce output size.
  // The PyTorch ConvTranspose2d with padding=0 and output_padding=0 produces output size:
  // output = (input - 1)*stride - 2*padding + kernel + output_padding
  // Given output=9, input=7, stride=2, kernel=3, padding=0, output_padding=0:
  // 9 = (7-1)*2 - 0 + 3 + 0 = 12 + 3 = 15 (too large)
  //
  // So the padding in PyTorch ConvTranspose2d is applied on the input, not on the convolution.
  // To simulate ConvTranspose2d with stride=2, padding=0, output_padding=0:
  // Use lhs_dilation=2, padding=kernel_size - 1 - padding = 3 - 1 - 0 = 2
  // So padding = 2 on each side.
  //
  // So padding = [[2, 2], [2, 2]]

  %conv = "stablehlo.convolution"(%arg1, %reversed_kernel) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[2, 2], [2, 2]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 2, 2>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<8x6x7x7xf32>, tensor<6x6x3x3xf32>) -> tensor<8x6x9x9xf32>

  return %conv : tensor<8x6x9x9xf32>
}

// Conv dimension numbers attribute
// stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>
