func.func @main(%arg0: tensor<6x7x3x3x3xf32>, %arg1: tensor<8x6x8x8x8xf32>) -> tensor<8x7x10x10x10xf32> {
  // %arg0: conv_transpose3d.weight with shape [in_channels=6, out_channels=7, kD=3, kH=3, kW=3]
  // %arg1: input tensor with shape [batch=8, in_channels=6, D=8, H=8, W=8]

