  // Step 2: Perform convolution with lhs_dilation = stride = 2 (transposed conv stride)
  // dimension_numbers: input [b, f, 0, 1, 2] = [batch, in_channels, D, H, W]
  // kernel [o, i, 0, 1, 2] = [out_channels, in_channels, kD, kH, kW]
  // output [b, f, 0, 1, 2] = [batch, out_channels, D_out, H_out, W_out]
  //
  // Note: The weight shape is [in_channels, out_channels, kD, kH, kW], but convolution expects kernel shape [out_channels, in_channels, ...]
  // So we must transpose the kernel from [6,7,3,3,3] to [7,6,3,3,3].
  %kernel_transposed = "stablehlo.transpose"(%reversed_kernel) {permutation = array<i64: 1, 0, 2, 3, 4>} : (tensor<6x7x3x3x3xf32>) -> tensor<7x6x3x3x3xf32>

