  //
  // The formula for output spatial size in convolution:
  // output_size = floor((padding_low + (input_size - 1)*lhs_dilation + 1 + padding_high - ((kernel_size - 1)*rhs_dilation + 1)) / stride) + 1
  //
  // Here:
  // lhs_dilation = stride = 2
  // rhs_dilation = dilation = 1
  // padding = 1 on both sides
  //
  // So padding attribute is dense<[[1,1],[1,1],[1,1]]> : tensor<3x2xi64>
  //
  // dimension_numbers = #stablehlo.conv<[b, f, 0, 1, 2]x[o, i, 0, 1, 2]->[b, f, 0, 1, 2]>
  %conv = "stablehlo.convolution"(%arg1, %kernel_transposed) {
    window_strides = array<i64: 1, 1, 1>,
    padding = dense<[[1, 1], [1, 1], [1, 1]]> : tensor<3x2xi64>,
    lhs_dilation = array<i64: 2, 2, 2>,
    rhs_dilation = array<i64: 1, 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 0, 1, 2]x[o, i, 0, 1, 2]->[b, f, 0, 1, 2]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<8x6x8x8x8xf32>, tensor<7x6x3x3x3xf32>) -> tensor<8x7x10x10x10xf32>

  return %conv : tensor<8x7x10x10x10xf32>
}

func.func @main(%multiplier: tensor<6x1x1xf32>, %conv_weight: tensor<6x6x3x3xf32>, %conv_bias: tensor<6xf32>, %input: tensor<6x6x7x7xf32>) -> tensor<6x6x5x5xf32> {
  // Convolution parameters:
  // input shape: [6, 6, 7, 7]
  // weight shape: [6, 6, 3, 3]
  // output shape: [6, 6, 5, 5] (default stride=1, padding=0)
  // dimension_numbers: input [b, f, h, w], kernel [o, i, kh, kw], output [b, f, oh, ow]
  %conv = "stablehlo.convolution"(%input, %conv_weight) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 1, 1>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 2, 3]x[o, i, 2, 3]->[b, f, 2, 3]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x6x7x7xf32>, tensor<6x6x3x3xf32>) -> tensor<6x6x5x5xf32>

  // Add bias: broadcast bias from [6] to [6x6x5x5]
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%conv_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<6xf32>) -> tensor<1x6x1x1xf32>
  // We want to add bias to conv output of shape [6x6x5x5], so broadcast bias to [6x6x5x5]
  // The bias shape is [6], corresponds to output channels dimension (f=1)
  // So broadcast bias from [6] to [6x6x5x5] with broadcast dims [1]
  // But stablehlo.broadcast_in_dim requires rank(operand) == size(broadcast_dimensions)
  // So first reshape bias to [6] -> [1x6x1x1]
  %bias_reshaped = "stablehlo.reshape"(%conv_bias) : (tensor<6xf32>) -> tensor<1x6x1x1xf32>
  %bias_broadcasted = "stablehlo.broadcast_in_dim"(%bias_reshaped) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<1x6x1x1xf32>) -> tensor<6x6x5x5xf32>
  %conv_plus_bias = stablehlo.add %conv, %bias_broadcasted : tensor<6x6x5x5xf32>

  // Multiply by multiplier: multiplier shape [6x1x1], broadcast to [6x6x5x5]
  // multiplier shape: [6x1x1], rank=3
  // output shape: [6x6x5x5], rank=4
  // broadcast_dimensions: map multiplier dims [0,1,2] to output dims [1,2,3]
  // Because multiplier dims correspond to output channels (f=1), height=2, width=3
  %multiplier_broadcast = "stablehlo.broadcast_in_dim"(%multiplier) {broadcast_dimensions = array<i64: 1, 2, 3>} : (tensor<6x1x1xf32>) -> tensor<6x6x5x5xf32>
  %scaled = stablehlo.multiply %conv_plus_bias, %multiplier_broadcast : tensor<6x6x5x5xf32>

  // LeakyReLU: f(x) = max(0, x) + negative_slope * min(0, x)
  // Default negative_slope = 0.01
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %zero_tensor = "stablehlo.broadcast_in_dim"(%zero) {broadcast_dimensions = array<i64>} : (tensor<f32>) -> tensor<6x6x5x5xf32>
  %max_part = stablehlo.maximum %scaled, %zero_tensor : tensor<6x6x5x5xf32>
  %min_part = stablehlo.minimum %scaled, %zero_tensor : tensor<6x6x5x5xf32>
  %neg_slope = stablehlo.constant dense<0.01> : tensor<f32>
  %neg_slope_tensor = "stablehlo.broadcast_in_dim"(%neg_slope) {broadcast_dimensions = array<i64>} : (tensor<f32>) -> tensor<6x6x5x5xf32>
  %min_scaled = stablehlo.multiply %min_part, %neg_slope_tensor : tensor<6x6x5x5xf32>
  %leaky_relu = stablehlo.add %max_part, %min_scaled : tensor<6x6x5x5xf32>

  // GELU: x * 0.5 * (1 + erf(x / sqrt(2)))
  // Compute x / sqrt(2)
  %sqrt2 = stablehlo.constant dense<1.4142135623730951> : tensor<f32>
  %sqrt2_tensor = "stablehlo.broadcast_in_dim"(%sqrt2) {broadcast_dimensions = array<i64>} : (tensor<f32>) -> tensor<6x6x5x5xf32>
  %inv_sqrt2 = stablehlo.divide %leaky_relu, %sqrt2_tensor : tensor<6x6x5x5xf32>

  // erf(x / sqrt(2))
  %erf_val = "chlo.erf"(%inv_sqrt2) : (tensor<6x6x5x5xf32>) -> tensor<6x6x5x5xf32>

  // 1 + erf(...)
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_tensor = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64>} : (tensor<f32>) -> tensor<6x6x5x5xf32>
  %one_plus_erf = stablehlo.add %one_tensor, %erf_val : tensor<6x6x5x5xf32>

  // x * 0.5
  %half = stablehlo.constant dense<0.5> : tensor<f32>
  %half_tensor = "stablehlo.broadcast_in_dim"(%half) {broadcast_dimensions = array<i64>} : (tensor<f32>) -> tensor<6x6x5x5xf32>
  %x_times_half = stablehlo.multiply %leaky_relu, %half_tensor : tensor<6x6x5x5xf32>

  // Final GELU output: x * 0.5 * (1 + erf(x / sqrt(2)))
  %gelu = stablehlo.multiply %x_times_half, %one_plus_erf : tensor<6x6x5x5xf32>

  return %gelu : tensor<6x6x5x5xf32>
}

func.func @main(%scale: tensor<1xf32>, %weight: tensor<7x7xf32>, %bias: tensor<7xf32>, %bn_weight: tensor<7xf32>, %bn_bias: tensor<7xf32>, %input: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // %input: [6,7], %weight: [7,7], %bias: [7]
  // Compute gemm: x @ weight + bias
  // dot_general lhs_contracting_dimensions=[1], rhs_contracting_dimensions=[0]
  %gemm = "stablehlo.dot_general"(%input, %weight) {dot_dimension_numbers = #stablehlo.dot<lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>} : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>
  %gemm_bias = stablehlo.add %gemm, "stablehlo.broadcast_in_dim"(%bias) {broadcast_dimensions = array<i64: 1>} : (tensor<6x7xf32>, tensor<7xf32>) -> tensor<6x7xf32>

  // BatchNorm1d forward (training mode):
  // mean = reduce mean over batch dim 0 -> shape [7]
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %init_mean = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
  %sum = "stablehlo.reduce"(%gemm_bias, %init_mean) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>
  // mean = sum / 6
  %six = stablehlo.constant dense<6.0> : tensor<f32>
  %mean = stablehlo.divide %sum, %six : tensor<7xf32>

  // Compute variance: mean of (x - mean)^2 over batch dim 0
  // Broadcast mean to [6,7]
  %mean_broadcast = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %diff = stablehlo.subtract %gemm_bias, %mean_broadcast : tensor<6x7xf32>
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<6x7xf32>
  %init_var = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
  %var_sum = "stablehlo.reduce"(%diff_sq, %init_var) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>
  %var = stablehlo.divide %var_sum, %six : tensor<7xf32>

  // Normalize: (x - mean) / sqrt(var + eps)
  %eps = stablehlo.constant dense<1.00000001e-5> : tensor<f32>
  %var_eps = stablehlo.add %var, %eps : tensor<7xf32>
  %stddev = stablehlo.sqrt %var_eps : tensor<7xf32>
  %stddev_broadcast = "stablehlo.broadcast_in_dim"(%stddev) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %normalized = stablehlo.divide %diff, %stddev_broadcast : tensor<6x7xf32>

  // Scale and shift: normalized * bn_weight + bn_bias
  %bn_weight_broadcast = "stablehlo.broadcast_in_dim"(%bn_weight) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %bn_bias_broadcast = "stablehlo.broadcast_in_dim"(%bn_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %scaled = stablehlo.multiply %normalized, %bn_weight_broadcast : tensor<6x7xf32>
  %shifted = stablehlo.add %scaled, %bn_bias_broadcast : tensor<6x7xf32>

  // Multiply by scale parameter (broadcast scale [1] to [6,7])
  %scale_broadcast = "stablehlo.broadcast_in_dim"(%scale) {broadcast_dimensions = array<i64: 1>} : (tensor<1xf32>) -> tensor<6x7xf32>
  %scaled_output = stablehlo.multiply %shifted, %scale_broadcast : tensor<6x7xf32>

  // Softmax along dim=1 (features dimension)
  // softmax(x) = exp(x - max(x)) / sum(exp(x - max(x)))
  // Compute max along dim=1 -> shape [6]
  %neg_inf = stablehlo.constant dense<0xFF800000> : tensor<f32>  // -inf
  %init_max = %neg_inf
  %max = "stablehlo.reduce"(%scaled_output, %init_max) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.maximum %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<6xf32>
  // Broadcast max to [6,7]
  %max_broadcast = "stablehlo.broadcast_in_dim"(%max) {broadcast_dimensions = array<i64: 0>} : (tensor<6xf32>) -> tensor<6x7xf32>
  // Subtract max for numerical stability
  %shifted_logits = stablehlo.subtract %scaled_output, %max_broadcast : tensor<6x7xf32>
  // exp(shifted_logits)
  %exp_logits = stablehlo.exponential %shifted_logits : tensor<6x7xf32>
  // sum exp along dim=1 -> shape [6]
  %init_zero = stablehlo.constant dense<0.0> : tensor<f32>
  %sum_exp = "stablehlo.reduce"(%exp_logits, %init_zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<6xf32>
  // Broadcast sum_exp to [6,7]
  %sum_exp_broadcast = "stablehlo.broadcast_in_dim"(%sum_exp) {broadcast_dimensions = array<i64: 0>} : (tensor<6xf32>) -> tensor<6x7xf32>
  // Divide exp_logits / sum_exp to get softmax output
  %softmax = stablehlo.divide %exp_logits, %sum_exp_broadcast : tensor<6x7xf32>

  "stablehlo.return"(%softmax) : tensor<6x7xf32>
}

func.func @main(%arg0: tensor<7x16x3x3xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x16x8x8xf32>) -> tensor<6x1x6x6xf32> {
  // %arg0 = conv.weight: [out_channels=7, in_channels=16, kernel_h=3, kernel_w=3]
  // %arg1 = conv.bias: [7]
  // %arg2 = input: [batch=6, in_channels=16, height=8, width=8]

  // Perform convolution:
  // dimension_numbers = [b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]
  // window_strides = [1, 1], padding = 0, lhs_dilation = 1, rhs_dilation = 1
  %conv = "stablehlo.convolution"(%arg2, %arg0) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 1, 1>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x16x8x8xf32>, tensor<7x16x3x3xf32>) -> tensor<6x7x6x6xf32>

  // Add bias: broadcast bias from [7] to [6x7x6x6]
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<1x7x1x1xf32>
  %bias_broadcast_reshaped = stablehlo.reshape %bias_broadcast : (tensor<1x7x1x1xf32>) -> tensor<6x7x6x6xf32>  // reshape to match conv output shape by repeating dims

  // Actually, reshape alone does not repeat data, so we must broadcast_in_dim directly to output shape:
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<1x7x1x1xf32>
  %bias_broadcast_full = "stablehlo.broadcast_in_dim"(%bias_broadcast) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<1x7x1x1xf32>) -> tensor<6x7x6x6xf32>

  %conv_bias = stablehlo.add %conv, %bias_broadcast_full : tensor<6x7x6x6xf32>

  // Compute minimum along channel dimension (dim=1), keepdim=True
  // stablehlo.reduce with init = +inf, reduce dimension = [1]
  %init_inf = stablehlo.constant dense<0x7F800000> : tensor<f32>  // +inf scalar
  %init_inf_tensor = stablehlo.broadcast_in_dim %init_inf {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<>  // rank-0 tensor, no broadcast needed

  %min = "stablehlo.reduce"(%conv_bias, %init_inf) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.minimum %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x7x6x6xf32>, tensor<f32>) -> tensor<6x6x6x6xf32>

  // The output shape after reduction is [6x6x6x6], but we want to keepdim=1, so shape should be [6x1x6x6]
  // So we reshape or add back the reduced dimension as size 1
  %min_keepdim = stablehlo.reshape %min : (tensor<6x6x6x6xf32>) -> tensor<6x1x6x6xf32>

  // Apply tanh twice
  %tanh1 = stablehlo.tanh %min_keepdim : tensor<6x1x6x6xf32>
  %tanh2 = stablehlo.tanh %tanh1 : tensor<6x1x6x6xf32>

  "stablehlo.return"(%tanh2) : tensor<6x1x6x6xf32>
}

func.func @main(%scale: tensor<1xf32>, %weight: tensor<7x7xf32>, %bias: tensor<7xf32>, %bn_weight: tensor<7xf32>, %bn_bias: tensor<7xf32>, %input: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // %gemm = input @ %input: tensor<6x7xf32>
  // %weight: tensor<7x7xf32>, %bias: tensor<7xf32>
  // Compute gemm: x @ weight + bias
  // dot_general with contracting dims: input last dim 1, weight second dim 0
  // input shape: [6,7], weight shape: [7,7]
  // Contract input dim 1 with weight dim 0
  %gemm = "stablehlo.dot_general"(%input, %weight) {dot_dimension_numbers = #stablehlo.dot<lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>} : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>
  %gemm_bias = stablehlo.broadcast_in_dim %bias {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %gemm_bias_added = stablehlo.add %gemm, %gemm_bias : tensor<6x7xf32>

  // BatchNorm1d forward (training mode):
  // input: %gemm_bias_added: tensor<6x7xf32>
  // bn_weight: tensor<7xf32>, bn_bias: tensor<7xf32>
  // eps = 1e-5
  // Compute mean over batch dim 0: reduce over dim 0
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %init_mean = stablehlo.broadcast_in_dim %zero_f32 {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<f32>
  %mean = "stablehlo.reduce"(%gemm_bias_added, %init_mean) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>
  // mean = sum / 6
  %six_f32 = stablehlo.constant dense<6.0> : tensor<f32>
  %six_broadcast = stablehlo.broadcast_in_dim %six_f32 {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<7xf32>
  %mean_div = stablehlo.divide %mean, %six_broadcast : tensor<7xf32>

  // Compute variance: mean of (x - mean)^2 over batch dim 0
  // Broadcast mean to shape [6,7]
  %mean_broadcast = stablehlo.broadcast_in_dim %mean_div {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %diff = stablehlo.subtract %gemm_bias_added, %mean_broadcast : tensor<6x7xf32>
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<6x7xf32>
  %init_var = stablehlo.broadcast_in_dim %zero_f32 {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<f32>
  %var_sum = "stablehlo.reduce"(%diff_sq, %init_var) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>
  %var = stablehlo.divide %var_sum, %six_broadcast : tensor<7xf32>

  // Add eps to variance
  %eps = stablehlo.constant dense<0.00001> : tensor<f32>
  %eps_broadcast = stablehlo.broadcast_in_dim %eps {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<7xf32>
  %var_eps = stablehlo.add %var, %eps_broadcast : tensor<7xf32>

  // Compute rsqrt(var + eps)
  %inv_std = stablehlo.rsqrt %var_eps : tensor<7xf32>

  // Normalize: (x - mean) * inv_std
  %inv_std_broadcast = stablehlo.broadcast_in_dim %inv_std {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %normalized = stablehlo.multiply %diff, %inv_std_broadcast : tensor<6x7xf32>

  // Scale and shift: normalized * bn_weight + bn_bias
  %bn_weight_broadcast = stablehlo.broadcast_in_dim %bn_weight {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %bn_bias_broadcast = stablehlo.broadcast_in_dim %bn_bias {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %scaled = stablehlo.multiply %normalized, %bn_weight_broadcast : tensor<6x7xf32>
  %shifted = stablehlo.add %scaled, %bn_bias_broadcast : tensor<6x7xf32>

  // Multiply by scale parameter (broadcast scale from [1] to [6,7])
  %scale_broadcast = stablehlo.broadcast_in_dim %scale {broadcast_dimensions = array<i64: >} : (tensor<1xf32>) -> tensor<6x7xf32>
  %scaled_output = stablehlo.multiply %shifted, %scale_broadcast : tensor<6x7xf32>

  // Softmax along dim=1 (features dimension)
  // Softmax(x) = exp(x - max(x)) / sum(exp(x - max(x)))
  // Compute max over dim=1 (dim=1)
  %neg_inf = stablehlo.constant dense<0xFF800000> : tensor<f32>  // -inf
  %init_max = stablehlo.broadcast_in_dim %neg_inf {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<f32>
  %max_per_row = "stablehlo.reduce"(%scaled_output, %init_max) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %max = stablehlo.maximum %a, %b : tensor<f32>
      "stablehlo.return"(%max) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<6xf32>
  // Broadcast max_per_row to [6,7]
  %max_broadcast = stablehlo.broadcast_in_dim %max_per_row {broadcast_dimensions = array<i64: 0>} : (tensor<6xf32>) -> tensor<6x7xf32>
  // Subtract max for numerical stability
  %shifted_logits = stablehlo.subtract %scaled_output, %max_broadcast : tensor<6x7xf32>
  // exp(shifted_logits)
  %exp_logits = stablehlo.exponential %shifted_logits : tensor<6x7xf32>
  // sum exp over dim=1
  %zero_f32_2 = stablehlo.constant dense<0.0> : tensor<f32>
  %init_sum = stablehlo.broadcast_in_dim %zero_f32_2 {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<f32>
  %sum_exp = "stablehlo.reduce"(%exp_logits, %init_sum) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<6xf32>
  // Broadcast sum_exp to [6,7]
  %sum_exp_broadcast = stablehlo.broadcast_in_dim %sum_exp {broadcast_dimensions = array<i64: 0>} : (tensor<6xf32>) -> tensor<6x7xf32>
  // Divide exp_logits by sum_exp to get softmax output
  %softmax = stablehlo.divide %exp_logits, %sum_exp_broadcast : tensor<6x7xf32>

  "stablehlo.return"(%softmax) : tensor<6x7xf32>
}

func.func @main(%arg0: tensor<7x16x3x3xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x16x8x8xf32>) -> tensor<6x1x6x6xf32> {
  // %arg0: conv.weight (out_channels=7, in_channels=16, kernel=3x3)
  // %arg1: conv.bias (7)
  // %arg2: input (batch=6, in_channels=16, height=8, width=8)

  // Perform convolution:
  // dimension_numbers = [b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]
  // window_strides = [1,1], padding = 0, lhs_dilation = 1, rhs_dilation = 1
  %conv = "stablehlo.convolution"(%arg2, %arg0) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 1, 1>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x16x8x8xf32>, tensor<7x16x3x3xf32>) -> tensor<6x7x6x6xf32>

  // Add bias: broadcast bias from [7] to [6x7x6x6]
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<1x7x1x1xf32>
  %bias_broadcast_reshaped = stablehlo.reshape %bias_broadcast : (tensor<1x7x1x1xf32>) -> tensor<6x7x6x6xf32>  // reshape to match conv output shape by repeating dims

  // Actually, reshape alone won't repeat dims, so we must broadcast_in_dim directly to output shape:
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7x6x6xf32>

  %conv_bias = stablehlo.add %conv, %bias_broadcast : tensor<6x7x6x6xf32>

  // Compute minimum along channel dimension (dim=1), keepdim=True
  // stablehlo.reduce with init = +inf, reduce dimension = 1
  %inf = stablehlo.constant dense<0x7F800000> : tensor<f32>  // +inf
  %init = stablehlo.broadcast_in_dim %inf {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<f32>  // scalar init

  %min = "stablehlo.reduce"(%conv_bias, %init) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.minimum %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x7x6x6xf32>, tensor<f32>) -> tensor<6x6x6xf32>

  // Add back the reduced dimension as size 1 (keepdim=True)
  %min_keepdim = stablehlo.reshape %min : (tensor<6x6x6xf32>) -> tensor<6x1x6x6xf32>

  // Apply tanh twice
  %tanh1 = stablehlo.tanh %min_keepdim : tensor<6x1x6x6xf32>
  %tanh2 = stablehlo.tanh %tanh1 : tensor<6x1x6x6xf32>

  "stablehlo.return"(%tanh2) : tensor<6x1x6x6xf32>
}

func.func @main(%arg0: tensor<7x16x3x3xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x16x8x8xf32>) -> tensor<6x1x6x6xf32> {
  // Convolution dimension numbers for PyTorch Conv2d: NCHW input, OIHW kernel, NCFH output
  // stablehlo convolution dimension_numbers: [b, f, h, w] x [o, i, kh, kw] -> [b, f, oh, ow]
  // Here: batch=6, in_channels=16, out_channels=7, kernel=3x3, input=8x8
