    batch_group_count = 1 : i64
  } : (tensor<6x16x8x8xf32>, tensor<7x16x3x3xf32>) -> tensor<6x7x6x6xf32>

  // Add bias: broadcast bias from [7] to [6x7x6x6]
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7x6x6xf32>
  %conv_bias = stablehlo.add %conv, %bias_broadcast : tensor<6x7x6x6xf32>

  // Compute minimum along channel dimension (dim=1), keepdim=True
  // stablehlo.reduce with initial value +inf
  %inf = stablehlo.constant dense<0x7F800000> : tensor<f32>  // +inf float32
  %init = "stablehlo.broadcast_in_dim"(%inf) {broadcast_dimensions = array<i64: 0, 2, 3>} : (tensor<f32>) -> tensor<6x1x6x6xf32>
  %min = "stablehlo.reduce"(%conv_bias, %init) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.minimum %a, %b : tensor<f32>
      stablehlo.return %c : tensor<f32>
  }) {dimensions = array<i64: 1>} : (tensor<6x7x6x6xf32>, tensor<6x1x6x6xf32>) -> tensor<6x1x6x6xf32>

  // Apply tanh twice
  %tanh1 = stablehlo.tanh %min : tensor<6x1x6x6xf32>
  %tanh2 = stablehlo.tanh %tanh1 : tensor<6x1x6x6xf32>

  return %tanh2 : tensor<6x1x6x6xf32>
}

