  // mean = reduce mean over batch dim 0
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %init_mean = stablehlo.broadcast_in_dim %zero_f32 {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<>  // scalar 0.0
  %sum = stablehlo.reduce(%x, %init_mean) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %add = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %add : tensor<f32>
  }) {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>
  // mean = sum / 6
  %six_f32 = stablehlo.constant dense<6.0> : tensor<f32>
  %six_bcast = stablehlo.broadcast_in_dim %six_f32 {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<7xf32>
  %mean = stablehlo.divide %sum, %six_bcast : tensor<7xf32>

