  %init_mean = "stablehlo.broadcast_in_dim"(%zero_f32) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<f32>) -> tensor<6x7xf32>
  %sum = "stablehlo.reduce"(%bmm_bias_reshaped, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2, 3>} : (tensor<6x7x1x1xf32>, tensor<f32>) -> tensor<6x7xf32>

  // mean = sum / 1 = sum
  %mean = %sum : tensor<6x7xf32>

  // Compute variance: mean of (x - mean)^2 over dims [2,3]
  // Broadcast mean to (6x7x1x1)
  %mean_broadcast = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<6x7xf32>) -> tensor<6x7x1x1xf32>

  // x - mean
  %diff = stablehlo.subtract %bmm_bias_reshaped, %mean_broadcast : tensor<6x7x1x1xf32>

  // (x - mean)^2
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<6x7x1x1xf32>

  // sum of squared differences over dims [2,3]
  %zero_f32_2 = stablehlo.constant dense<0.0> : tensor<f32>
  %var_sum = "stablehlo.reduce"(%diff_sq, %zero_f32_2) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2, 3>} : (tensor<6x7x1x1xf32>, tensor<f32>) -> tensor<6x7xf32>

  // variance = var_sum / 1 = var_sum
  %variance = %var_sum : tensor<6x7xf32>

  // eps constant
  %eps = stablehlo.constant dense<0.00001> : tensor<f32>

  // variance + eps
  %var_eps = stablehlo.add %variance, %eps : tensor<6x7xf32>

  // sqrt(variance + eps)
  %stddev = stablehlo.sqrt %var_eps : tensor<6x7xf32>

  // Broadcast stddev to (6x7x1x1)
  %stddev_broadcast = "stablehlo.broadcast_in_dim"(%stddev) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<6x7xf32>) -> tensor<6x7x1x1xf32>

  // Normalize: (x - mean) / stddev
  %norm = stablehlo.divide %diff, %stddev_broadcast : tensor<6x7x1x1xf32>

  // InstanceNorm affine transform: scale=1, bias=0 (default)
  // So output = norm

  // Squeeze dims 2 and 3: (6x7x1x1) -> (6x7)
  %norm_reshaped = stablehlo.reshape %norm : (tensor<6x7x1x1xf32>) -> tensor<6x7xf32>

  // Add residual: x + y
  %add_residual = stablehlo.add %norm_reshaped, %arg3 : tensor<6x7xf32>

  // Multiply by y: (x + y) * y
  %output = stablehlo.multiply %add_residual, %arg3 : tensor<6x7xf32>

  return %output : tensor<6x7xf32>
}

func.func @main(%arg0: tensor<7x7xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x7xf32>, %arg3: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // %arg0 = bmm.weight (7x7)
  // %arg1 = bmm.bias (7)
  // %arg2 = input x (6x7)
  // %arg3 = input y (6x7)

  // Linear layer: x @ weight^T + bias
  // weight shape: 7x7, input shape: 6x7
  // We want (6x7) @ (7x7)^T = (6x7) @ (7x7) = (6x7)
  // So transpose weight to 7x7 (actually same shape), but dot_general contracting dims are last dim of lhs and last dim of rhs
  // We'll do dot_general with contracting dims [1] on lhs and [1] on rhs, batching dims [0] on lhs and rhs

  // Transpose weight to (7x7) -> (7x7) no change needed, but we want to contract rhs dim 1 (last dim)
  // Actually, stablehlo.dot_general expects lhs_contracting_dimensions and rhs_contracting_dimensions to be specified.
  // lhs: (6x7), rhs: (7x7)
  // Contract lhs dim 1 with rhs dim 1? That would be wrong, because rhs dim 1 is output dim.
  // Actually, for linear layer, we do x @ weight^T + bias
  // weight is (out_features x in_features) = (7x7)
  // So weight^T is (7x7)
  // So dot_general lhs: (6x7), rhs: (7x7)
  // Contract lhs dim 1 with rhs dim 0 (in_features)
  // So lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]
  // Result shape: (6x7) (batch 6, output 7)

  %weight_t = "stablehlo.transpose"(%arg0) {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>
  %bmm_out = "stablehlo.dot_general"(%arg2, %weight_t) {dot_dimension_numbers = #stablehlo.dot<lhs_batching_dimensions = [0], rhs_batching_dimensions = [], lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>} : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

  // Add bias: broadcast bias (7) to (6x7)
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %bmm_out_bias = stablehlo.add %bmm_out, %bias_broadcast : tensor<6x7xf32>

  // InstanceNorm2d on x.unsqueeze(1).unsqueeze(1)
  // Input to instance norm shape: (N, C, H, W) = (6, 7, 1, 1)
  // So reshape (6x7) -> (6x7x1x1)
  %bmm_reshaped = stablehlo.reshape %bmm_out_bias : (tensor<6x7xf32>) -> tensor<6x7x1x1xf32>

  // Compute mean over spatial dims (2,3) for each (N,C)
  // mean = sum / (H*W) = sum / 1 = sum
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %init_mean = "stablehlo.broadcast_in_dim"(%zero_f32) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7x1x1xf32>
  %mean = "stablehlo.reduce"(%bmm_reshaped, %init_mean) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2, 3>} : (tensor<6x7x1x1xf32>, tensor<6x7x1x1xf32>) -> tensor<6x7x1x1xf32>

  // Compute variance: mean of squared difference
  %mean_broadcast = %mean  // shape (6x7x1x1)
  %diff = stablehlo.subtract %bmm_reshaped, %mean_broadcast : tensor<6x7x1x1xf32>
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<6x7x1x1xf32>

  %init_var = "stablehlo.broadcast_in_dim"(%zero_f32) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7x1x1xf32>
  %var = "stablehlo.reduce"(%diff_sq, %init_var) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2, 3>} : (tensor<6x7x1x1xf32>, tensor<6x7x1x1xf32>) -> tensor<6x7x1x1xf32>

  // variance = var / (H*W) = var / 1 = var
  // eps = 1e-5
  %eps = stablehlo.constant dense<0.00001> : tensor<f32>
  %eps_broadcast = "stablehlo.broadcast_in_dim"(%eps) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7x1x1xf32>
  %var_eps = stablehlo.add %var, %eps_broadcast : tensor<6x7x1x1xf32>

  // inv_std = rsqrt(var + eps)
  %inv_std = stablehlo.rsqrt %var_eps : tensor<6x7x1x1xf32>

  // normalized = (x - mean) * inv_std
  %normalized = stablehlo.multiply %diff, %inv_std : tensor<6x7x1x1xf32>

  // Squeeze dims 2 and 3: reshape (6x7x1x1) -> (6x7)
  %normalized_squeezed = stablehlo.reshape %normalized : (tensor<6x7x1x1xf32>) -> tensor<6x7xf32>

  // Add residual: normalized + y
  %add_residual = stablehlo.add %normalized_squeezed, %arg3 : tensor<6x7xf32>

  // Multiply by y
  %output = stablehlo.multiply %add_residual, %arg3 : tensor<6x7xf32>

  return %output : tensor<6x7xf32>
}

