  %t9 = stablehlo.log_plus_one %t8 : tensor<6x7xf32>
  %t10 = stablehlo.tanh %t9 : tensor<6x7xf32>
  %t11 = stablehlo.multiply %t7, %t10 : tensor<6x7xf32>

  return %t11 : tensor<6x7xf32>
}

