func.func @main(%arg0: tensor<6x7x8xf32>) -> tensor<6x8xi64> {
  // %min_val = reduce min over dimension 1 (dim=1) of %arg0
  %c_inf = stablehlo.constant dense<0x7F800000> : tensor<f32>  // +inf
  %min_val = "stablehlo.reduce"(%arg0, %c_inf) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %cmp = "stablehlo.compare"(%a, %b) {comparison_direction = #stablehlo<comparison_direction LT>, compare_type = #stablehlo<comparison_type FLOAT>} : (tensor<f32>, tensor<f32>) -> tensor<i1>
      %sel = "stablehlo.select"(%cmp, %a, %b) : (tensor<i1>, tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%sel) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x7x8xf32>, tensor<f32>) -> tensor<6x8xf32>

  // Create iota for dim=1 (size 7), shape [7]
  %iota_1d = "stablehlo.iota"() {iota_dimension = 0 : i64} : () -> tensor<7xi64>

  // Broadcast min_val from [6x8] to [6x7x8]
  %min_val_bcast = stablehlo.broadcast_in_dim %min_val
    {broadcast_dimensions = dense<[0,2]> : tensor<2xi64>} : tensor<6x8xf32> to tensor<6x7x8xf32>

  // Broadcast iota_1d from [7] to [6x7x8]
  %iota_bcast = stablehlo.broadcast_in_dim %iota_1d
    {broadcast_dimensions = dense<[1]> : tensor<1xi64>} : tensor<7xi64> to tensor<6x7x8xi64>

  // Compare %arg0 and %min_val_bcast for equality (f32)
  %eq = "stablehlo.compare"(%arg0, %min_val_bcast)
    {comparison_direction = #stablehlo<comparison_direction EQ>, compare_type = #stablehlo<comparison_type FLOAT>} : (tensor<6x7x8xf32>, tensor<6x7x8xf32>) -> tensor<6x7x8xi1>

  // Reduce with min over dimension 1 (dim=1) of iota_bcast, masked by eq
  // We want the minimal index i where arg0 == min_val along dim=1
  // Use a reduce with initial value = 7 (out of range), and select min index where eq is true, else keep current min index

  %c_7 = stablehlo.constant dense<7> : tensor<i64>

  %argmin = "stablehlo.reduce"(%iota_bcast, %c_7, %eq) ({
    ^bb0(%idx: tensor<i64>, %cur_min: tensor<i64>, %mask: tensor<i1>):
      // If mask true, candidate = idx else cur_min
      %cand = "stablehlo.select"(%mask, %idx, %cur_min) : (tensor<i1>, tensor<i64>, tensor<i64>) -> tensor<i64>
      // min(cand, cur_min)
      %cmp = "stablehlo.compare"(%cand, %cur_min)
        {comparison_direction = #stablehlo<comparison_direction LT>, compare_type = #stablehlo<comparison_type NOTYPE>} : (tensor<i64>, tensor<i64>) -> tensor<i1>
      %res = "stablehlo.select"(%cmp, %cand, %cur_min) : (tensor<i1>, tensor<i64>, tensor<i64>) -> tensor<i64>
      "stablehlo.return"(%res) : (tensor<i64>) -> ()
  }) {dimensions = array<i64: 1>, mask = %eq} : (tensor<6x7x8xi64>, tensor<i64>, tensor<6x7x8xi1>) -> tensor<6x8xi64>

  return %argmin : tensor<6x8xi64>
}

func.func @main(%arg0: tensor<6x7x8xf32>) -> tensor<6x8xi64> {
  // %c_init = +inf scalar for f32, used as initial value for min reduction
  %c_init = stablehlo.constant dense<0x7F800000> : tensor<f32>

  // %iota = iota tensor for indices along dimension 1 (size 7)
  // shape: [7], element type i64
  %iota = "stablehlo.iota"() {iota_dimension = 0 : i64} : () -> tensor<7xi64>

  // We want to reduce along dimension 1 (the second dimension) of %arg0,
  // which has shape [6,7,8].
  // The output shape after reducing dim 1 is [6,8].
  // The reduction will find the minimum value and the index of that minimum along dim 1.

  // Reshape %iota to [1,7,1] to broadcast along batch and dim2
  %iota_reshaped = "stablehlo.reshape"(%iota) : (tensor<7xi64>) -> tensor<1x7x1xi64>

  // Broadcast %iota_reshaped to [6,7,8]
  %iota_broadcasted = "stablehlo.broadcast_in_dim"(%iota_reshaped) {broadcast_dimensions = array<i64: 1>} : (tensor<1x7x1xi64>) -> tensor<6x7x8xi64>

  // Initial index value for argmin is 0 (rank 0 scalar)
  %c_zero = stablehlo.constant dense<0> : tensor<i64>

  // Initial min value is +inf (rank 0 scalar)
  %c_init_scalar = stablehlo.constant dense<0x7F800000> : tensor<f32>

  // We perform a reduce with two inputs: the values and the indices.
  // Inputs to reduce: %arg0 (f32), %iota_broadcasted (i64)
  // Initial values: %c_init_scalar (f32), %c_zero (i64)
  // Reduce along dimension 1

  %init_tuple = stablehlo.tuple(%c_init_scalar, %c_zero) : (tensor<f32>, tensor<i64>) -> tuple<tensor<f32>, tensor<i64>>

  %reduce_result = "stablehlo.reduce"(%arg0, %iota_broadcasted, %c_init_scalar, %c_zero) ({
    ^bb0(%acc_val: tensor<f32>, %acc_idx: tensor<i64>, %elem_val: tensor<f32>, %elem_idx: tensor<i64>):
      // Compare elem_val < acc_val
      %cmp = "stablehlo.compare"(%elem_val, %acc_val) {comparison_direction = #stablehlo<comparison_direction LT>, compare_type = #stablehlo<comparison_type FLOAT>} : (tensor<f32>, tensor<f32>) -> tensor<i1>
      // Select new min val: if cmp true then elem_val else acc_val
      %sel_val = "stablehlo.select"(%cmp, %elem_val, %acc_val) : (tensor<i1>, tensor<f32>, tensor<f32>) -> tensor<f32>
      // Select new min idx: if cmp true then elem_idx else acc_idx
      %sel_idx = "stablehlo.select"(%cmp, %elem_idx, %acc_idx) : (tensor<i1>, tensor<i64>, tensor<i64>) -> tensor<i64>
      "stablehlo.return"(%sel_val, %sel_idx) : (tensor<f32>, tensor<i64>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x7x8xf32>, tensor<6x7x8xi64>, tensor<f32>, tensor<i64>) -> (tensor<6x8xf32>, tensor<6x8xi64>)

  // %reduce_result is a tuple of (min_values, min_indices)
  %min_indices = stablehlo.get_tuple_element %reduce_result {index = 1 : i32} : tuple<tensor<6x8xf32>, tensor<6x8xi64>>

  // Return the indices tensor of shape [6,8] with element type i64
  return %min_indices : tensor<6x8xi64>
}

