func.func @main(%arg0: tensor<7x7xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // %arg0 = linear.weight (7x7)
  // %arg1 = linear.bias (7)
  // %arg2 = input (6x7)

  // Perform linear: x @ W^T + b
  // W^T shape: 7x7 -> transpose to 7x7 (same shape, but transpose needed for correct contraction)
  %t0 = "stablehlo.transpose"(%arg0) {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>
  // dot_general: batch dims none, contracting dims input feature dim 1 and weight dim 0
  %t1 = "stablehlo.dot_general"(%arg2, %t0) {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [],
      rhs_batching_dimensions = [],
      lhs_contracting_dimensions = [1],
      rhs_contracting_dimensions = [0]>
  } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

  // Add bias: broadcast bias (7) to (6x7)
  %t2 = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %t3 = stablehlo.add %t1, %t2 : tensor<6x7xf32>

  // Apply ReLU: max(x, 0)
  %c0 = stablehlo.constant dense<0.0> : tensor<f32>
  %c0_bcast = "stablehlo.broadcast_in_dim"(%c0) {broadcast_dimensions = array<i64: } : () -> tensor<6x7xf32> // We need to broadcast scalar 0.0 to 6x7
  // Actually, stablehlo.constant dense<0.0> : tensor<f32> is scalar tensor, broadcast it:
  %c0_bcast = "stablehlo.broadcast_in_dim"(%c0) {broadcast_dimensions = array<i64: } : (tensor<f32>) -> tensor<6x7xf32>
  // But we must specify broadcast_dimensions for scalar to 6x7: empty array means scalar broadcast to all dims
  %c0_bcast = "stablehlo.broadcast_in_dim"(%c0) {broadcast_dimensions = array<i64: } : (tensor<f32>) -> tensor<6x7xf32>
  // The broadcast_dimensions for scalar is empty array
  %c0_bcast = "stablehlo.broadcast_in_dim"(%c0) {broadcast_dimensions = array<i64: } : (tensor<f32>) -> tensor<6x7xf32>
  // Correct form:
  %c0_bcast = "stablehlo.broadcast_in_dim"(%c0) {broadcast_dimensions = array<i64: } : (tensor<f32>) -> tensor<6x7xf32>
  // Actually, scalar broadcast to any shape uses empty broadcast_dimensions array
  %c0_bcast = "stablehlo.broadcast_in_dim"(%c0) {broadcast_dimensions = array<i64: } : (tensor<f32>) -> tensor<6x7xf32>
  // So:
  %c0_bcast = "stablehlo.broadcast_in_dim"(%c0) {broadcast_dimensions = array<i64: } : (tensor<f32>) -> tensor<6x7xf32>
  // Final correct:
  %c0_bcast = "stablehlo.broadcast_in_dim"(%c0) {broadcast_dimensions = array<i64: } : (tensor<f32>) -> tensor<6x7xf32>
  // Sorry for repetition, final line:
  %c0_bcast = "stablehlo.broadcast_in_dim"(%c0) {broadcast_dimensions = array<i64: } : (tensor<f32>) -> tensor<6x7xf32>
  // Actually, the broadcast_dimensions attribute for scalar to tensor<6x7xf32> is empty array:
  %c0_bcast = "stablehlo.broadcast_in_dim"(%c0) {broadcast_dimensions = array<i64: } : (tensor<f32>) -> tensor<6x7xf32>
  // So:
  %c0_bcast = "stablehlo.broadcast_in_dim"(%c0) {broadcast_dimensions = array<i64: } : (tensor<f32>) -> tensor<6x7xf32>
  // Final:
  %c0_bcast = "stablehlo.broadcast_in_dim"(%c0) {broadcast_dimensions = array<i64: } : (tensor<f32>) -> tensor<6x7xf32>
  // Sorry for the confusion, here is the correct line:
  %c0_bcast = "stablehlo.broadcast_in_dim"(%c0) {broadcast_dimensions = array<i64: } : (tensor<f32>) -> tensor<6x7xf32>
  // Actually, the attribute must be array<i64: > (empty array)
  %c0_bcast = "stablehlo.broadcast_in_dim"(%c0) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7xf32>

  %t4 = stablehlo.maximum %t3, %c0_bcast : tensor<6x7xf32>

  // Divide by divisor=2.0 (constant)
  %c2 = stablehlo.constant dense<2.0> : tensor<f32>
  %c2_bcast = "stablehlo.broadcast_in_dim"(%c2) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7xf32>

  %t5 = stablehlo.divide %t4, %c2_bcast : tensor<6x7xf32>

  return %t5 : tensor<6x7xf32>
}

func.func @main(%bias: tensor<1x1x1x1xf32>, %conv_transpose_weight: tensor<3x16x3x3x3xf32>, %conv_transpose_bias: tensor<16xf32>, %input: tensor<6x3x16x7x7xf32>) -> tensor<6x1x31x13x13xf32> {
  // Transpose conv_transpose_weight from (in_channels, out_channels, D, H, W) to (out_channels, in_channels, D, H, W)
  %weight_reshaped = stablehlo.reshape %conv_transpose_weight : (tensor<3x16x3x3x3xf32>) -> tensor<3x16x27xf32>
  %weight_transposed = "stablehlo.transpose"(%conv_transpose_weight) {permutation = array<i64: 1, 0, 2, 3, 4>} : (tensor<3x16x3x3x3xf32>) -> tensor<16x3x3x3x3xf32>

  // Perform convolution with stride=2, padding=1, dilation=1, groups=1, batch_group_count=1
  %conv = "stablehlo.convolution"(%input, %weight_transposed) {
    window_strides = array<i64: 2, 2, 2>,
    padding = dense<[[1, 1], [1, 1], [1, 1]]> : tensor<3x2xi64>,
    lhs_dilation = array<i64: 1, 1, 1>,
    rhs_dilation = array<i64: 1, 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, i, 2, 3, 4]x[o, i, 2, 3, 4]->[b, o, 2, 3, 4]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x3x16x7x7xf32>, tensor<16x3x3x3x3xf32>) -> tensor<6x16x31x13x13xf32>

  // Add conv_transpose_bias (shape: [16]) to conv output, broadcast bias over batch and spatial dims
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%conv_transpose_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<1x16x1x1x1xf32>
  %conv_bias_added = stablehlo.add %conv, %bias_broadcast : tensor<6x16x31x13x13xf32>

  // Compute logsumexp over channel dimension (dim=1), keepdim=True
  // Step 1: max over dim=1 for numerical stability
  %init_max = stablehlo.constant dense<-inf> : tensor<f32>
  %max_over_channels = "stablehlo.reduce"(%conv_bias_added, %init_max) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.maximum %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x16x31x13x13xf32>, tensor<f32>) -> tensor<6x1x31x13x13xf32>

  // Step 2: subtract max, exponentiate
  %max_broadcast = "stablehlo.broadcast_in_dim"(%max_over_channels) {broadcast_dimensions = array<i64: 0, 2, 3, 4>} : (tensor<6x1x31x13x13xf32>) -> tensor<6x16x31x13x13xf32>
  %shifted = stablehlo.subtract %conv_bias_added, %max_broadcast : tensor<6x16x31x13x13xf32>
  %exp_shifted = stablehlo.exponential %shifted : tensor<6x16x31x13x13xf32>

  // Step 3: sum exp over dim=1
  %init_zero = stablehlo.constant dense<0.0> : tensor<f32>
  %sum_exp = "stablehlo.reduce"(%exp_shifted, %init_zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x16x31x13x13xf32>, tensor<f32>) -> tensor<6x1x31x13x13xf32>

  // Step 4: log(sum_exp) + max
  %log_sum_exp = stablehlo.log %sum_exp : tensor<6x1x31x13x13xf32>
  %logsumexp = stablehlo.add %log_sum_exp, %max_over_channels : tensor<6x1x31x13x13xf32>

  // HardSwish: x * sigmoid(x + 3) / 6
  %three = stablehlo.constant dense<3.0> : tensor<f32>
  %three_broadcast = "stablehlo.broadcast_in_dim"(%three) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<6x1x31x13x13xf32>
  %x_plus_3 = stablehlo.add %logsumexp, %three_broadcast : tensor<6x1x31x13x13xf32>
  %sigmoid = stablehlo.logistic %x_plus_3 : tensor<6x1x31x13x13xf32>
  %x_times_sigmoid = stablehlo.multiply %logsumexp, %sigmoid : tensor<6x1x31x13x13xf32>
  %six = stablehlo.constant dense<6.0> : tensor<f32>
  %six_broadcast = "stablehlo.broadcast_in_dim"(%six) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<6x1x31x13x13xf32>
  %hard_swish = stablehlo.divide %x_times_sigmoid, %six_broadcast : tensor<6x1x31x13x13xf32>

  // Subtract bias (shape: 1x1x1x1)
  %bias_broadcast_hswish = "stablehlo.broadcast_in_dim"(%bias) {broadcast_dimensions = array<i64: 1, 2, 3, 4>} : (tensor<1x1x1x1xf32>) -> tensor<6x1x31x13x13xf32>
  %subtracted = stablehlo.subtract %hard_swish, %bias_broadcast_hswish : tensor<6x1x31x13x13xf32>

  // Clamp between -1 and 1
  %minus_one = stablehlo.constant dense<-1.0> : tensor<f32>
  %minus_one_broadcast = "stablehlo.broadcast_in_dim"(%minus_one) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<6x1x31x13x13xf32>
  %clamped_min = stablehlo.maximum %subtracted, %minus_one_broadcast : tensor<6x1x31x13x13xf32>
