  %one_broadcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: 0, 1, 2, 3, 4>} : (tensor<f32>) -> tensor<6x1x31x13x13xf32>
  %denominator = stablehlo.add %one_broadcast, %exp_neg : tensor<6x1x31x13x13xf32>
  %sigmoid = stablehlo.divide %one_broadcast, %denominator : tensor<6x1x31x13x13xf32>

  // multiply x * sigmoid(x + 3)
  %mul = stablehlo.multiply %lse, %sigmoid : tensor<6x1x31x13x13xf32>

