  %rev_w_reshape2 = stablehlo.reshape %rev_w_reshape1 : (tensor<3x16x27xf32>) -> tensor<16x3x27xf32>
  %rev_w = stablehlo.reshape %rev_w_reshape2 : (tensor<16x3x27xf32>) -> tensor<16x3x3x3x3xf32>

