  %init_tensor = stablehlo.broadcast_in_dim %init_zero {broadcast_dimensions = array<i64: } : () -> tensor<f32> // will create scalar zero for reduce init
  %init = stablehlo.constant dense<0.0> : tensor<f32>
  %sum = "stablehlo.reduce"(%exp, %init) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
