  %log_sum_reshape = stablehlo.reshape %log_sum : (tensor<6x31x13x13xf32>) -> tensor<6x1x31x13x13xf32>

  // Compute x + 3
  %three = stablehlo.constant dense<3.0> : tensor<f32>
