  // Compute sigmoid(x + 3) = 1 / (1 + exp(-x_plus_3))
  %neg_x_plus_3 = stablehlo.negate %x_plus_3 : tensor<6x1x31x13x13xf32>
  %exp_neg = stablehlo.exponential %neg_x_plus_3 : tensor<6x1x31x13x13xf32>
