  %c0 = stablehlo.constant dense<0.0> : tensor<f32>
  %init = "stablehlo.broadcast_in_dim"(%c0) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<1xf32>
  %res = "stablehlo.reduce_window"(%arg0, %init) ({
