  }) {window_dimensions = array<i64: 1, 1, 11, 11>, window_strides = array<i64: 1, 1, 1, 1>, padding = dense<[[0, 0], [0, 0], [0, 0], [0, 0]]> : tensor<4x2xi64>} : (tensor<16x16x16x16xf32>, tensor<f32>) -> tensor<16x16x6x6xf32>
  %res_div = stablehlo.divide %res, %c121_bcast : tensor<16x16x6x6xf32>
  %slice = "stablehlo.reduce_window"(%res_div, %init) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      stablehlo.return %a : tensor<f32>
  }) {window_dimensions = array<i64: 1, 1, 6, 6>, window_strides = array<i64: 1, 1, 6, 6>, padding = dense<[[0, 0], [0, 0], [0, 0], [0, 0]]> : tensor<4x2xi64>} : (tensor<16x16x6x6xf32>, tensor<f32>) -> tensor<16x16x1x1xf32>
  return %slice : tensor<16x16x1x1xf32>
}

func.func @main(%arg0: tensor<16x16x16x16xf32>) -> tensor<16x16x1x1xf32> {
  %c121 = stablehlo.constant dense<121.0> : tensor<f32>
  %c121_bcast = "stablehlo.broadcast_in_dim"(%c121) {broadcast_dimensions = array<i64: 3>} : (tensor<f32>) -> tensor<1x1x1x1xf32>
  %init = stablehlo.constant dense<0.0> : tensor<f32>
