func.func @main(%scale: tensor<7xf32>, %weight: tensor<7x7xf32>, %bias: tensor<7xf32>, %bn_weight: tensor<7xf32>, %bn_bias: tensor<7xf32>, %input: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // %x1 = gemm: input @ %input (6x7), weight @ %weight (7x7)
  // dot_general with contracting dims: input dim 1 and weight dim 0
  %x1 = "stablehlo.dot_general"(%input, %weight) {dot_dimension_numbers = #stablehlo.dot<lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>} : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

  // %x2 = element-wise multiply by scale (broadcast scale from [7] to [6x7])
  %scale_broadcast = "stablehlo.broadcast_in_dim"(%scale) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %x2 = stablehlo.multiply %x1, %scale_broadcast : tensor<6x7xf32>

  // BatchNorm1d forward (training mode):
  // Given input x2: [batch=6, features=7]
  // Compute mean over batch dimension (dim 0)
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %init_mean = stablehlo.constant dense<0.0> : tensor<f32>
  %mean = "stablehlo.reduce"(%x2, %init_mean) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>
  // mean = sum / 6
  %six_f32 = stablehlo.constant dense<6.0> : tensor<f32>
  %six_broadcast = "stablehlo.broadcast_in_dim"(%six_f32) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<7xf32>
  %mean_scaled = stablehlo.divide %mean, %six_broadcast : tensor<7xf32>

  // Compute variance over batch dimension: var = mean((x - mean)^2)
  // First compute (x - mean)
  %mean_broadcast = "stablehlo.broadcast_in_dim"(%mean_scaled) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %x_centered = stablehlo.subtract %x2, %mean_broadcast : tensor<6x7xf32>
  // square (x - mean)
  %x_centered_sq = stablehlo.multiply %x_centered, %x_centered : tensor<6x7xf32>
  // sum over batch dim 0
  %init_var = stablehlo.constant dense<0.0> : tensor<f32>
  %var_sum = "stablehlo.reduce"(%x_centered_sq, %init_var) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>
  // var = var_sum / 6
  %var = stablehlo.divide %var_sum, %six_broadcast : tensor<7xf32>

  // eps = 1e-5 constant
  %eps = stablehlo.constant dense<0.00001> : tensor<f32>
  // var + eps
  %var_eps = stablehlo.add %var, %eps : tensor<7xf32>
  // sqrt(var + eps)
  %stddev = stablehlo.sqrt %var_eps : tensor<7xf32>

  // Normalize: (x - mean) / stddev
  %stddev_broadcast = "stablehlo.broadcast_in_dim"(%stddev) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %x_norm = stablehlo.divide %x_centered, %stddev_broadcast : tensor<6x7xf32>

  // Apply affine transform: y = bn_weight * x_norm + bn_bias
  %bn_weight_broadcast = "stablehlo.broadcast_in_dim"(%bn_weight) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %bn_bias_broadcast = "stablehlo.broadcast_in_dim"(%bn_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %y_mul = stablehlo.multiply %x_norm, %bn_weight_broadcast : tensor<6x7xf32>
  %y = stablehlo.add %y_mul, %bn_bias_broadcast : tensor<6x7xf32>

  // Return final output
  return %y : tensor<6x7xf32>
}

