func.func @main(%scale: tensor<7xf32>, %weight: tensor<7x7xf32>, %bias: tensor<7xf32>, %bn_weight: tensor<7xf32>, %bn_bias: tensor<7xf32>, %input: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // %x = gemm(input, weight) + bias
  // gemm: input (6x7) * weight (7x7) -> (6x7)
  %x_gemm = "stablehlo.dot_general"(%input, %weight) {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [],
      rhs_batching_dimensions = [],
      lhs_contracting_dimensions = [1],
      rhs_contracting_dimensions = [0]>
  } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

  // broadcast bias (7) to (6x7)
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%bias) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>

  %x_bias = stablehlo.add %x_gemm, %bias_broadcast : tensor<6x7xf32>

  // broadcast scale (7) to (6x7)
  %scale_broadcast = "stablehlo.broadcast_in_dim"(%scale) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>

  // x = x * scale
  %x_scaled = stablehlo.multiply %x_bias, %scale_broadcast : tensor<6x7xf32>

  // BatchNorm1d forward training mode:
  // Compute mean over batch dimension (dim 0)
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %mean = "stablehlo.reduce"(%x_scaled, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>

  // Compute mean / batch_size (6)
  %batch_size_const = stablehlo.constant dense<6.0> : tensor<f32>
  %mean_div = stablehlo.divide %mean, %batch_size_const : tensor<7xf32>

  // Broadcast mean to (6x7)
  %mean_broadcast = "stablehlo.broadcast_in_dim"(%mean_div) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>

  // x_centered = x_scaled - mean
  %x_centered = stablehlo.subtract %x_scaled, %mean_broadcast : tensor<6x7xf32>

  // Compute variance: mean of squared differences
  %x_centered_sq = stablehlo.multiply %x_centered, %x_centered : tensor<6x7xf32>

  %var_sum = "stablehlo.reduce"(%x_centered_sq, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>

  %var = stablehlo.divide %var_sum, %batch_size_const : tensor<7xf32>

  // eps constant for numerical stability
  %eps = stablehlo.constant dense<0.00001> : tensor<f32>

  // var + eps
  %var_eps = stablehlo.add %var, %eps : tensor<7xf32>

  // sqrt(var + eps)
  %stddev = stablehlo.sqrt %var_eps : tensor<7xf32>

  // Broadcast stddev to (6x7)
  %stddev_broadcast = "stablehlo.broadcast_in_dim"(%stddev) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>

  // Normalize: x_norm = x_centered / stddev
  %x_norm = stablehlo.divide %x_centered, %stddev_broadcast : tensor<6x7xf32>

  // Broadcast bn_weight and bn_bias to (6x7)
  %bn_weight_broadcast = "stablehlo.broadcast_in_dim"(%bn_weight) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %bn_bias_broadcast = "stablehlo.broadcast_in_dim"(%bn_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>

  // Apply scale and shift: y = x_norm * bn_weight + bn_bias
  %y_scaled = stablehlo.multiply %x_norm, %bn_weight_broadcast : tensor<6x7xf32>
  %y = stablehlo.add %y_scaled, %bn_bias_broadcast : tensor<6x7xf32>

  return %y : tensor<6x7xf32>
}

func.func @main(%arg0: tensor<7xf32>, %arg1: tensor<7x7xf32>, %arg2: tensor<7xf32>, %arg3: tensor<7xf32>, %arg4: tensor<7xf32>, %arg5: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // %arg0 = scale (7)
  // %arg1 = gemm.weight (7x7)
  // %arg2 = gemm.bias (7)
  // %arg3 = bn.weight (7)
  // %arg4 = bn.bias (7)
  // %arg5 = input (6x7)

  // GEMM: x @ W^T + b
  // gemm.weight shape is (7x7) = (out_features x in_features)
  // input shape is (6x7) = (batch x in_features)
  // We want: (6x7) = input (6x7) dot gemm.weight^T (7x7)
  // So transpose gemm.weight to (7x7) -> (7x7) (actually same shape, but transpose swaps dims)
  // Actually gemm.weight is (7x7), so transpose dims [1,0]
  %w_t = "stablehlo.transpose"(%arg1) {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>

  // dot_general with contracting dims: input last dim (1), weight first dim (0)
  // no batching dims
  %dot = "stablehlo.dot_general"(%arg5, %w_t) {dot_dimension_numbers = #stablehlo.dot<lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>} : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

  // add bias: broadcast bias (7) to (6x7)
  %bias_bcast = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %add_bias = stablehlo.add %dot, %bias_bcast : tensor<6x7xf32>

  // multiply by scale: broadcast scale (7) to (6x7)
  %scale_bcast = "stablehlo.broadcast_in_dim"(%arg0) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %scaled = stablehlo.multiply %add_bias, %scale_bcast : tensor<6x7xf32>

  // BatchNorm1d forward (training mode):
  // input: (6x7)
  // compute mean over batch dim 0 -> shape (7)
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %init_mean = "stablehlo.broadcast_in_dim"(%zero_f32) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<7xf32>
  %mean = "stablehlo.reduce"(%scaled, %init_mean) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<7xf32>) -> tensor<7xf32>

  // compute variance: mean of squared difference
  // diff = x - mean (broadcast mean to (6x7))
  %mean_bcast = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %diff = stablehlo.subtract %scaled, %mean_bcast : tensor<6x7xf32>
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<6x7xf32>

  %init_var = "stablehlo.broadcast_in_dim"(%zero_f32) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<7xf32>
  %var = "stablehlo.reduce"(%diff_sq, %init_var) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<7xf32>) -> tensor<7xf32>

  // divide sum by N=6 (batch size)
  %six = stablehlo.constant dense<6.0> : tensor<f32>
  %var_div = stablehlo.divide %var, %six : tensor<7xf32>

  // add eps=1e-5 to variance
  %eps = stablehlo.constant dense<0.00001> : tensor<f32>
  %eps_bcast = "stablehlo.broadcast_in_dim"(%eps) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<7xf32>
  %var_eps = stablehlo.add %var_div, %eps_bcast : tensor<7xf32>

  // sqrt variance + eps
  %stddev = stablehlo.sqrt %var_eps : tensor<7xf32>

  // normalize: (x - mean) / stddev
  // broadcast stddev to (6x7)
  %stddev_bcast = "stablehlo.broadcast_in_dim"(%stddev) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %norm = stablehlo.divide %diff, %stddev_bcast : tensor<6x7xf32>

  // apply bn.weight (gamma) and bn.bias (beta)
  // broadcast bn.weight and bn.bias to (6x7)
  %bn_weight_bcast = "stablehlo.broadcast_in_dim"(%arg3) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %bn_bias_bcast = "stablehlo.broadcast_in_dim"(%arg4) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>

  %scaled_norm = stablehlo.multiply %norm, %bn_weight_bcast : tensor<6x7xf32>
  %out = stablehlo.add %scaled_norm, %bn_bias_bcast : tensor<6x7xf32>

  return %out : tensor<6x7xf32>
}

func.func @main(%arg0: tensor<7xf32>, %arg1: tensor<7x7xf32>, %arg2: tensor<7xf32>, %arg3: tensor<7xf32>, %arg4: tensor<7xf32>, %arg5: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // %arg0 = scale (7,)
  // %arg1 = gemm.weight (7x7)
  // %arg2 = gemm.bias (7,)
  // %arg3 = bn.weight (7,)
  // %arg4 = bn.bias (7,)
  // %arg5 = input (6x7)

  // Step 1: GEMM: x @ W^T + b
  // gemm.weight shape is (7x7) = (out_features x in_features)
  // input shape is (6x7) = (batch_size x in_features)
  // We want: (6x7) @ (7x7)^T = (6x7) @ (7x7) = (6x7)
  // So transpose gemm.weight to (7x7) -> (7x7) (actually same shape, but transpose swaps dims)
  %t0 = "stablehlo.transpose"(%arg1) {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>
  %dot = "stablehlo.dot_general"(%arg5, %t0) {dot_dimension_numbers = #stablehlo.dot<lhs_batching_dimensions = [0], rhs_batching_dimensions = [], lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>} : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

