  %scale_broadcast = "stablehlo.broadcast_in_dim"(%arg0) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %scaled = stablehlo.multiply %add_bias, %scale_broadcast : tensor<6x7xf32>

  // Step 3: BatchNorm1d forward (training mode)
