  %mean = "stablehlo.reduce"(%scaled, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>): 
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>

  // Compute variance: mean of squared differences
  // First compute (x - mean)
  %mean_broadcast = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %diff = stablehlo.subtract %scaled, %mean_broadcast : tensor<6x7xf32>
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<6x7xf32>

  // variance = mean of diff_sq over batch dimension (0)
  %var = "stablehlo.reduce"(%diff_sq, %zero) ({
