      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>

  // Divide sums by N (batch size = 6)
  %six = stablehlo.constant dense<6.0> : tensor<f32>
  %six_broadcast = "stablehlo.broadcast_in_dim"(%six) {broadcast_dimensions = array<i64: >} : (tensor<>) -> tensor<> // scalar broadcast no dims
  // Broadcast scalar 6.0 to shape (7,)
  %six_7 = "stablehlo.broadcast_in_dim"(%six) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<7xf32>

  %mean_div = stablehlo.divide %mean, %six_7 : tensor<7xf32>
  %var_div = stablehlo.divide %var, %six_7 : tensor<7xf32>

  // Actually, the reduce sums the elements, so to get mean we divide by 6
  // But we broadcast 6.0 to (7,) for elementwise divide

  // Add epsilon to variance
  %eps = stablehlo.constant dense<1.000000e-05> : tensor<f32>
  %eps_7 = "stablehlo.broadcast_in_dim"(%eps) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<7xf32>
  %var_eps = stablehlo.add %var_div, %eps_7 : tensor<7xf32>

  // Compute rsqrt(variance + eps)
  %inv_std = stablehlo.rsqrt %var_eps : tensor<7xf32>

  // Normalize: (x - mean) * inv_std
  %diff_norm = stablehlo.multiply %diff, "stablehlo.broadcast_in_dim"(%inv_std) {broadcast_dimensions = array<i64: 1>} : (tensor<6x7xf32>, tensor<7xf32>) -> tensor<6x7xf32>

  // Scale and shift: y = weight * normalized + bias
  %weight_broadcast = "stablehlo.broadcast_in_dim"(%arg3) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %bias_bn_broadcast = "stablehlo.broadcast_in_dim"(%arg4) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %scaled_norm = stablehlo.multiply %diff_norm, %weight_broadcast : tensor<6x7xf32>
  %out = stablehlo.add %scaled_norm, %bias_bn_broadcast : tensor<6x7xf32>

  return %out : tensor<6x7xf32>
}

