  %bias_broadcast = "stablehlo.broadcast_in_dim"(%group_norm_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %scaled = stablehlo.multiply %normalized, %weight_broadcast : tensor<16x16xf32>
  %shifted = stablehlo.add %scaled, %bias_broadcast : tensor<16x16xf32>

