  // sigmoid(x) = 1 / (1 + exp(-x))
  %neg_shifted = stablehlo.negate %shifted : tensor<16x16xf32>
  %exp_neg = stablehlo.exponential %neg_shifted : tensor<16x16xf32>
  %one_16x16 = stablehlo.constant dense<1.0> : tensor<16x16xf32>
  %denom = stablehlo.add %one_16x16, %exp_neg : tensor<16x16xf32>
  %sigmoid = stablehlo.divide %one_16x16, %denom : tensor<16x16xf32>
  %swish1 = stablehlo.multiply %shifted, %sigmoid : tensor<16x16xf32>

  // Multiply by multiply_weight (broadcast multiply_weight from [16] to [16x16])
  %multiply_weight_broadcast = "stablehlo.broadcast_in_dim"(%multiply_weight) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
