  %neg_multiplied = stablehlo.negate %multiplied : tensor<16x16xf32>
  %exp_neg_multiplied = stablehlo.exponential %neg_multiplied : tensor<16x16xf32>
  %denom2 = stablehlo.add %one_16x16, %exp_neg_multiplied : tensor<16x16xf32>
  %sigmoid2 = stablehlo.divide %one_16x16, %denom2 : tensor<16x16xf32>
  %swish2 = stablehlo.multiply %multiplied, %sigmoid2 : tensor<16x16xf32>

  "stablehlo.return"(%swish2) : tensor<16x16xf32>
}

