  %three_broadcast = "stablehlo.broadcast_in_dim"(%three) {broadcast_dimensions = array<i64:}> : (tensor<f32>) -> tensor<6x7x4x4xf32>
  %x_plus_3 = stablehlo.add %conv_plus_bias, %three_broadcast : tensor<6x7x4x4xf32>

  // relu6(x + 3) = min(max(0, x+3), 6)
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %zero_broadcast = "stablehlo.broadcast_in_dim"(%zero) {broadcast_dimensions = array<i64:}> : (tensor<f32>) -> tensor<6x7x4x4xf32>
  %six = stablehlo.constant dense<6.0> : tensor<f32>
  %six_broadcast = "stablehlo.broadcast_in_dim"(%six) {broadcast_dimensions = array<i64:}> : (tensor<f32>) -> tensor<6x7x4x4xf32>

  %max_0_xplus3 = stablehlo.maximum %x_plus_3, %zero_broadcast : tensor<6x7x4x4xf32>
  %relu6 = stablehlo.minimum %max_0_xplus3, %six_broadcast : tensor<6x7x4x4xf32>

