func.func @main(%arg0: tensor<16xf32>, %arg1: tensor<16x16xf32>, %arg2: tensor<16xf32>, %arg3: tensor<16xf32>, %arg4: tensor<16xf32>, %arg5: tensor<16x16xf32>) -> tensor<16x16xf32> {
  // %arg0 = bias (tensor<16xf32>)
  // %arg1 = matmul.weight (tensor<16x16xf32>)
  // %arg2 = matmul.bias (tensor<16xf32>)
  // %arg3 = group_norm.weight (tensor<16xf32>)
  // %arg4 = group_norm.bias (tensor<16xf32>)
  // %arg5 = input x (tensor<16x16xf32>)

  // Step 1: matmul: x @ weight^T + bias
  // matmul.weight shape: [16,16], input shape: [16,16]
  // We want to do dot_general with contracting dims: input last dim (1), weight last dim (1)
  // But weight needs to be transposed to [16,16] -> [16,16], so we transpose weight to swap dims 0 and 1
  %weight_t = "stablehlo.transpose"(%arg1) {permutation = array<i64: 1, 0>} : (tensor<16x16xf32>) -> tensor<16x16xf32>

  // dot_general: batch dims empty, contracting dims input dim 1 and weight dim 0
  %matmul = "stablehlo.dot_general"(%arg5, %weight_t) {dot_dimension_numbers = #stablehlo.dot<lhs_batching_dimensions = [], rhs_batching_dimensions = [], lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>} : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Add matmul.bias (arg2) to each row of matmul result
  // Broadcast matmul.bias from [16] to [16x16] along dimension 1
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %matmul_bias = stablehlo.add %matmul, %bias_broadcast : tensor<16x16xf32>

  // Step 2: Swish activation: x * sigmoid(x)
  // sigmoid(x) = 1 / (1 + exp(-x))
  %neg = stablehlo.negate %matmul_bias : tensor<16x16xf32>
  %exp = stablehlo.exponential %neg : tensor<16x16xf32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  // Broadcast one to tensor<16x16xf32>
  %one_broadcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64:}> : (tensor<f32>) -> tensor<16x16xf32>
  %exp_plus_one = stablehlo.add %exp, %one_broadcast : tensor<16x16xf32>
  %sigmoid = stablehlo.divide %one_broadcast, %exp_plus_one : tensor<16x16xf32>
  %swish = stablehlo.multiply %matmul_bias, %sigmoid : tensor<16x16xf32>

  // Step 3: Add bias (arg0) to swish output
  // bias shape: [16], broadcast to [16x16] along dimension 1
  %bias0_broadcast = "stablehlo.broadcast_in_dim"(%arg0) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %swish_bias = stablehlo.add %swish, %bias0_broadcast : tensor<16x16xf32>

  // Step 4: GroupNorm with num_groups=16, out_features=16
  // Input shape: [16,16] (batch_size=16, channels=16)
  // GroupNorm with num_groups=16 means each channel is its own group (group size = 1)
  // So group dimension is 1, group size is 1
  // Reshape input to [batch_size, num_groups, group_size] = [16,16,1]
  %reshape1 = stablehlo.reshape %swish_bias : (tensor<16x16xf32>) -> tensor<16x16x1xf32>

  // Compute mean over group_size dimension (dim=2)
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %init_mean = "stablehlo.broadcast_in_dim"(%zero_f32) {broadcast_dimensions = array<i64:}> : (tensor<f32>) -> tensor<16x16xf32>
  %mean = "stablehlo.reduce"(%reshape1, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2>} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>

  // group_size = 1, so mean is the same as the element itself, but keep formula for generality
  // Compute variance: mean of squared differences
  %mean_broadcast = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<16x16xf32>) -> tensor<16x16x1xf32>
  %diff = stablehlo.subtract %reshape1, %mean_broadcast : tensor<16x16x1xf32>
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<16x16x1xf32>
  %zero_f32_var = stablehlo.constant dense<0.0> : tensor<f32>
  %var = "stablehlo.reduce"(%diff_sq, %zero_f32_var) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2>} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>

  // variance = var / group_size = var / 1 = var
  // Add epsilon for numerical stability
  %epsilon = stablehlo.constant dense<1.000000e-05> : tensor<f32>
  %var_eps = stablehlo.add %var, %epsilon : tensor<16x16xf32>

  // Compute rsqrt(var_eps)
  %rsqrt_var = stablehlo.rsqrt %var_eps : tensor<16x16xf32>

  // Normalize: (x - mean) * rsqrt(var + eps)
  %rsqrt_var_broadcast = "stablehlo.broadcast_in_dim"(%rsqrt_var) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<16x16xf32>) -> tensor<16x16x1xf32>
  %norm = stablehlo.multiply %diff, %rsqrt_var_broadcast : tensor<16x16x1xf32>

  // Reshape norm back to [16x16]
  %norm_reshaped = stablehlo.reshape %norm : (tensor<16x16x1xf32>) -> tensor<16x16xf32>

  // Apply group_norm.weight (arg3) and group_norm.bias (arg4)
  // Both shape [16], broadcast to [16x16] along dimension 1
  %weight_broadcast = "stablehlo.broadcast_in_dim"(%arg3) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %bias_gn_broadcast = "stablehlo.broadcast_in_dim"(%arg4) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>

  %scaled = stablehlo.multiply %norm_reshaped, %weight_broadcast : tensor<16x16xf32>
  %out = stablehlo.add %scaled, %bias_gn_broadcast : tensor<16x16xf32>

  return %out : tensor<16x16xf32>
}

func.func @main(%arg0: tensor<16xf32>, %arg1: tensor<16x16xf32>, %arg2: tensor<16xf32>, %arg3: tensor<16xf32>, %arg4: tensor<16xf32>, %arg5: tensor<16x16xf32>) -> tensor<16x16xf32> {
  // %arg0 = bias (tensor<16xf32>)
  // %arg1 = matmul.weight (tensor<16x16xf32>)
  // %arg2 = matmul.bias (tensor<16xf32>)
  // %arg3 = group_norm.weight (tensor<16xf32>)
  // %arg4 = group_norm.bias (tensor<16xf32>)
  // %arg5 = input x (tensor<16x16xf32>)

  // Step 1: matmul: x @ weight^T + bias
  // Note: PyTorch Linear does x @ weight^T + bias
  // %arg5 shape: [16,16], %arg1 shape: [16,16] (weight)
  // We want to do dot_general with contracting dims: x dim 1 and weight dim 1 (weight transposed)
  // So transpose weight to [16,16] -> [16,16] (swap dims 0 and 1)
  %weight_t = "stablehlo.transpose"(%arg1) {permutation = array<i64: 1, 0>} : (tensor<16x16xf32>) -> tensor<16x16xf32>

  // dot_general: batch dims empty, contracting dims: x dim 1 and weight_t dim 0
  %matmul = "stablehlo.dot_general"(%arg5, %weight_t) {dot_dimension_numbers = #stablehlo.dot<lhs_batching_dimensions = [], rhs_batching_dimensions = [], lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>} : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // add matmul.bias (%arg2) broadcasted over dim 0 (batch)
  // %arg2 shape: [16], need to broadcast to [16x16]
  %matmul_bias_broadcast = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %matmul_plus_bias = stablehlo.add %matmul, %matmul_bias_broadcast : tensor<16x16xf32>

  // Step 2: Swish activation: x * sigmoid(x)
  // sigmoid(x) = 1 / (1 + exp(-x))
  %neg = stablehlo.negate %matmul_plus_bias : tensor<16x16xf32>
  %exp_neg = stablehlo.exponential %neg : tensor<16x16xf32>
  %one = stablehlo.constant dense<1.000000e+00> : tensor<f32>
  // broadcast one to [16x16]
  %one_broadcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: } : (tensor<f32>) -> tensor<16x16xf32>
  %one_plus_exp = stablehlo.add %one_broadcast, %exp_neg : tensor<16x16xf32>
  %sigmoid = stablehlo.divide %one_broadcast, %one_plus_exp : tensor<16x16xf32>
  %swish = stablehlo.multiply %matmul_plus_bias, %sigmoid : tensor<16x16xf32>

  // Step 3: add bias (%arg0) broadcasted over dim 0 (batch)
  // %arg0 shape: [16], broadcast to [16x16]
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg0) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %swish_plus_bias = stablehlo.add %swish, %bias_broadcast : tensor<16x16xf32>

  // Step 4: GroupNorm with num_groups=16, channels=16, so each group has 1 channel
  // Input shape: [N=16, C=16]
  // Reshape to [N=16, G=16, C_per_group=1]
  %reshape1 = stablehlo.reshape %swish_plus_bias : tensor<16x16xf32> -> tensor<16x16x1xf32>

  // Compute mean over axis=2 (C_per_group=1)
  %zero_f32 = stablehlo.constant dense<0.000000e+00> : tensor<f32>
  %mean = "stablehlo.reduce"(%reshape1, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2>} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>

  // mean shape: [16x16], divide by 1 (C_per_group)
  // C_per_group=1, so mean is sum itself
  // broadcast mean to [16x16x1]
  %mean_broadcast = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<16x16xf32>) -> tensor<16x16x1xf32>

  // Compute (x - mean)
  %x_minus_mean = stablehlo.subtract %reshape1, %mean_broadcast : tensor<16x16x1xf32>

  // Compute variance: mean of (x - mean)^2 over axis=2
  %squared = stablehlo.multiply %x_minus_mean, %x_minus_mean : tensor<16x16x1xf32>
  %var = "stablehlo.reduce"(%squared, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2>} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>

  // variance divide by 1 (C_per_group)
  // var shape: [16x16]
  // Add epsilon=1e-5 for numerical stability
  %epsilon = stablehlo.constant dense<1.000000e-05> : tensor<f32>
  %epsilon_broadcast = "stablehlo.broadcast_in_dim"(%epsilon) {broadcast_dimensions = array<i64: } : (tensor<f32>) -> tensor<16x16xf32>
  %var_plus_eps = stablehlo.add %var, %epsilon_broadcast : tensor<16x16xf32>

  // sqrt(var + eps)
  %stddev = stablehlo.sqrt %var_plus_eps : tensor<16x16xf32>

  // broadcast stddev to [16x16x1]
  %stddev_broadcast = "stablehlo.broadcast_in_dim"(%stddev) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<16x16xf32>) -> tensor<16x16x1xf32>

  // normalize: (x - mean) / stddev
  %normalized = stablehlo.divide %x_minus_mean, %stddev_broadcast : tensor<16x16x1xf32>

  // Reshape normalized to [16x16]
  %normalized_2d = stablehlo.reshape %normalized : tensor<16x16x1xf32> -> tensor<16x16xf32>

  // Apply affine transform: normalized * weight + bias
  // %arg3 = group_norm.weight (tensor<16xf32>)
  // %arg4 = group_norm.bias (tensor<16xf32>)
  // Broadcast weight and bias to [16x16]
  %weight_broadcast = "stablehlo.broadcast_in_dim"(%arg3) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %bias_gn_broadcast = "stablehlo.broadcast_in_dim"(%arg4) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>

  %scaled = stablehlo.multiply %normalized_2d, %weight_broadcast : tensor<16x16xf32>
  %out = stablehlo.add %scaled, %bias_gn_broadcast : tensor<16x16xf32>

  return %out : tensor<16x16xf32>
}

func.func @main(%arg0: tensor<12x32xf32>, %arg1: tensor<32x12xf32>) -> tensor<12x12xf32> {
