func.func @main(%bias: tensor<16xf32>, %matmul_weight: tensor<16x16xf32>, %matmul_bias: tensor<16xf32>, %gn_weight: tensor<16xf32>, %gn_bias: tensor<16xf32>, %input: tensor<16x16xf32>) -> tensor<16x16xf32> {
  // matmul: x @ weight^T + bias
  // matmul.weight shape: [16,16], we want to do input [16,16] x weight^T [16,16] -> [16,16]
  // So transpose matmul_weight to [16,16] (actually same shape, but transpose swaps dims)
  %matmul_weight_t = "stablehlo.transpose"(%matmul_weight) {permutation = array<i64: 1, 0>} : (tensor<16x16xf32>) -> tensor<16x16xf32>
  %matmul_out = "stablehlo.dot_general"(%input, %matmul_weight_t) {dot_dimension_numbers = #stablehlo.dot<lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [1]>} : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
  // add matmul bias (shape [16]) broadcast to [16x16]
  %matmul_bias_broadcast = "stablehlo.broadcast_in_dim"(%matmul_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %matmul_out_bias = stablehlo.add %matmul_out, %matmul_bias_broadcast : tensor<16x16xf32>

  // Swish activation: x * sigmoid(x)
  // sigmoid(x) = 1 / (1 + exp(-x))
  %neg_matmul = stablehlo.negate %matmul_out_bias : tensor<16x16xf32>
  %exp_neg = stablehlo.exponential %neg_matmul : tensor<16x16xf32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_tensor = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: 0} : (tensor<f32>) -> tensor<16xf32>
  // Broadcast one to [16x16]
  %one_2d = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<f32>) -> tensor<16x16xf32>
  %denominator = stablehlo.add %one_2d, %exp_neg : tensor<16x16xf32>
  %sigmoid = stablehlo.divide %one_2d, %denominator : tensor<16x16xf32>
  %swish = stablehlo.multiply %matmul_out_bias, %sigmoid : tensor<16x16xf32>

  // add bias (bias argument %bias shape [16]) broadcast to [16x16]
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%bias) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %swish_bias = stablehlo.add %swish, %bias_broadcast : tensor<16x16xf32>

  // GroupNorm with num_groups=16, out_features=16
  // Input shape: [16,16] (batch_size=16, channels=16)
  // GroupNorm divides channels into groups, here each group has 1 channel (16 groups)
  // So reshape to [batch_size, num_groups, channels_per_group] = [16,16,1]
  %reshape1 = stablehlo.reshape %swish_bias : (tensor<16x16xf32>) -> tensor<16x16x1xf32>

  // Compute mean over channels_per_group dimension (dim=2)
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %zero_f32_0d = "stablehlo.broadcast_in_dim"(%zero_f32) {broadcast_dimensions = array<i64:>} : (tensor<f32>) -> tensor<f32>
  %mean = "stablehlo.reduce"(%reshape1, %zero_f32_0d) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2>} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>
  // divide by channels_per_group=1 (no-op)
  // mean shape: [16,16]

  // Compute variance: mean of (x - mean)^2 over dim=2
  // Broadcast mean to [16,16,1]
  %mean_broadcast = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<16x16xf32>) -> tensor<16x16x1xf32>
  %diff = stablehlo.subtract %reshape1, %mean_broadcast : tensor<16x16x1xf32>
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<16x16x1xf32>
  %var = "stablehlo.reduce"(%diff_sq, %zero_f32_0d) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2>} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>
  // divide by channels_per_group=1 (no-op)
  // var shape: [16,16]

  // Add epsilon for numerical stability
  %epsilon = stablehlo.constant dense<1.000000e-05> : tensor<f32>
  %epsilon_broadcast = "stablehlo.broadcast_in_dim"(%epsilon) {broadcast_dimensions = array<i64:>} : (tensor<f32>) -> tensor<f32>
  %epsilon_2d = "stablehlo.broadcast_in_dim"(%epsilon) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<f32>) -> tensor<16x16xf32>
  %var_eps = stablehlo.add %var, %epsilon_2d : tensor<16x16xf32>

  // rsqrt(var + eps)
  %rsqrt_var = stablehlo.rsqrt %var_eps : tensor<16x16xf32>

  // Normalize: (x - mean) * rsqrt_var
  %diff_norm = stablehlo.subtract %reshape1, %mean_broadcast : tensor<16x16x1xf32>
  %rsqrt_var_broadcast = "stablehlo.broadcast_in_dim"(%rsqrt_var) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<16x16xf32>) -> tensor<16x16x1xf32>
  %norm = stablehlo.multiply %diff_norm, %rsqrt_var_broadcast : tensor<16x16x1xf32>

  // Reshape norm back to [16,16]
  %norm_2d = stablehlo.reshape %norm : (tensor<16x16x1xf32>) -> tensor<16x16xf32>

  // Apply group norm weight and bias (both shape [16]) broadcast to [16x16]
  %gn_weight_broadcast = "stablehlo.broadcast_in_dim"(%gn_weight) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %gn_bias_broadcast = "stablehlo.broadcast_in_dim"(%gn_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %scaled = stablehlo.multiply %norm_2d, %gn_weight_broadcast : tensor<16x16xf32>
  %out = stablehlo.add %scaled, %gn_bias_broadcast : tensor<16x16xf32>

  return %out : tensor<16x16xf32>
}

func.func @main(%arg0: tensor<6x7x3x3xf32>, %arg1: tensor<6xf32>, %arg2: tensor<6x7x6x6xf32>) -> tensor<6x6x2x2xf32> {
  // %arg0 = conv.weight: [out_channels=6, in_channels=7, kernel_h=3, kernel_w=3]
  // %arg1 = conv.bias: [out_channels=6]
  // %arg2 = input: [batch=6, channels=7, height=6, width=6]

  // Convolution parameters:
  // input layout: [b, f, h, w] = [6,7,6,6]
  // kernel layout: [o, i, kh, kw] = [6,7,3,3]
  // output layout: [b, f, h_out, w_out] = [6,6,4,4] (since no padding, stride=1)
  // dimension_numbers = [b,f,0,1]x[o,i,0,1]->[b,f,0,1]
  // window_strides = [1,1]
  // padding = 0

  %conv = "stablehlo.convolution"(%arg2, %arg0) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 1, 1>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x7x6x6xf32>, tensor<6x7x3x3xf32>) -> tensor<6x6x4x4xf32>

  // Add bias: conv output shape [6,6,4,4], bias shape [6]
  // Broadcast bias to [6,6,4,4] with broadcast_in_dim: bias dim 0 -> conv dim 1 (features)
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<6xf32>) -> tensor<6x6x4x4xf32>
  %conv_bias = stablehlo.add %conv, %bias_broadcast : tensor<6x6x4x4xf32>

  // Subtract subtract1_value = 0.5
  %c_subtract1 = stablehlo.constant dense<0.5> : tensor<f32>
  %c_subtract1_tensor = "stablehlo.broadcast_in_dim"(%c_subtract1) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x4x4xf32>
  %sub1 = stablehlo.subtract %conv_bias, %c_subtract1_tensor : tensor<6x6x4x4xf32>

  // Apply tanh
  %tanh = stablehlo.tanh %sub1 : tensor<6x6x4x4xf32>

  // Subtract subtract2_value = 0.2
  %c_subtract2 = stablehlo.constant dense<0.2> : tensor<f32>
  %c_subtract2_tensor = "stablehlo.broadcast_in_dim"(%c_subtract2) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x4x4xf32>
  %sub2 = stablehlo.subtract %tanh, %c_subtract2_tensor : tensor<6x6x4x4xf32>

  // Average pooling with kernel_size_pool=2, stride=2, no padding
  // Input shape: [6,6,4,4]
  // Output shape: [6,6,2,2]
  // Use reduce_window with sum and then divide by 4 (2*2)
  %init = stablehlo.constant dense<0.0> : tensor<f32>
  %sum = "stablehlo.reduce_window"(%sub2, %init) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %add = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %add : tensor<f32>
  }) {
    window_dimensions = array<i64: 1, 1, 2, 2>,
    window_strides = array<i64: 1, 1, 2, 2>,
    padding = dense<[[0, 0], [0, 0], [0, 0], [0, 0]]> : tensor<4x2xi64>
  } : (tensor<6x6x4x4xf32>, tensor<f32>) -> tensor<6x6x2x2xf32>

  // Divide sum by 4.0 to get average
  %c_4 = stablehlo.constant dense<4.0> : tensor<f32>
  %c_4_broadcast = "stablehlo.broadcast_in_dim"(%c_4) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x2x2xf32>
  %avgpool = stablehlo.divide %sum, %c_4_broadcast : tensor<6x6x2x2xf32>

  return %avgpool : tensor<6x6x2x2xf32>
}

func.func @main(%arg0: tensor<16xf32>, %arg1: tensor<16x16xf32>, %arg2: tensor<16xf32>, %arg3: tensor<16xf32>, %arg4: tensor<16xf32>, %arg5: tensor<16x16xf32>) -> tensor<16x16xf32> {
  // %arg0 = bias (tensor<16xf32>)
  // %arg1 = matmul.weight (tensor<16x16xf32>)
  // %arg2 = matmul.bias (tensor<16xf32>)
  // %arg3 = group_norm.weight (tensor<16xf32>)
  // %arg4 = group_norm.bias (tensor<16xf32>)
  // %arg5 = input x (tensor<16x16xf32>)

  // Step 1: matmul: x @ weight^T + bias
  // PyTorch Linear: y = x @ W^T + b
  // Given weight shape (16x16), we transpose it to (16x16) (actually same shape but transpose swaps dims)
  // x shape: (16x16), weight shape: (16x16)
  // We want to do dot_general with contracting dims: x dim 1 and weight dim 1 (since weight is transposed)
  // So lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [1]
  // Batch dims empty
  %weight_t = "stablehlo.transpose"(%arg1) {permutation = array<i64: 1, 0>} : (tensor<16x16xf32>) -> tensor<16x16xf32>
  %matmul = "stablehlo.dot_general"(%arg5, %weight_t) {dot_dimension_numbers = #stablehlo.dot<lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [1]>} : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Add matmul.bias (%arg2) to each row of matmul result
  // Broadcast bias (16) to (16x16) along dimension 1
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %matmul_bias = stablehlo.add %matmul, %bias_broadcast : tensor<16x16xf32>

  // Step 2: Swish activation: x * sigmoid(x)
  // sigmoid(x) = 1 / (1 + exp(-x))
  %neg = stablehlo.negate %matmul_bias : tensor<16x16xf32>
  %exp = stablehlo.exponential %neg : tensor<16x16xf32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  // Broadcast one to tensor<16x16xf32>
  %one_broadcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64:>} : (tensor<f32>) -> tensor<16x16xf32>
  %exp_plus_one = stablehlo.add %exp, %one_broadcast : tensor<16x16xf32>
  %sigmoid = stablehlo.divide %one_broadcast, %exp_plus_one : tensor<16x16xf32>
  %swish = stablehlo.multiply %matmul_bias, %sigmoid : tensor<16x16xf32>

  // Step 3: Add bias parameter %arg0 (bias) to swish output
  // Broadcast bias (16) to (16x16) along dimension 1
  %bias_broadcast2 = "stablehlo.broadcast_in_dim"(%arg0) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %swish_bias = stablehlo.add %swish, %bias_broadcast2 : tensor<16x16xf32>

  // Step 4: GroupNorm with num_groups=16, out_features=16
  // GroupNorm reshapes input (N, C) to (N, num_groups, C/num_groups)
  // Here N=16, C=16, num_groups=16, so C/num_groups=1
  // Reshape input to (16,16,1)
  %swish_bias_reshaped = stablehlo.reshape %swish_bias : (tensor<16x16xf32>) -> tensor<16x16x1xf32>

  // Compute mean over last dimension (dim=2)
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %mean = "stablehlo.reduce"(%swish_bias_reshaped, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2>} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>

  // mean shape: (16x16)
  // Compute variance: mean of (x - mean)^2 over dim=2
  // Broadcast mean to (16x16x1)
  %mean_broadcast = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<16x16xf32>) -> tensor<16x16x1xf32>
  %diff = stablehlo.subtract %swish_bias_reshaped, %mean_broadcast : tensor<16x16x1xf32>
  %sq = stablehlo.multiply %diff, %diff : tensor<16x16x1xf32>
  %var = "stablehlo.reduce"(%sq, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2>} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>

  // var shape: (16x16)
  // Normalize: (x - mean) / sqrt(var + eps)
  %eps = stablehlo.constant dense<1.0e-5> : tensor<f32>
  %var_eps = stablehlo.add %var, %eps : tensor<16x16xf32>
  %sqrt_var = stablehlo.sqrt %var_eps : tensor<16x16xf32>
  // Broadcast sqrt_var to (16x16x1)
  %sqrt_var_broadcast = "stablehlo.broadcast_in_dim"(%sqrt_var) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<16x16xf32>) -> tensor<16x16x1xf32>
  %normalized = stablehlo.divide %diff, %sqrt_var_broadcast : tensor<16x16x1xf32>

  // Reshape normalized to (16x16)
  %normalized_2d = stablehlo.reshape %normalized : (tensor<16x16x1xf32>) -> tensor<16x16xf32>

  // Apply group_norm.weight (%arg3) and group_norm.bias (%arg4)
  // Broadcast weight and bias to (16x16) along dimension 1
  %weight_broadcast = "stablehlo.broadcast_in_dim"(%arg3) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %bias_gn_broadcast = "stablehlo.broadcast_in_dim"(%arg4) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>

  %scaled = stablehlo.multiply %normalized_2d, %weight_broadcast : tensor<16x16xf32>
  %shifted = stablehlo.add %scaled, %bias_gn_broadcast : tensor<16x16xf32>

  return %shifted : tensor<16x16xf32>
}

func.func @main(%arg0: tensor<6x7x3x3xf32>, %arg1: tensor<6xf32>, %arg2: tensor<6x7x6x6xf32>) -> tensor<6x6x2x2xf32> {
  // %arg0 = conv.weight: [out_channels=6, in_channels=7, kernel_h=3, kernel_w=3]
  // %arg1 = conv.bias: [out_channels=6]
  // %arg2 = input: [batch=6, in_channels=7, height=6, width=6]

  // Convolution parameters:
  // input layout: [b, f, h, w] = [6,7,6,6]
  // kernel layout: [o, i, kh, kw] = [6,7,3,3]
  // output layout: [b, f, h_out, w_out] = [6,6,4,4] because:
  // output spatial size = floor((0 + (6-1)*1 + 1 + 0 - ((3-1)*1 + 1))/1) + 1 = floor((5+1 - 3)/1)+1 = floor(3)+1=4
  // So output shape after conv is [6,6,4,4]

  // Perform convolution
  %conv = "stablehlo.convolution"(%arg2, %arg0) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 1, 1>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x7x6x6xf32>, tensor<6x7x3x3xf32>) -> tensor<6x6x4x4xf32>

  // Add bias: broadcast bias from [6] to [6,6,4,4]
  // Bias shape: [out_channels=6], conv output feature dim is dim=1
  // Broadcast bias to [batch=6, feature=6, height=4, width=4]
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<6xf32>) -> tensor<6x6x4x4xf32>
  %conv_bias = stablehlo.add %conv, %bias_broadcast : tensor<6x6x4x4xf32>

  // Subtract subtract1_value = 0.5
  %c_sub1 = stablehlo.constant dense<0.5> : tensor<f32>
  // Broadcast scalar to conv output shape
  %sub1_broadcast = "stablehlo.broadcast_in_dim"(%c_sub1) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x4x4xf32>
  %sub1 = stablehlo.subtract %conv_bias, %sub1_broadcast : tensor<6x6x4x4xf32>

  // Apply tanh
  %tanh = stablehlo.tanh %sub1 : tensor<6x6x4x4xf32>

  // Subtract subtract2_value = 0.2
  %c_sub2 = stablehlo.constant dense<0.2> : tensor<f32>
  %sub2_broadcast = "stablehlo.broadcast_in_dim"(%c_sub2) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x4x4xf32>
  %sub2 = stablehlo.subtract %tanh, %sub2_broadcast : tensor<6x6x4x4xf32>

  // Average pooling with kernel_size_pool=2, stride=2 (default for AvgPool2d)
  // Input shape: [6,6,4,4]
  // Output shape: floor((4 - 2)/2) + 1 = 2 for height and width
  // So output shape: [6,6,2,2]

  // AvgPool2d is reduce_window with sum and divide by window size
  // Create init value 0.0 for reduce_window
  %zero = stablehlo.constant dense<0.0> : tensor<f32>

  // Define reduce_window with window_dimensions = [1,1,2,2] (pool over spatial dims only)
  // window_strides = [1,1,2,2]
  // padding = 0
  %sum = "stablehlo.reduce_window"(%sub2, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %add = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %add : tensor<f32>
  }) {
    window_dimensions = array<i64: 1, 1, 2, 2>,
    window_strides = array<i64: 1, 1, 2, 2>,
    padding = dense<[[0, 0], [0, 0], [0, 0], [0, 0]]> : tensor<4x2xi64>
  } : (tensor<6x6x4x4xf32>, tensor<f32>) -> tensor<6x6x2x2xf32>

  // Divide sum by window size (2*2=4)
  %four = stablehlo.constant dense<4.0> : tensor<f32>
  %four_broadcast = "stablehlo.broadcast_in_dim"(%four) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x2x2xf32>
  %avgpool = stablehlo.divide %sum, %four_broadcast : tensor<6x6x2x2xf32>

  return %avgpool : tensor<6x6x2x2xf32>
}

func.func @main(%conv_weight: tensor<6x7x3x3xf32>, %conv_bias: tensor<6xf32>, %input: tensor<6x7x6x6xf32>) -> tensor<6x6x2x2xf32> {
  // Convolution: output shape [6, 6, 6, 6]
  %zero_i64 = stablehlo.constant dense<0> : tensor<i64>
  %one_i64 = stablehlo.constant dense<1> : tensor<i64>

  // Convolution parameters:
  // window_strides = [1, 1]
  // padding = [[0,0],[0,0]] (no padding)
  // lhs_dilation = [1, 1]
  // rhs_dilation = [1, 1]
  // dimension_numbers = [b, f, 0, 1] x [o, i, 0, 1] -> [b, f, 0, 1]
  // feature_group_count = 1
  // batch_group_count = 1

  %conv = "stablehlo.convolution"(%input, %conv_weight) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 1, 1>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x7x6x6xf32>, tensor<6x7x3x3xf32>) -> tensor<6x6x6x6xf32>

  // Add bias: broadcast conv_bias [6] to [6,6,6,6]
  %conv_bias_bcast = "stablehlo.broadcast_in_dim"(%conv_bias) {broadcast_dimensions = array<i64: 0>} : (tensor<6xf32>) -> tensor<6x1x1x1xf32>
  %conv_bias_bcast_reshaped = "stablehlo.broadcast_in_dim"(%conv_bias_bcast) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<6x1x1x1xf32>) -> tensor<6x6x6x6xf32>
  %conv_plus_bias = stablehlo.add %conv, %conv_bias_bcast_reshaped : tensor<6x6x6x6xf32>

  // Subtract 0.5 (subtract1_value)
  %const_subtract1 = stablehlo.constant dense<0.5> : tensor<f32>
  %const_subtract1_bcast = "stablehlo.broadcast_in_dim"(%const_subtract1) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x6x6xf32>
  %after_subtract1 = stablehlo.subtract %conv_plus_bias, %const_subtract1_bcast : tensor<6x6x6x6xf32>

  // Apply tanh
  %after_tanh = stablehlo.tanh %after_subtract1 : tensor<6x6x6x6xf32>

  // Subtract 0.2 (subtract2_value)
  %const_subtract2 = stablehlo.constant dense<0.2> : tensor<f32>
  %const_subtract2_bcast = "stablehlo.broadcast_in_dim"(%const_subtract2) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x6x6xf32>
  %after_subtract2 = stablehlo.subtract %after_tanh, %const_subtract2_bcast : tensor<6x6x6x6xf32>

  // Average Pooling with kernel_size_pool=2, stride=2, no padding
  // Use reduce_window with add and divide by window size (4)
  %init = stablehlo.constant dense<0.0> : tensor<f32>
  %window_dims = array<i64: 1, 1, 2, 2>
  %window_strides = array<i64: 1, 1, 2, 2>
  %padding = stablehlo.constant dense<[[0, 0], [0, 0], [0, 0], [0, 0]]> : tensor<4x2xi64>

  %sum_pool = "stablehlo.reduce_window"(%after_subtract2, %init) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %c : tensor<f32>
  }) {
    window_dimensions = %window_dims,
    window_strides = %window_strides,
    padding = %padding
  } : (tensor<6x6x6x6xf32>, tensor<f32>) -> tensor<6x6x3x3xf32>

  // Divide by 4 (window size)
  %four = stablehlo.constant dense<4.0> : tensor<f32>
  %four_bcast = "stablehlo.broadcast_in_dim"(%four) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x3x3xf32>
  %avg_pool = stablehlo.divide %sum_pool, %four_bcast : tensor<6x6x3x3xf32>

  // Reshape output from [6,6,3,3] to [6,6,2,2]
  // The output shape is tensor<6x6x2x2xf32>
  %output = stablehlo.reshape %avg_pool : tensor<6x6x3x3xf32> -> tensor<6x6x2x2xf32>

  return %output : tensor<6x6x2x2xf32>
}

// Conv dimension numbers attribute
// #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>

func.func @main(%arg0: tensor<6x7x3x3xf32>, %arg1: tensor<6xf32>, %arg2: tensor<6x7x6x6xf32>) -> tensor<6x6x2x2xf32> {
  // %arg0 = conv.weight: [out_channels=6, in_channels=7, kernel_h=3, kernel_w=3]
  // %arg1 = conv.bias: [out_channels=6]
  // %arg2 = input: [batch=6, in_channels=7, height=6, width=6]

  // Convolution parameters:
  // input: [6,7,6,6]
  // weight: [6,7,3,3]
  // output: [6,6,4,4] (since no padding, stride=1)
  // dimension_numbers: input [b,f,h,w], kernel [o,i,kh,kw], output [b,f,h,w]
  // feature_group_count=1, batch_group_count=1
  // window_strides = [1,1]
  // padding = [[0,0],[0,0]]

  %zero = stablehlo.constant dense<0> : tensor<i32>
  %f32_0_5 = stablehlo.constant dense<0.5> : tensor<f32>
  %f32_0_2 = stablehlo.constant dense<0.2> : tensor<f32>

  // Convolution
  %conv = "stablehlo.convolution"(%arg2, %arg0) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 1, 1>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 2, 3]x[o, i, 2, 3]->[b, f, 2, 3]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x7x6x6xf32>, tensor<6x7x3x3xf32>) -> tensor<6x6x4x4xf32>

  // Add bias: broadcast bias from [6] to [6x6x4x4]
  // Broadcast bias on dimension 1 (feature dimension)
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<6xf32>) -> tensor<6x6x1x1xf32>
  // Broadcast to full spatial dims 4x4
  %bias_broadcast_full = "stablehlo.broadcast_in_dim"(%bias_broadcast) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<6x6x1x1xf32>) -> tensor<6x6x4x4xf32>
  %conv_bias = stablehlo.add %conv, %bias_broadcast_full : tensor<6x6x4x4xf32>

  // Subtract subtract1_value (0.5)
  %sub1_broadcast = "stablehlo.broadcast_in_dim"(%f32_0_5) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x4x4xf32>
  %sub1 = stablehlo.subtract %conv_bias, %sub1_broadcast : tensor<6x6x4x4xf32>

  // Tanh activation
  %tanh = stablehlo.tanh %sub1 : tensor<6x6x4x4xf32>

  // Subtract subtract2_value (0.2)
  %sub2_broadcast = "stablehlo.broadcast_in_dim"(%f32_0_2) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x4x4xf32>
  %sub2 = stablehlo.subtract %tanh, %sub2_broadcast : tensor<6x6x4x4xf32>

  // Average Pooling with kernel_size=2, stride=2, no padding
  // Use reduce_window with add and then divide by 4 (2x2)
  %init = stablehlo.constant dense<0.0> : tensor<f32>
  %sum_pool = "stablehlo.reduce_window"(%sub2, %init) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %add = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %add : tensor<f32>
  }) {
    window_dimensions = array<i64: 1, 1, 2, 2>,
    window_strides = array<i64: 1, 1, 2, 2>,
    padding = dense<[[0, 0], [0, 0], [0, 0], [0, 0]]> : tensor<4x2xi64>
  } : (tensor<6x6x4x4xf32>, tensor<f32>) -> tensor<6x6x2x2xf32>

  // Divide by 4.0 to get average
  %divisor = stablehlo.constant dense<4.0> : tensor<f32>
  %divisor_broadcast = "stablehlo.broadcast_in_dim"(%divisor) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x2x2xf32>
  %avg_pool = stablehlo.divide %sum_pool, %divisor_broadcast : tensor<6x6x2x2xf32>

  return %avg_pool : tensor<6x6x2x2xf32>
}

func.func @main(%bn_weight: tensor<6xf32>, %bn_bias: tensor<6xf32>, %x: tensor<6x6x7x7xf32>) -> tensor<6x6x7x7xf32> {
  // Compute mean over batch, height, width dimensions: dims = [0, 2, 3]
  %c0 = stablehlo.constant dense<0.0> : tensor<f32>
  %mean = "stablehlo.reduce"(%x, %c0) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0, 2, 3>} : (tensor<6x6x7x7xf32>, tensor<f32>) -> tensor<6xf32>
  // divisor = batch_size * height * width = 6*7*7=294
  %c294 = stablehlo.constant dense<294.0> : tensor<f32>
  %mean_div = stablehlo.divide %mean, %c294 : tensor<6xf32>

  // Broadcast mean to input shape for subtraction
  %mean_bcast = "stablehlo.broadcast_in_dim"(%mean_div) {broadcast_dimensions = array<i64: 1>} : (tensor<6xf32>) -> tensor<6x6x7x7xf32>

  // x - mean
  %x_centered = stablehlo.subtract %x, %mean_bcast : tensor<6x6x7x7xf32>

  // Compute variance: mean of squared differences
  %x_centered_sq = stablehlo.multiply %x_centered, %x_centered : tensor<6x6x7x7xf32>
  %var_sum = "stablehlo.reduce"(%x_centered_sq, %c0) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0, 2, 3>} : (tensor<6x6x7x7xf32>, tensor<f32>) -> tensor<6xf32>
  %var = stablehlo.divide %var_sum, %c294 : tensor<6xf32>

  // epsilon constant for numerical stability
  %epsilon = stablehlo.constant dense<1.0e-5> : tensor<f32>

  // variance + epsilon
  %var_eps = stablehlo.add %var, %epsilon : tensor<6xf32>

  // sqrt(variance + epsilon)
  %stddev = stablehlo.sqrt %var_eps : tensor<6xf32>

  // Broadcast stddev to input shape
  %stddev_bcast = "stablehlo.broadcast_in_dim"(%stddev) {broadcast_dimensions = array<i64: 1>} : (tensor<6xf32>) -> tensor<6x6x7x7xf32>

  // Normalize: (x - mean) / stddev
  %x_norm = stablehlo.divide %x_centered, %stddev_bcast : tensor<6x6x7x7xf32>

  // Broadcast bn.weight and bn.bias to input shape
  %weight_bcast = "stablehlo.broadcast_in_dim"(%bn_weight) {broadcast_dimensions = array<i64: 1>} : (tensor<6xf32>) -> tensor<6x6x7x7xf32>
  %bias_bcast = "stablehlo.broadcast_in_dim"(%bn_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<6xf32>) -> tensor<6x6x7x7xf32>

  // Scale and shift: x_norm * weight + bias
  %scaled = stablehlo.multiply %x_norm, %weight_bcast : tensor<6x6x7x7xf32>
  %shifted = stablehlo.add %scaled, %bias_bcast : tensor<6x6x7x7xf32>

  "stablehlo.return"(%shifted) : tensor<6x6x7x7xf32>
}

func.func @main(%bn_weight: tensor<6xf32>, %bn_bias: tensor<6xf32>, %x: tensor<6x6x7x7xf32>) -> tensor<6x6x7x7xf32> {
  // Compute mean over batch (dim 0), height (dim 2), width (dim 3)
  %c0 = stablehlo.constant dense<0.0> : tensor<f32>
  %mean = "stablehlo.reduce"(%x, %c0) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0, 2, 3>} : (tensor<6x6x7x7xf32>, tensor<f32>) -> tensor<6xf32>

  // Compute variance: mean of squared deviations
  %mean_broadcast = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = array<i64: 1>} : (tensor<6xf32>) -> tensor<1x6x1x1xf32>
  %x_minus_mean = stablehlo.subtract %x, %mean_broadcast : tensor<6x6x7x7xf32>
  %sq_diff = stablehlo.multiply %x_minus_mean, %x_minus_mean : tensor<6x6x7x7xf32>
  %c0_var = stablehlo.constant dense<0.0> : tensor<f32>
  %var = "stablehlo.reduce"(%sq_diff, %c0_var) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0, 2, 3>} : (tensor<6x6x7x7xf32>, tensor<f32>) -> tensor<6xf32>

  // Normalize variance by dividing by N = 6*7*7 = 294
  %c294 = stablehlo.constant dense<294.0> : tensor<f32>
  %var_div = stablehlo.divide %var, %c294 : tensor<6xf32>

  // Add epsilon for numerical stability (eps=1e-5)
  %c_eps = stablehlo.constant dense<0.00001> : tensor<f32>
  %var_eps = stablehlo.add %var_div, %c_eps : tensor<6xf32>

  // Compute rsqrt(variance + eps)
  %inv_std = stablehlo.rsqrt %var_eps : tensor<6xf32>

  // Broadcast inv_std, bn_weight, bn_bias to input shape
  %inv_std_bcast = "stablehlo.broadcast_in_dim"(%inv_std) {broadcast_dimensions = array<i64: 1>} : (tensor<6xf32>) -> tensor<1x6x1x1xf32>
  %bn_weight_bcast = "stablehlo.broadcast_in_dim"(%bn_weight) {broadcast_dimensions = array<i64: 1>} : (tensor<6xf32>) -> tensor<1x6x1x1xf32>
  %bn_bias_bcast = "stablehlo.broadcast_in_dim"(%bn_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<6xf32>) -> tensor<1x6x1x1xf32>

  // Normalize input: (x - mean) * inv_std
  %x_centered = stablehlo.subtract %x, %mean_broadcast : tensor<6x6x7x7xf32>
  %x_norm = stablehlo.multiply %x_centered, %inv_std_bcast : tensor<6x6x7x7xf32>

  // Scale and shift: x_norm * weight + bias
  %scaled = stablehlo.multiply %x_norm, %bn_weight_bcast : tensor<6x6x7x7xf32>
  %shifted = stablehlo.add %scaled, %bn_bias_bcast : tensor<6x6x7x7xf32>

  "stablehlo.return"(%shifted) : tensor<6x6x7x7xf32>
}

func.func @main(%arg0: tensor<7x8x3x3xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x8x6x6xf32>) -> tensor<6x7x4x4xf32> {
  // Convolution dimension numbers:
  // input: [b, f, h, w] = [6, 8, 6, 6]
  // kernel: [o, i, kh, kw] = [7, 8, 3, 3]
  // output: [b, f, h_out, w_out] = [6, 7, 4, 4]
  //
  // Using dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 2, 3]->[b, f, 2, 3]>
  // which means:
  // input dims: batch=0, feature=1, spatial dims=2,3
  // kernel dims: output_feature=0, input_feature=1, spatial dims=2,3
  // output dims: batch=0, feature=1, spatial dims=2,3

  %c1 = stablehlo.constant dense<1> : tensor<i64>
  %c0 = stablehlo.constant dense<0> : tensor<i64>

  // Convolution with stride=1, no padding, no dilation, feature_group_count=1
  %conv = "stablehlo.convolution"(%arg2, %arg0) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 1, 1>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 2, 3]x[o, i, 2, 3]->[b, f, 2, 3]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x8x6x6xf32>, tensor<7x8x3x3xf32>) -> tensor<6x7x4x4xf32>

  // Add bias: %arg1 shape is [7], need to broadcast to [6x7x4x4]
  // Broadcast bias to [1x7x1x1] then to [6x7x4x4]
  %bias_bcast_1 = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<1x7x1x1xf32>
  %bias_bcast = "stablehlo.broadcast_in_dim"(%bias_bcast_1) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<1x7x1x1xf32>) -> tensor<6x7x4x4xf32>

  %conv_bias = stablehlo.add %conv, %bias_bcast : tensor<6x7x4x4xf32>

  // Divide by divisor=2 (scalar)
  %divisor = stablehlo.constant dense<2.0> : tensor<f32>
  // Broadcast divisor scalar to tensor<6x7x4x4xf32>
  %divisor_bcast = "stablehlo.broadcast_in_dim"(%divisor) {broadcast_dimensions = array<i64:>} : (tensor<f32>) -> tensor<6x7x4x4xf32>

  %div = stablehlo.divide %conv_bias, %divisor_bcast : tensor<6x7x4x4xf32>

  // LeakyReLU with negative_slope=0.01
  // leaky_relu(x) = max(0, x) + negative_slope * min(0, x)
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %zero_bcast = "stablehlo.broadcast_in_dim"(%zero) {broadcast_dimensions = array<i64:>} : (tensor<f32>) -> tensor<6x7x4x4xf32>

  %max_part = stablehlo.maximum %div, %zero_bcast : tensor<6x7x4x4xf32>
  %min_part = stablehlo.minimum %div, %zero_bcast : tensor<6x7x4x4xf32>

  %neg_slope = stablehlo.constant dense<0.01> : tensor<f32>
  %neg_slope_bcast = "stablehlo.broadcast_in_dim"(%neg_slope) {broadcast_dimensions = array<i64:>} : (tensor<f32>) -> tensor<6x7x4x4xf32>

  %scaled_min = stablehlo.multiply %min_part, %neg_slope_bcast : tensor<6x7x4x4xf32>

  %leaky_relu = stablehlo.add %max_part, %scaled_min : tensor<6x7x4x4xf32>

  return %leaky_relu : tensor<6x7x4x4xf32>
}

func.func @main(%weight: tensor<6xf32>, %bias: tensor<6xf32>, %x: tensor<6x6x7x7xf32>) -> tensor<6x6x7x7xf32> {
  // Compute mean over axes [0, 2, 3] (batch, height, width) for each channel
  %c0 = stablehlo.constant dense<0> : tensor<i64>
  %c2 = stablehlo.constant dense<2> : tensor<i64>
  %c3 = stablehlo.constant dense<3> : tensor<i64>
  %zero_f32 = stablehlo.constant dense<0.000000e+00> : tensor<f32>
  %mean = "stablehlo.reduce"(%x, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0, 2, 3>} : (tensor<6x6x7x7xf32>, tensor<f32>) -> tensor<6xf32>

  // Compute count = batch_size * height * width = 6*7*7 = 294 as f32 constant
  %count = stablehlo.constant dense<2.940000e+02> : tensor<f32>

  // mean = sum / count
  %mean_broadcast = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = array<i64: 1} : (tensor<6xf32>) -> tensor<1x6x1x1xf32>
  %count_broadcast = "stablehlo.broadcast_in_dim"(%count) {broadcast_dimensions = array<i64: }> : (tensor<f32>) -> tensor<f32> // scalar broadcast
  %mean_div = stablehlo.divide %mean, %count : tensor<6xf32>
  // Actually we need to divide sum by count, but sum shape is [6], count scalar
  // So divide mean by count directly:
  %mean_f32 = stablehlo.divide %mean, %count : tensor<6xf32>

  // Broadcast mean to shape [6x6x7x7]
  %mean_broadcast = "stablehlo.broadcast_in_dim"(%mean_f32) {broadcast_dimensions = array<i64: 1} : (tensor<6xf32>) -> tensor<6x6x7x7xf32>

  // Compute (x - mean)
  %x_minus_mean = stablehlo.subtract %x, %mean_broadcast : tensor<6x6x7x7xf32>

  // Compute variance: mean of squared differences over axes [0, 2, 3]
  %x_minus_mean_sq = stablehlo.multiply %x_minus_mean, %x_minus_mean : tensor<6x6x7x7xf32>
  %var_sum = "stablehlo.reduce"(%x_minus_mean_sq, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0, 2, 3>} : (tensor<6x6x7x7xf32>, tensor<f32>) -> tensor<6xf32>

  // variance = var_sum / count
  %var_f32 = stablehlo.divide %var_sum, %count : tensor<6xf32>

  // Broadcast variance to shape [6x6x7x7]
  %var_broadcast = "stablehlo.broadcast_in_dim"(%var_f32) {broadcast_dimensions = array<i64: 1} : (tensor<6xf32>) -> tensor<6x6x7x7xf32>

  // epsilon constant 1e-5
  %epsilon = stablehlo.constant dense<1.000000e-05> : tensor<f32>
  %epsilon_broadcast = "stablehlo.broadcast_in_dim"(%epsilon) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<f32>

  // variance + epsilon
  %var_eps = stablehlo.add %var_broadcast, %epsilon_broadcast : tensor<6x6x7x7xf32>

  // sqrt(variance + epsilon)
  %stddev = stablehlo.sqrt %var_eps : tensor<6x6x7x7xf32>

  // Normalize: (x - mean) / stddev
  %x_centered = stablehlo.subtract %x, %mean_broadcast : tensor<6x6x7x7xf32>
  %x_norm = stablehlo.divide %x_centered, %stddev : tensor<6x6x7x7xf32>

  // Broadcast weight and bias to [6x6x7x7]
  %weight_broadcast = "stablehlo.broadcast_in_dim"(%weight) {broadcast_dimensions = array<i64: 1} : (tensor<6xf32>) -> tensor<6x6x7x7xf32>
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%bias) {broadcast_dimensions = array<i64: 1} : (tensor<6xf32>) -> tensor<6x6x7x7xf32>

  // Scale and shift: weight * x_norm + bias
  %scaled = stablehlo.multiply %weight_broadcast, %x_norm : tensor<6x6x7x7xf32>
  %out = stablehlo.add %scaled, %bias_broadcast : tensor<6x6x7x7xf32>

  return %out : tensor<6x6x7x7xf32>
}

func.func @main(%arg0: tensor<7x8x3x3xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x8x6x6xf32>) -> tensor<6x7x4x4xf32> {
  // %arg0: conv.weight (out_channels=7, in_channels=8, kernel_h=3, kernel_w=3)
  // %arg1: conv.bias (out_channels=7)
  // %arg2: input (batch=6, in_channels=8, height=6, width=6)

  // Convolution parameters:
  // input: [6,8,6,6]
  // kernel: [7,8,3,3]
  // output: [6,7,4,4] because:
  // output_h = floor((6 + 0 + 0 - 3)/1) + 1 = 4
  // output_w = floor((6 + 0 + 0 - 3)/1) + 1 = 4
  // stride=1, padding=0, dilation=1

  // dimension_numbers = #stablehlo.conv<[b, i, h, w]x[o, i, kh, kw]->[b, o, oh, ow]>
  // feature_group_count=1, batch_group_count=1

  %conv = "stablehlo.convolution"(%arg2, %arg0) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 1, 1>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[0, 1, 2, 3]x[0, 1, 2, 3]->[0, 1, 2, 3]>,
