  %divisor_broadcast = "stablehlo.broadcast_in_dim"(%divisor) {broadcast_dimensions = array<i64:>} : (tensor<f32>) -> tensor<> // scalar broadcast
  %divisor_broadcast_4d = "stablehlo.broadcast_in_dim"(%divisor) {broadcast_dimensions = array<i64: 0} : (tensor<f32>) -> tensor<6x7x4x4xf32> // Actually broadcast scalar to full shape
  // Correct broadcasting: broadcast scalar to [6,7,4,4]
  %divisor_broadcast = "stablehlo.broadcast_in_dim"(%divisor) {broadcast_dimensions = array<i64:}> : (tensor<f32>) -> tensor<> // scalar
  %divisor_broadcast_4d = "stablehlo.broadcast_in_dim"(%divisor) {broadcast_dimensions = array<i64:}> : (tensor<f32>) -> tensor<6x7x4x4xf32>
  // The above is invalid, must broadcast scalar to 6x7x4x4 with empty broadcast_dimensions array is invalid.
  // Correct way: broadcast scalar to 6x7x4x4 with broadcast_dimensions = []
  // But stablehlo.broadcast_in_dim requires broadcast_dimensions length == operand rank.
  // Scalar rank 0, broadcast_dimensions empty array is valid.
  // So:
  %divisor_broadcast_4d = "stablehlo.broadcast_in_dim"(%divisor) {broadcast_dimensions = array<i64:>} : (tensor<f32>) -> tensor<6x7x4x4xf32>

  %divided = stablehlo.divide %conv_plus_bias, %divisor_broadcast_4d : tensor<6x7x4x4xf32>

  // LeakyReLU with negative_slope=0.01
  // leaky_relu(x) = max(x, 0) + negative_slope * min(x, 0)
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %zero_broadcast = "stablehlo.broadcast_in_dim"(%zero) {broadcast_dimensions = array<i64:>} : (tensor<f32>) -> tensor<6x7x4x4xf32>
  %max_part = stablehlo.maximum %divided, %zero_broadcast : tensor<6x7x4x4xf32>
  %min_part = stablehlo.minimum %divided, %zero_broadcast : tensor<6x7x4x4xf32>
  %neg_slope = stablehlo.constant dense<0.01> : tensor<f32>
  %neg_slope_broadcast = "stablehlo.broadcast_in_dim"(%neg_slope) {broadcast_dimensions = array<i64:>} : (tensor<f32>) -> tensor<6x7x4x4xf32>
  %scaled_min = stablehlo.multiply %min_part, %neg_slope_broadcast : tensor<6x7x4x4xf32>
  %leaky_relu = stablehlo.add %max_part, %scaled_min : tensor<6x7x4x4xf32>

  return %leaky_relu : tensor<6x7x4x4xf32>
}

func.func @main(%conv_weight: tensor<7x8x3x3xf32>, %conv_bias: tensor<7xf32>, %input: tensor<6x8x6x6xf32>) -> tensor<6x7x4x4xf32> {
  // Perform convolution: input shape [6,8,6,6], weight shape [7,8,3,3]
  // dimension_numbers: input [b,f,0,1], kernel [o,i,0,1], output [b,f,0,1]
  %conv = "stablehlo.convolution"(%input, %conv_weight) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 1, 1>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x8x6x6xf32>, tensor<7x8x3x3xf32>) -> tensor<6x7x4x4xf32>

  // Broadcast bias from [7] to [6,7,4,4] to add after convolution
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%conv_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7x4x4xf32>

  // Add bias
  %conv_bias_added = stablehlo.add %conv, %bias_broadcast : tensor<6x7x4x4xf32>

  // Create constant divisor tensor with value 2.0, shape [6,7,4,4]
  %const_two = stablehlo.constant dense<2.0> : tensor<f32>
  %divisor = "stablehlo.broadcast_in_dim"(%const_two) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7x4x4xf32>

  // Divide by divisor
  %divided = stablehlo.divide %conv_bias_added, %divisor : tensor<6x7x4x4xf32>

  // Create constant zero tensor for comparison, shape [6,7,4,4]
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %zero_broadcast = "stablehlo.broadcast_in_dim"(%zero) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7x4x4xf32>

  // Compare divided > 0.0 for LeakyReLU condition
  %cond = "stablehlo.compare"(%divided, %zero_broadcast) {comparison_direction = #stablehlo<comparison_direction GT>, compare_type = #stablehlo<comparison_type FLOAT>} : (tensor<6x7x4x4xf32>, tensor<6x7x4x4xf32>) -> tensor<6x7x4x4xi1>

  // Create constant 0.01 tensor for negative slope, shape [6,7,4,4]
  %const_point_zero_one = stablehlo.constant dense<0.01> : tensor<f32>
  %neg_slope = "stablehlo.broadcast_in_dim"(%const_point_zero_one) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7x4x4xf32>

  // Multiply divided * 0.01 for negative slope branch
  %neg_branch = stablehlo.multiply %divided, %neg_slope : tensor<6x7x4x4xf32>

