  %epsilon_broadcast = "stablehlo.broadcast_in_dim"(%epsilon) {broadcast_dimensions = array<i64: ()} : (tensor<f32>) -> tensor<f32>
  %epsilon_broadcast = "stablehlo.broadcast_in_dim"(%epsilon) {broadcast_dimensions = array<i64: ()} : (tensor<f32>) -> tensor<f32>
  %epsilon_broadcast = "stablehlo.broadcast_in_dim"(%epsilon) {broadcast_dimensions = array<i64: ()} : (tensor<f32>) -> tensor<f32>
