}

func.func @main(%arg0: tensor<6x6xf32>) -> tensor<6x6xf32> {
  // We compute cumulative product along dimension 1 (the second dimension).
  // The output at (i,j) = product of input(i,0:j).
  // We implement this by a loop over j, multiplying previous output(i,j-1) by input(i,j).
  // Since StableHLO is functional and SSA, we unroll the loop manually for size 6.

  // Extract slices for each column along dim=1
  %c0 = stablehlo.constant dense<0> : tensor<i64>
  %c1 = stablehlo.constant dense<1> : tensor<i64>
  %c6 = stablehlo.constant dense<6> : tensor<i64>

  // Slice dim=1 index 0: input[:,0]
  %start0 = stablehlo.constant dense<[0, 0]> : tensor<2xi64>
  %limit0 = stablehlo.constant dense<[6, 1]> : tensor<2xi64>
