  %slice0 = stablehlo.slice %arg0 {start_indices = array<i64: 0, 0>, limit_indices = array<i64: 6, 1>, strides = array<i64: 1, 1>} : (tensor<6x6xf32>) -> tensor<6x1xf32>

  // Reshape slice0 from 6x1 to 6 (remove dim 1)
  %slice0_reshaped = stablehlo.reshape %slice0 : tensor<6x1xf32> to tensor<6xf32>

  // Initialize output column 0 = input[:,0]
  %out0 = %slice0_reshaped

  // For each next column j=1..5:
  // slice input[:,j], reshape to 6xf32
  // multiply elementwise with previous output column

  // slice dim=1 index 1
  %slice1 = stablehlo.slice %arg0 {start_indices = array<i64: 0, 1>, limit_indices = array<i64: 6, 2>, strides = array<i64: 1, 1>} : (tensor<6x6xf32>) -> tensor<6x1xf32>
  %slice1_reshaped = stablehlo.reshape %slice1 : tensor<6x1xf32> to tensor<6xf32>
  %out1 = stablehlo.multiply %out0, %slice1_reshaped : tensor<6xf32>

  // slice dim=1 index 2
  %slice2 = stablehlo.slice %arg0 {start_indices = array<i64: 0, 2>, limit_indices = array<i64: 6, 3>, strides = array<i64: 1, 1>} : (tensor<6x6xf32>) -> tensor<6x1xf32>
  %slice2_reshaped = stablehlo.reshape %slice2 : tensor<6x1xf32> to tensor<6xf32>
  %out2 = stablehlo.multiply %out1, %slice2_reshaped : tensor<6xf32>

  // slice dim=1 index 3
  %slice3 = stablehlo.slice %arg0 {start_indices = array<i64: 0, 3>, limit_indices = array<i64: 6, 4>, strides = array<i64: 1, 1>} : (tensor<6x6xf32>) -> tensor<6x1xf32>
  %slice3_reshaped = stablehlo.reshape %slice3 : tensor<6x1xf32> to tensor<6xf32>
  %out3 = stablehlo.multiply %out2, %slice3_reshaped : tensor<6xf32>

  // slice dim=1 index 4
  %slice4 = stablehlo.slice %arg0 {start_indices = array<i64: 0, 4>, limit_indices = array<i64: 6, 5>, strides = array<i64: 1, 1>} : (tensor<6x6xf32>) -> tensor<6x1xf32>
  %slice4_reshaped = stablehlo.reshape %slice4 : tensor<6x1xf32> to tensor<6xf32>
  %out4 = stablehlo.multiply %out3, %slice4_reshaped : tensor<6xf32>

  // slice dim=1 index 5
  %slice5 = stablehlo.slice %arg0 {start_indices = array<i64: 0, 5>, limit_indices = array<i64: 6, 6>, strides = array<i64: 1, 1>} : (tensor<6x6xf32>) -> tensor<6x1xf32>
  %slice5_reshaped = stablehlo.reshape %slice5 : tensor<6x1xf32> to tensor<6xf32>
  %out5 = stablehlo.multiply %out4, %slice5_reshaped : tensor<6xf32>

  // Now we have 6 vectors of shape 6xf32: out0..out5
  // We need to stack them back along dim=1 to shape 6x6xf32

  // Reshape each outN from 6 to 6x1
  %out0_2d = stablehlo.reshape %out0 : tensor<6xf32> to tensor<6x1xf32>
  %out1_2d = stablehlo.reshape %out1 : tensor<6xf32> to tensor<6x1xf32>
  %out2_2d = stablehlo.reshape %out2 : tensor<6xf32> to tensor<6x1xf32>
  %out3_2d = stablehlo.reshape %out3 : tensor<6xf32> to tensor<6x1xf32>
  %out4_2d = stablehlo.reshape %out4 : tensor<6xf32> to tensor<6x1xf32>
  %out5_2d = stablehlo.reshape %out5 : tensor<6xf32> to tensor<6x1xf32>

  // Concatenate along dim=1 (second dimension)
  %result = stablehlo.concatenate %out0_2d, %out1_2d, %out2_2d, %out3_2d, %out4_2d, %out5_2d {dimension = 1 : i64} : (tensor<6x1xf32>, tensor<6x1xf32>, tensor<6x1xf32>, tensor<6x1xf32>, tensor<6x1xf32>, tensor<6x1xf32>) -> tensor<6x6xf32>

  stablehlo.return %result : tensor<6x6xf32>
}

