func.func @main(%conv_transpose_weight: tensor<3x16x3x3x3xf32>, %conv_transpose_bias: tensor<16xf32>, %bn_weight: tensor<16xf32>, %bn_bias: tensor<16xf32>, %input: tensor<6x3x7x7x7xf32>) -> tensor<6x16x3x3x3xf32> {
