  // b=batch, f=feature, h=height, w=width, o=out_channels, i=in_channels, kh=kernel_h, kw=kernel_w
  // stablehlo.conv<[b, f, 2, 3]x[o, i, 2, 3]->[b, f, 2, 3]>
  %conv = "stablehlo.convolution"(%input, %conv_weight) {
