  // HardSwish: x * relu6(x + 3) / 6
  // relu6(x) = min(max(x, 0), 6)
  %three = stablehlo.constant dense<3.0> : tensor<f32>
  %six = stablehlo.constant dense<6.0> : tensor<f32>
  %zero = stablehlo.constant dense<0.0> : tensor<f32>

  // Broadcast constants
  %three_b = "stablehlo.broadcast_in_dim"(%three) {broadcast_dimensions = array<i64:>} : (tensor<f32>) -> tensor<6x6x4x4xf32>
  %six_b = "stablehlo.broadcast_in_dim"(%six) {broadcast_dimensions = array<i64:>} : (tensor<f32>) -> tensor<6x6x4x4xf32>
  %zero_b = "stablehlo.broadcast_in_dim"(%zero) {broadcast_dimensions = array<i64:>} : (tensor<f32>) -> tensor<6x6x4x4xf32>

  %x_plus_3 = stablehlo.add %subtracted, %three_b : tensor<6x6x4x4xf32>
  %max_x_0 = stablehlo.maximum %x_plus_3, %zero_b : tensor<6x6x4x4xf32>
  %relu6 = stablehlo.minimum %max_x_0, %six_b : tensor<6x6x4x4xf32>
  %mul = stablehlo.multiply %subtracted, %relu6 : tensor<6x6x4x4xf32>
  %six_b_for_div = %six_b
  %hardswish = stablehlo.divide %mul, %six_b_for_div : tensor<6x6x4x4xf32>

