  } : (tensor<6x6x4x4xf32>, tensor<f32>) -> tensor<6x6x2x2xf32>

  // Mish activation: x * tanh(softplus(x))
  // softplus(x) = log(1 + exp(x))
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_b = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x2x2xf32>

  %exp_x = stablehlo.exponential %maxpool : tensor<6x6x2x2xf32>
  %exp_x_plus_1 = stablehlo.add %exp_x, %one_b : tensor<6x6x2x2xf32>
  %softplus = stablehlo.log %exp_x_plus_1 : tensor<6x6x2x2xf32>
  %tanh_softplus = stablehlo.tanh %softplus : tensor<6x6x2x2xf32>
  %mish = stablehlo.multiply %maxpool, %tanh_softplus : tensor<6x6x2x2xf32>

  stablehlo.return %mish : tensor<6x6x2x2xf32>
}

