func.func @main(%arg0: tensor<7x7xf32>, %arg1: tensor<7xf32>, %arg2: tensor<7xf32>, %arg3: tensor<7xf32>, %arg4: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // %arg0 = gemm.weight (7x7)
  // %arg1 = gemm.bias (7)
  // %arg2 = batch_norm.weight (7)
  // %arg3 = batch_norm.bias (7)
  // %arg4 = input (6x7)

  // GEMM: x = input @ weight^T + bias
  // weight is (7x7), input is (6x7), so we transpose weight to (7x7) to (7x7) (actually same shape)
  // but PyTorch Linear does x @ weight^T + bias, so we transpose weight
  %weight_t = "stablehlo.transpose"(%arg0) {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>
  %gemm = "stablehlo.dot_general"(%arg4, %weight_t) {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [],
      rhs_batching_dimensions = [],
      lhs_contracting_dimensions = [1],
      rhs_contracting_dimensions = [1]>
  } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>
  // Add bias: broadcast bias (7) to (6x7)
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %gemm_bias = stablehlo.add %gemm, %bias_broadcast : tensor<6x7xf32>

  // BatchNorm1d in training mode:
  // batch_norm(x) = weight * ((x - mean) / sqrt(var + eps)) + bias
  // mean and var computed over batch dimension (dim 0)
  // eps = 1e-5 (PyTorch default)
  // Compute mean over dim 0 (batch dimension)
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %init_mean = stablehlo.constant dense<0.0> : tensor<f32>
  %mean = "stablehlo.reduce"(%gemm_bias, %init_mean) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>
  // mean = sum / batch_size (6)
  %batch_size = stablehlo.constant dense<6.0> : tensor<f32>
  %mean_div = stablehlo.divide %mean, %batch_size : tensor<7xf32>

  // Compute variance: var = mean((x - mean)^2)
  // First broadcast mean to (6x7)
  %mean_broadcast = "stablehlo.broadcast_in_dim"(%mean_div) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %diff = stablehlo.subtract %gemm_bias, %mean_broadcast : tensor<6x7xf32>
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<6x7xf32>
  %init_var = stablehlo.constant dense<0.0> : tensor<f32>
  %var_sum = "stablehlo.reduce"(%diff_sq, %init_var) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>
  %var = stablehlo.divide %var_sum, %batch_size : tensor<7xf32>

  // eps constant
  %eps = stablehlo.constant dense<0.00001> : tensor<f32>
  %var_eps = stablehlo.add %var, %eps : tensor<7xf32>
  %rsqrt_var_eps = stablehlo.rsqrt %var_eps : tensor<7xf32>

  // Normalize: (x - mean) / sqrt(var + eps)
  %normalized = stablehlo.multiply %diff, "stablehlo.broadcast_in_dim"(%rsqrt_var_eps) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>

  // Scale and shift: weight * normalized + bias
  %weight_broadcast = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %scaled = stablehlo.multiply %weight_broadcast, %normalized : tensor<6x7xf32>
  %bias_bn_broadcast = "stablehlo.broadcast_in_dim"(%arg3) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %batch_norm_out = stablehlo.add %scaled, %bias_bn_broadcast : tensor<6x7xf32>

  // GELU activation: x * 0.5 * (1 + erf(x / sqrt(2)))
  // constants
  %half = stablehlo.constant dense<0.5> : tensor<f32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %sqrt2 = stablehlo.constant dense<1.4142135381698608> : tensor<f32>  // approx sqrt(2)

  %div_sqrt2 = stablehlo.divide %batch_norm_out, %sqrt2 : tensor<6x7xf32>
  %erf_val = chlo.erf %div_sqrt2 : tensor<6x7xf32> -> tensor<6x7xf32>
  %one_plus_erf = stablehlo.add %one, %erf_val : tensor<6x7xf32>
  %half_mul = stablehlo.multiply %half, %one_plus_erf : tensor<6x7xf32>
  %gelu_out = stablehlo.multiply %batch_norm_out, %half_mul : tensor<6x7xf32>

  // ReLU activation: max(0, x)
  %zero_tensor = stablehlo.constant dense<0.0> : tensor<6x7xf32>
  %relu_out = stablehlo.maximum %gelu_out, %zero_tensor : tensor<6x7xf32>

  "stablehlo.return"(%relu_out) : tensor<6x7xf32>
}

func.func @main(%arg0: tensor<7x7xf32>, %arg1: tensor<7xf32>, %arg2: tensor<7xf32>, %arg3: tensor<7xf32>, %arg4: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // %arg0 = gemm.weight (7x7)
  // %arg1 = gemm.bias (7)
  // %arg2 = batch_norm.weight (7)
  // %arg3 = batch_norm.bias (7)
  // %arg4 = input (6x7)

  // GEMM: x = input @ weight^T + bias
  // weight shape is (7 out_features x 7 in_features)
  // input shape is (6 batch x 7 in_features)
  // We want to do input (6x7) dot weight^T (7x7) -> (6x7)
  // So transpose weight to (7x7) -> (7x7) but actually weight is square, so transpose permutes last two dims
  %weight_t = "stablehlo.transpose"(%arg0) {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>
  %gemm = "stablehlo.dot_general"(%arg4, %weight_t) {dot_dimension_numbers = #stablehlo.dot<lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [1]>} : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

  // Add bias: broadcast bias (7) to (6x7)
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %gemm_bias = stablehlo.add %gemm, %bias_broadcast : tensor<6x7xf32>

  // BatchNorm1d forward (training mode):
  // y = weight * ((x - mean) / sqrt(var + eps)) + bias
  // mean = reduce mean over batch dimension (dim 0)
  // var = reduce variance over batch dimension (dim 0)
  // eps = 1e-5 (typical default for PyTorch BatchNorm1d)
  // weight and bias are batch_norm.weight and batch_norm.bias (both shape 7)
  // input to batchnorm is gemm_bias (6x7)

  // Compute mean over batch dim 0: shape (7)
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %init_mean = stablehlo.constant dense<0.0> : tensor<f32>
  %mean = "stablehlo.reduce"(%gemm_bias, %init_mean) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>

  // Divide mean by batch size 6 (convert 6 to f32)
  %six_f32 = stablehlo.constant dense<6.000000e+00> : tensor<f32>
  %mean_scaled = stablehlo.divide %mean, %six_f32 : tensor<7xf32>

  // Compute variance: mean of squared differences
  // First compute (x - mean) for each element: broadcast mean (7) to (6x7)
  %mean_broadcast = "stablehlo.broadcast_in_dim"(%mean_scaled) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %diff = stablehlo.subtract %gemm_bias, %mean_broadcast : tensor<6x7xf32>
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<6x7xf32>

  // Sum squared differences over batch dim 0
  %init_var = stablehlo.constant dense<0.0> : tensor<f32>
  %var_sum = "stablehlo.reduce"(%diff_sq, %init_var) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>

  // variance = var_sum / 6
  %var = stablehlo.divide %var_sum, %six_f32 : tensor<7xf32>

  // eps constant
  %eps = stablehlo.constant dense<1.000000e-05> : tensor<f32>

  // var + eps
  %var_eps = stablehlo.add %var, %eps : tensor<7xf32>

  // sqrt(var + eps)
  %stddev = stablehlo.sqrt %var_eps : tensor<7xf32>

  // Normalize: (x - mean) / stddev
  // Broadcast stddev (7) to (6x7)
  %stddev_broadcast = "stablehlo.broadcast_in_dim"(%stddev) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %norm = stablehlo.divide %diff, %stddev_broadcast : tensor<6x7xf32>

  // Scale and shift: weight * norm + bias
  // Broadcast weight and bias (7) to (6x7)
  %weight_broadcast = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %bias_bn_broadcast = "stablehlo.broadcast_in_dim"(%arg3) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %scaled = stablehlo.multiply %weight_broadcast, %norm : tensor<6x7xf32>
  %batchnorm_out = stablehlo.add %scaled, %bias_bn_broadcast : tensor<6x7xf32>

  // GELU activation: x * 0.5 * (1 + erf(x / sqrt(2)))
  // Compute x / sqrt(2)
  %sqrt2 = stablehlo.constant dense<1.4142135> : tensor<f32>  // approx sqrt(2)
  %sqrt2_broadcast = "stablehlo.broadcast_in_dim"(%sqrt2) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<f32>
  // Actually scalar constant, so just use scalar ops:
  // We need to divide batchnorm_out by sqrt(2)
  // Broadcast sqrt2 scalar to tensor<6x7xf32> by broadcast_in_dim with empty dims (rank 0 to rank 2)
  %sqrt2_scalar = stablehlo.constant dense<1.4142135> : tensor<f32>
  %sqrt2_broadcasted = "stablehlo.broadcast_in_dim"(%sqrt2_scalar) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7xf32>
  %x_div_sqrt2 = stablehlo.divide %batchnorm_out, %sqrt2_broadcasted : tensor<6x7xf32>

  // erf(x / sqrt(2))
  %erf = chlo.erf %x_div_sqrt2 : tensor<6x7xf32> -> tensor<6x7xf32>

  // 1 + erf(...)
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_broadcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7xf32>
  %one_plus_erf = stablehlo.add %one_broadcast, %erf : tensor<6x7xf32>

  // x * 0.5 * (1 + erf(...))
  %half = stablehlo.constant dense<0.5> : tensor<f32>
  %half_broadcast = "stablehlo.broadcast_in_dim"(%half) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7xf32>
  %x_times_half = stablehlo.multiply %batchnorm_out, %half_broadcast : tensor<6x7xf32>
  %gelu = stablehlo.multiply %x_times_half, %one_plus_erf : tensor<6x7xf32>

  // ReLU activation: max(0, gelu)
  %zero_broadcast = "stablehlo.broadcast_in_dim"(%zero_f32) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7xf32>
  %relu = stablehlo.maximum %gelu, %zero_broadcast : tensor<6

func.func @main(%arg0: tensor<7x7xf32>, %arg1: tensor<7xf32>, %arg2: tensor<7xf32>, %arg3: tensor<7xf32>, %arg4: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // %arg0: gemm.weight (7x7)
  // %arg1: gemm.bias (7)
  // %arg2: batch_norm.weight (7)
  // %arg3: batch_norm.bias (7)
  // %arg4: input (6x7)

  // Step 1: GEMM: x @ W^T + b
  // gemm.weight shape is (7,7) = (out_features, in_features)
  // input shape is (6,7) = (batch_size, in_features)
  // We want: output shape (6,7) = (batch_size, out_features)
  // So do dot_general with contracting dims: input dim 1 and weight dim 1
  // But weight needs to be transposed to (7,7) -> (7,7) (actually same shape)
  // Actually, gemm.weight is (out_features, in_features) = (7,7)
  // input is (6,7)
  // So dot_general contracting input dim 1 and weight dim 1, batching none
  // Result shape: (6,7) (batch_size, out_features)
  // So dot_general lhs_contracting=[1], rhs_contracting=[1], lhs_batching=[], rhs_batching=[]
  %weight_t = "stablehlo.transpose"(%arg0) {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>
  %dot = "stablehlo.dot_general"(%arg4, %weight_t) {dot_dimension_numbers = #stablehlo.dot<lhs_batching_dimensions = [], rhs_batching_dimensions = [], lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [1]>} : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

  // Add bias: broadcast bias (7) to (6,7)
  %bias_bcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %add_bias = stablehlo.add %dot, %bias_bcast : tensor<6x7xf32>

  // Step 2: BatchNorm1d (training mode)
  // batch_norm.weight and batch_norm.bias are scale and shift (gamma and beta)
  // Compute mean and variance over batch dimension (dim 0) for each feature (dim 1)
  // mean = reduce mean over dim 0
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %init_mean = "stablehlo.broadcast_in_dim"(%zero_f32) {broadcast_dimensions = array<i64: 0} : (tensor<f32>) -> tensor<7xf32>
  %mean = "stablehlo.reduce"(%add_bias, %init_mean) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<7xf32>) -> tensor<7xf32>

  // mean / 6 (batch_size)
  %six = stablehlo.constant dense<6.0> : tensor<f32>
  %six_bcast = "stablehlo.broadcast_in_dim"(%six) {broadcast_dimensions = array<i64: 0} : (tensor<f32>) -> tensor<7xf32>
  %mean_div = stablehlo.divide %mean, %six_bcast : tensor<7xf32>

  // Compute variance: mean of squared differences
  // diff = x - mean
  // broadcast mean to (6,7)
  %mean_bcast = "stablehlo.broadcast_in_dim"(%mean_div) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %diff = stablehlo.subtract %add_bias, %mean_bcast : tensor<6x7xf32>

  // square diff
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<6x7xf32>

  // sum of squared diff over batch dim 0
  %init_var = "stablehlo.broadcast_in_dim"(%zero_f32) {broadcast_dimensions = array<i64: 0} : (tensor<f32>) -> tensor<7xf32>
  %var_sum = "stablehlo.reduce"(%diff_sq, %init_var) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<7xf32>) -> tensor<7xf32>

  // variance = var_sum / 6
  %var = stablehlo.divide %var_sum, %six_bcast : tensor<7xf32>

  // epsilon for numerical stability
  %eps = stablehlo.constant dense<1.000000e-05> : tensor<f32>
  %eps_bcast = "stablehlo.broadcast_in_dim"(%eps) {broadcast_dimensions = array<i64: 0} : (tensor<f32>) -> tensor<7xf32>

  // variance + epsilon
  %var_eps = stablehlo.add %var, %eps_bcast : tensor<7xf32>

  // sqrt(variance + epsilon)
  %stddev = stablehlo.sqrt %var_eps : tensor<7xf32>

  // broadcast stddev to (6,7)
  %stddev_bcast = "stablehlo.broadcast_in_dim"(%stddev) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>

  // normalize: (x - mean) / stddev
  %norm = stablehlo.divide %diff, %stddev_bcast : tensor<6x7xf32>

  // scale (batch_norm.weight) and shift (batch_norm.bias)
  // broadcast scale and shift to (6,7)
  %scale_bcast = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %shift_bcast = "stablehlo.broadcast_in_dim"(%arg3) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>

  // scaled = norm * scale
  %scaled = stablehlo.multiply %norm, %scale_bcast : tensor<6x7xf32>

  // shifted = scaled + shift
  %shifted = stablehlo.add %scaled, %shift_bcast : tensor<6x7xf32>

  // Step 3: GELU activation (approximate with erf)
  // gelu(x) = 0.5 * x * (1 + erf(x / sqrt(2)))
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %half = stablehlo.constant dense<0.5> : tensor<f32>
  %sqrt2 = stablehlo.constant dense<1.4142135> : tensor<f32>
  %sqrt2_bcast = "stablehlo.broadcast_in_dim"(%sqrt2) {broadcast_dimensions = array<i64: 0} : (tensor<f32>) -> tensor<f32>
  // broadcast sqrt2 to shape (6,7)
  %sqrt2_bcast_6x7 = "stablehlo.broadcast_in_dim"(%sqrt2) {broadcast_dimensions = array<i64: 0} : (tensor<f32>) -> tensor<6x7xf32>

  // x / sqrt(2)
  %x_div_sqrt2 = stablehlo.divide %shifted, %sqrt2_bcast_6x7 : tensor<6x7xf32>

  // erf(x / sqrt(2))
  %erf_val = "chlo.erf"(%x_div_sqrt2) : (tensor<6x7xf32>) -> tensor<6x7xf32>

  // 1 + erf(...)
  %one_bcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: 0} : (tensor<f32>) -> tensor<6x7xf32>
  %one_plus_erf = stablehlo.add %one_bcast, %erf_val : tensor<6x7xf32>

  // 0.5 * x * (1 + erf(...))
  %half_bcast = "stablehlo.broadcast_in_dim"(%half) {broadcast_dimensions = array<i64: 0} : (tensor<f32>) -> tensor

func.func @main(%arg0: tensor<7x7xf32>, %arg1: tensor<7xf32>, %arg2: tensor<7xf32>, %arg3: tensor<7xf32>, %arg4: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // %arg0 = gemm.weight (7x7)
  // %arg1 = gemm.bias (7)
  // %arg2 = batch_norm.weight (7)
  // %arg3 = batch_norm.bias (7)
  // %arg4 = input (6x7)

  // GEMM: x @ W^T + b
  // dot_general lhs: %arg4 (6x7), rhs: %arg0 (7x7)
  // We want to do: (6x7) dot (7x7) with contracting dims (1) and (1)
  // But gemm.weight is (7x7) with shape (out_features x in_features)
  // PyTorch Linear does x @ W^T + b, so we transpose %arg0 to get (7x7) -> (7x7) (transpose dims 1,0)
  // Actually, since both are 7x7, transpose swaps dims 0 and 1
  %w_t = "stablehlo.transpose"(%arg0) {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>

  // dot_general with contracting dims: lhs contract dim 1, rhs contract dim 0
  %dot = "stablehlo.dot_general"(%arg4, %w_t) {dot_dimension_numbers = #stablehlo.dot<lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>} : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

  // Add bias: broadcast bias (7) to (6x7)
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %add_bias = stablehlo.add %dot, %bias_broadcast : tensor<6x7xf32>

  // BatchNorm1d in training mode:
  // y = (x - mean) / sqrt(var + eps) * weight + bias
  // mean = reduce mean over batch dim (dim 0)
  // var = reduce variance over batch dim (dim 0)
  // eps = 1e-5 (typical default)

  // Compute mean over dim 0 (batch dimension)
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %init_mean = "stablehlo.broadcast_in_dim"(%zero_f32) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<7xf32>
  %sum = "stablehlo.reduce"(%add_bias, %init_mean) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<7xf32>) -> tensor<7xf32>

  // Compute mean = sum / batch_size (6)
  %six = stablehlo.constant dense<6.0> : tensor<f32>
  %six_broadcast = "stablehlo.broadcast_in_dim"(%six) {broadcast_dimensions = array<i64>} : (tensor<f32>) -> tensor<7xf32>
  %mean = stablehlo.divide %sum, %six_broadcast : tensor<7xf32>

  // Broadcast mean to (6x7)
  %mean_broadcast = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>

  // Compute (x - mean)
  %x_centered = stablehlo.subtract %add_bias, %mean_broadcast : tensor<6x7xf32>

  // Compute variance:
  // var = mean((x - mean)^2) over batch dim 0
  %x_centered_sq = stablehlo.multiply %x_centered, %x_centered : tensor<6x7xf32>

  %zero_f32_var = stablehlo.constant dense<0.0> : tensor<f32>
  %init_var = "stablehlo.broadcast_in_dim"(%zero_f32_var) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<7xf32>
  %sum_sq = "stablehlo.reduce"(%x_centered_sq, %init_var) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<7xf32>) -> tensor<7xf32>

  // var = sum_sq / 6
  %var = stablehlo.divide %sum_sq, %six_broadcast : tensor<7xf32>

  // eps = 1e-5
  %eps = stablehlo.constant dense<0.00001> : tensor<f32>
  %eps_broadcast = "stablehlo.broadcast_in_dim"(%eps) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<7xf32>

  // var + eps
  %var_eps = stablehlo.add %var, %eps_broadcast : tensor<7xf32>

  // sqrt(var + eps)
  %stddev = stablehlo.sqrt %var_eps : tensor<7xf32>

  // Broadcast stddev to (6x7)
  %stddev_broadcast = "stablehlo.broadcast_in_dim"(%stddev) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>

  // Normalize: (x - mean) / stddev
  %x_norm = stablehlo.divide %x_centered, %stddev_broadcast : tensor<6x7xf32>

  // Apply batch_norm.weight (scale) and batch_norm.bias (shift)
  // Broadcast weight and bias to (6x7)
