  %rev = "stablehlo.reverse"(%arg1) {dimensions = array<i64: 2, 3, 4>} : (tensor<8x6x7x7x7xf32>) -> tensor<8x6x7x7x7xf32>

  // Perform convolution with:
  // window_strides = 1 (no stride)
  // padding = 1 on all spatial dims (to achieve output size 9 from input 7 and kernel 3)
  // lhs_dilation = 1 (no dilation on input)
  // rhs_dilation = 1 (no dilation on kernel)
  // dimension_numbers = [b, i, d, h, w] x [i, o, kd, kh, kw] -> [b, o, d, h, w]
  // feature_group_count = 1
  %conv = "stablehlo.convolution"(%rev, %arg0) {
    window_strides = array<i64: 1, 1, 1>,
    padding = dense<[[1, 1], [1, 1], [1, 1]]> : tensor<3x2xi64>,
    lhs_dilation = array<i64: 1, 1, 1>,
    rhs_dilation = array<i64: 1, 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, i, 2, 3, 4]x[i, o, 2, 3, 4]->[b, o, 2, 3, 4]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<8x6x7x7x7xf32>, tensor<6x6x3x3x3xf32>) -> tensor<8x6x9x9x9xf32>

  // Reverse spatial dims of output to get final result
  %out = "stablehlo.reverse"(%conv) {dimensions = array<i64: 2, 3, 4>} : (tensor<8x6x9x9x9xf32>) -> tensor<8x6x9x9x9xf32>

  return %out : tensor<8x6x9x9x9xf32>
}

