  // x_centered = conv_bias_added - mean_bcast_reshaped
  %x_centered = stablehlo.subtract %conv_bias_added, %mean_bcast_reshaped : tensor<6x7x4x4xf32>

  // Compute variance: mean of squared differences
  %x_centered_squared = stablehlo.multiply %x_centered, %x_centered : tensor<6x7x4x4xf32>
  %var_sum = "stablehlo.reduce"(%x_centered_squared, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0, 2, 3>} : (tensor<6x7x4x4xf32>, tensor<f32>) -> tensor<7xf32>
  %variance = stablehlo.divide %var_sum, %divisor : tensor<7xf32>

