  // Normalize: x_centered / stddev_bcast_reshaped
  %x_norm = stablehlo.divide %x_centered, %stddev_bcast_reshaped : tensor<6x7x4x4xf32>

  // Broadcast bn_weight and bn_bias to [6x7x4x4]
  %bn_weight_bcast = "stablehlo.broadcast_in_dim"(%bn_weight) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<1x7x1x1xf32>
  %bn_weight_bcast_reshaped = "stablehlo.broadcast_in_dim"(%bn_weight_bcast) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<1x7x1x1xf32>) -> tensor<6x7x4x4xf32>
  %bn_bias_bcast = "stablehlo.broadcast_in_dim"(%bn_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<1x7x1x1xf32>
  %bn_bias_bcast_reshaped = "stablehlo.broadcast_in_dim"(%bn_bias_bcast) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<1x7x1x1xf32>) -> tensor<6x7x4x4xf32>

  // Apply batch norm: x_norm * bn_weight + bn_bias
  %scaled = stablehlo.multiply %x_norm, %bn_weight_bcast_reshaped : tensor<6x7x4x4xf32>
