  // scaling_factor constant = 2.0
  %scaling_factor = stablehlo.constant dense<2.0> : tensor<f32>

  // Broadcast scaling_factor to [6x7x4x4]
  %scaling_factor_bcast = "stablehlo.broadcast_in_dim"(%scaling_factor) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7x4x4xf32>

  // Final output = bn_out * scaling_factor
  %output = stablehlo.multiply %bn_out, %scaling_factor_bcast : tensor<6x7x4x4xf32>

  return %output : tensor<6x7x4x4xf32>
}

func.func @main(%conv_weight: tensor<7x8x3x3xf32>, %conv_bias: tensor<7xf32>, %bn_weight: tensor<7xf32>, %bn_bias: tensor<7xf32>, %input: tensor<6x8x6x6xf32>) -> tensor<6x7x4x4xf32> {
