  // input: [6,8,6,6], weight: [7,8,3,3]
  // stride=1, padding=0, dilation=1, groups=1
  // dimension_numbers: input [b,f,h,w], kernel [o,i,h,w], output [b,f,h,w]
  %zero_padding = stablehlo.constant dense<0> : tensor<i64>
