  // bn.weight (gamma): %bn_weight [7]
  // bn.bias (beta): %bn_bias [7]
  // batch mean and variance computed from conv_bias_added over batch and spatial dims (0,2,3)
  // axes to reduce: [0,2,3]

  // Compute mean over axes [0,2,3]
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %mean = "stablehlo.reduce"(%conv_bias_added, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0, 2, 3}} : (tensor<6x7x4x4xf32>, tensor<f32>) -> tensor<7xf32>

