  // First compute (x - mean)
  // Broadcast mean [7] to [6x7x4x4]
  %mean_broadcast = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7x4x4xf32>
  %diff = stablehlo.subtract %conv_bias_added, %mean_broadcast : tensor<6x7x4x4xf32>

  // Square diff
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<6x7x4x4xf32>

  // Compute variance = mean of diff_sq over axes [0,2,3]
  %variance = "stablehlo.reduce"(%diff_sq, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0, 2, 3}} : (tensor<6x7x4x4xf32>, tensor<f32>) -> tensor<7xf32>

  // Compute count = 6*4*4 = 96 as float constant
  %count = stablehlo.constant dense<96.0> : tensor<f32>

  // Compute mean and variance by dividing sums by count
  %count_broadcast = "stablehlo.broadcast_in_dim"(%count) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<f32>
  // Actually count is scalar, no broadcast needed for division with vector [7], so broadcast count to [7]
  %count_7 = "stablehlo.broadcast_in_dim"(%count) {broadcast_dimensions = array<i64: 0} : (tensor<f32>) -> tensor<7xf32>

  %mean_final = stablehlo.divide %mean, %count_7 : tensor<7xf32>
  %variance_final = stablehlo.divide %variance, %count_7 : tensor<7xf32>

  // epsilon for numerical stability
  %epsilon = stablehlo.constant dense<0.00001> : tensor<f32>

  // variance + epsilon
  %var_eps = stablehlo.add %variance_final, %epsilon : tensor<7xf32>

  // sqrt(variance + epsilon)
  %stddev = stablehlo.sqrt %var_eps : tensor<7xf32>

  // Normalize: (x - mean) / stddev
  // Broadcast mean_final and stddev to [6x7x4x4]
  %mean_final_bcast = "stablehlo.broadcast_in_dim"(%mean_final) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7x4x4xf32>
  %stddev_bcast = "stablehlo.broadcast_in_dim"(%stddev) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7x4x4xf32>

  %x_centered = stablehlo.subtract %conv_bias_added, %mean_final_bcast : tensor<6x7x4x4xf32>
  %x_norm = stablehlo.divide %x_centered, %stddev_bcast : tensor<6x7x4x4xf32>

  // Apply bn.weight (gamma) and bn.bias (beta)
  // Broadcast bn_weight and bn_bias to [6x7x4x4]
  %bn_weight_bcast = "stablehlo.broadcast_in_dim"(%bn_weight) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7x4x4xf32>
  %bn_bias_bcast = "stablehlo.broadcast_in_dim"(%bn_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7x4x4xf32>

  %scaled = stablehlo.multiply %x_norm, %bn_weight_bcast : tensor<6x7x4x4xf32>
  %shifted = stablehlo.add %scaled, %bn_bias_bcast : tensor<6x7x4x4xf32>

  // Multiply by scaling_factor = 2.0 (constant scalar)
  %scaling_factor = stablehlo.constant dense<2.0> : tensor<f32>
  // Broadcast scaling_factor scalar to [6x7x4x4]
  %scaling_factor_bcast = "stablehlo.broadcast_in_dim"(%scaling_factor) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7x4x4xf32>

  %output = stablehlo.multiply %shifted, %scaling_factor_bcast : tensor<6x7x4x4xf32>

  return %output : tensor<6x7x4x4xf32>
}

