func.func @main(%conv_weight: tensor<7x8x3x3xf32>, %conv_bias: tensor<7xf32>, %input: tensor<6x8x8x8xf32>) -> tensor<6xf32> {
  // Convolution: input (6x8x8x8), weight (7x8x3x3) -> output (6x7x6x6)
  // dimension_numbers: input [b, f, 0, 1] = [batch, in_channels, height, width]
  // kernel [o, i, 0, 1] = [out_channels, in_channels, kernel_h, kernel_w]
  // output [b, f, 0, 1] = [batch, out_channels, out_h, out_w]
  %conv = "stablehlo.convolution"(%input, %conv_weight) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 1, 1>,
