  %bias_broadcast = "stablehlo.broadcast_in_dim"(%conv_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<1x7x1x1xf32>
  %bias_broadcast_reshaped = "stablehlo.broadcast_in_dim"(%bias_broadcast) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<1x7x1x1xf32>) -> tensor<6x7x6x6xf32>
  %conv_bias_added = stablehlo.add %conv, %bias_broadcast_reshaped : tensor<6x7x6x6xf32>

