  %divisor_broadcast = "stablehlo.broadcast_in_dim"(%divisor) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<f32>) -> tensor<6x7x1x1xf32>
  %avg_pool = stablehlo.divide %avg_pool_sum, %divisor_broadcast : tensor<6x7x1x1xf32>

