    batch_group_count = 1 : i64
  } : (tensor<6x8x8x8xf32>, tensor<7x8x3x3xf32>) -> tensor<6x7x6x6xf32>

  // Add bias: broadcast bias from [7] to [6,7,6,6]
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7x6x6xf32>
  %conv_bias = stablehlo.add %conv, %bias_broadcast : tensor<6x7x6x6xf32>

  // Average Pooling with kernel size 4 (AvgPool2d with kernel=4, stride=4, no padding)
  // window_dimensions = [1,1,4,4] (batch and channel dims window=1)
  // window_strides = [1,1,4,4]
  // padding = 0
  // init = 0.0
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %avgpool_sum = "stablehlo.reduce_window"(%conv_bias, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  }) {
    window_dimensions = array<i64: 1, 1, 4, 4>,
    window_strides = array<i64: 1, 1, 4, 4>,
    padding = dense<[[0, 0], [0, 0], [0, 0], [0, 0]]> : tensor<4x2xi64>
  } : (tensor<6x7x6x6xf32>, tensor<f32>) -> tensor<6x7x1x1xf32>

  // Divide by window size (4*4=16) to get average
  %divisor = stablehlo.constant dense<16.0> : tensor<f32>
  %divisor_bcast = "stablehlo.broadcast_in_dim"(%divisor) {broadcast_dimensions = array<i64: 3>} : (tensor<f32>) -> tensor<6x7x1x1xf32>
  %avgpool = stablehlo.divide %avgpool_sum, %divisor_bcast : tensor<6x7x1x1xf32>

