  %avgpool_reshape = stablehlo.reshape %avgpool : tensor<6x7x1x1xf32> -> tensor<6x7xf32>

  // Apply sigmoid: sigmoid(x) = 1 / (1 + exp(-x))
  %neg = stablehlo.negate %avgpool_reshape : tensor<6x7xf32>
  %exp = stablehlo.exponential %neg : tensor<6x7xf32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_bcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: 1>} : (tensor<f32>) -> tensor<6x7xf32>
