  // After reshape, sum over dim 1 (channels)
  // But original sum dims are [1,2,3], here dims 2 and 3 are 1, so sum over dim 1 suffices
  // So sum over dim 1 of [6x7] -> [6]
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %sum = "stablehlo.reduce"(%sigmoid, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %add = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %add : tensor<f32>
  }) {dimensions = array<i64: 1>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<6xf32>

  return %sum : tensor<6xf32>
}

func.func @main(%arg0: tensor<7x7xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x7xf32>) -> tensor<6x1xf32> {
  // %arg0 = gemm.weight: tensor<7x7xf32>
  // %arg1 = gemm.bias: tensor<7xf32>
  // %arg2 = input: tensor<6x7xf32>

  // Compute gemm: x @ W^T + b
  // W^T shape: 7x7 -> transpose %arg0
  %t0 = "stablehlo.transpose"(%arg0) {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>
  // dot_general with contracting dims: input last dim (1), weight first dim (0)
  %t1 = "stablehlo.dot_general"(%arg2, %t0) {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [0],
      rhs_batching_dimensions = [],
      lhs_contracting_dimensions = [1],
      rhs_contracting_dimensions = [0]>
  } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>
  // broadcast bias to shape 6x7
  %t2 = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %t3 = stablehlo.add %t1, %t2 : tensor<6x7xf32>

  // max over dim=1, keepdim=True -> shape 6x1
  %t4 = "stablehlo.reduce"(%t3, stablehlo.constant dense<-inf> : tensor<f32>) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.maximum %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<6x1xf32>

  // mean over dim=1, keepdim=True
  // sum over dim=1
  %t5 = "stablehlo.reduce"(%t4, stablehlo.constant dense<0.0> : tensor<f32>) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x1xf32>, tensor<f32>) -> tensor<6x1xf32>

  // Actually %t4 shape is 6x1, so mean over dim=1 is just the same values (mean of single element)
  // But to be consistent, compute mean as sum / 1 (dim size)
  // dim size = 1, so mean = sum
  %t6 = %t4

  // subtract mean from max values: x = max - mean
  %t7 = stablehlo.subtract %t4, %t6 : tensor<6x1xf32>

  // GELU: x * 0.5 * (1 + erf(x / sqrt(2)))
  // constants
  %c_half = stablehlo.constant dense<0.5> : tensor<f32>
  %c_one = stablehlo.constant dense<1.0> : tensor<f32>
  %c_sqrt2 = stablehlo.constant dense<1.4142135381698608> : tensor<f32>  // sqrt(2)

  // x / sqrt(2)
  %t8 = stablehlo.divide %t7, %c_sqrt2 : tensor<6x1xf32>

  // erf(x / sqrt(2))
  %t9 = "chlo.erf"(%t8) : (tensor<6x1xf32>) -> tensor<6x1xf32>

  // 1 + erf(...)
  %t10 = stablehlo.add %c_one, %t9 : tensor<6x1xf32>

  // x * 0.5
  %t11 = stablehlo.multiply %t7, %c_half : tensor<6x1xf32>

  // gelu = x * 0.5 * (1 + erf(...))
  %t12 = stablehlo.multiply %t11, %t10 : tensor<6x1xf32>

  "stablehlo.return"(%t12) : tensor<6x1xf32>
}

func.func @main(%arg0: tensor<7x7xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x7xf32>) -> tensor<6x1xf32> {
  // %arg0 = gemm.weight (7x7)
  // %arg1 = gemm.bias (7)
  // %arg2 = input (6x7)

  // Compute gemm: x @ W^T + b
  // W^T shape: 7x7 -> transpose to 7x7 (same shape, but transpose needed for dot_general)
  %t0 = "stablehlo.transpose"(%arg0) {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>
  // dot_general: lhs batch dims [], rhs batch dims [], lhs contract dims [1], rhs contract dims [0]
  %t1 = "stablehlo.dot_general"(%arg2, %t0) {dot_dimension_numbers = #stablehlo.dot<lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>} : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>
