  %divisor_bcast = "stablehlo.broadcast_in_dim"(%divisor) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<f32> // scalar broadcast to scalar (no-op)
  %mean = stablehlo.divide %sum_bcast, %divisor : tensor<6x1xf32>

  // subtract mean from max
  %sub = stablehlo.subtract %max_bcast, %mean : tensor<6x1xf32>

  // GELU activation: x * 0.5 * (1 + erf(x / sqrt(2)))
  %half = stablehlo.constant dense<0.5> : tensor<f32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %sqrt2 = stablehlo.constant dense<1.4142135381698608> : tensor<f32>  // approx sqrt(2)
  %sqrt2_bcast = "stablehlo.broadcast_in_dim"(%sqrt2) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<f32> // scalar broadcast no-op
  %x_div_sqrt2 = stablehlo.divide %sub, %sqrt2 : tensor<6x1xf32>
  %erf = chlo.erf %x_div_sqrt2 : tensor<6x1xf32> -> tensor<6x1xf32>
  %one_plus_erf = stablehlo.add %one, %erf : tensor<6x1xf32>
  %half_mul = stablehlo.multiply %sub, %half : tensor<6x1xf32>
