func.func @main(%arg0: tensor<7x6x3x3xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x6x8x8xf32>) -> tensor<6x7x6x6xf32> {
  // %arg0 = conv.weight: [out_channels=7, in_channels=6, kernel_h=3, kernel_w=3]
  // %arg1 = conv.bias: [out_channels=7]
  // %arg2 = input: [batch=6, in_channels=6, height=8, width=8]

  // Perform convolution:
  // dimension_numbers = [b, f, h, w] x [o, i, kh, kw] -> [b, f, h, w]
  // Here: input dims: b=0, f=1, h=2, w=3
  // kernel dims: o=0, i=1, kh=2, kw=3
  // output dims: b=0, f=1, h=2, w=3
