  // But stablehlo.add supports broadcasting only if shapes match, so broadcast explicitly
  %one_broadcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: } : (tensor<f32>) -> tensor<6x7x6x6xf32>
  // The above line is incomplete, fix below.

  // Correct broadcast of scalar 1.0 to shape of conv_bias (6x7x6x6)
  %one_scalar = stablehlo.constant dense<1.0> : tensor<f32>
  %one_broadcast = "stablehlo.broadcast_in_dim"(%one_scalar) {broadcast_dimensions = array<i64: } : (tensor<f32>) -> tensor<6x7x6x6xf32>
  // Need to specify broadcast_dimensions = array<i64: > with length rank(operand) = 0, so empty array
  // So broadcast_dimensions = array<i64: > (empty)
  %one_broadcast = "stablehlo.broadcast_in_dim"(%one_scalar) {broadcast_dimensions = array<i64:>} : (tensor<f32>) -> tensor<6x7x6x6xf32>

  %exp_plus_one = stablehlo.add %exp_val, %one_broadcast : tensor<6x7x6x6xf32>
  %softplus = stablehlo.log %exp_plus_one : tensor<6x7x6x6xf32>

  // tanh(softplus)
  %tanh_softplus = stablehlo.tanh %softplus : tensor<6x7x6x6xf32>

  // mish = x * tanh(softplus(x))
  %mish1 = stablehlo.multiply %conv_bias, %tanh_softplus : tensor<6x7x6x6xf32>

  // Apply Mish again
  %exp_val2 = stablehlo.exponential %mish1 : tensor<6x7x6x6xf32>
  %exp_plus_one2 = stablehlo.add %exp_val2, %one_broadcast : tensor<6x7x6x6xf32>
  %softplus2 = stablehlo.log %exp_plus_one2 : tensor<6x7x6x6xf32>
  %tanh_softplus2 = stablehlo.tanh %softplus2 : tensor<6x7x6x6xf32>
  %mish2 = stablehlo.multiply %mish1, %tanh_softplus2 : tensor<6x7x6x6xf32>

  return %mish2 : tensor<6x7x6x6xf32>
}

func.func @main(%arg0: tensor<7x6x3x3xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x6x8x8xf32>) -> tensor<6x7x6x6xf32> {
