  %softplus = stablehlo.log %exp_plus_one : tensor<6x7x6x6xf32>

  // tanh(softplus)
  %tanh_softplus = stablehlo.tanh %softplus : tensor<6x7x6x6xf32>

  // mish = x * tanh(softplus(x))
  %mish1 = stablehlo.multiply %conv_bias, %tanh_softplus : tensor<6x7x6x6xf32>

  // Apply Mish again on mish1
  %exp2 = stablehlo.exponential %mish1 : tensor<6x7x6x6xf32>
  %exp_plus_one_2 = stablehlo.add %exp2, %one_broadcast : tensor<6x7x6x6xf32>
  %softplus2 = stablehlo.log %exp_plus_one_2 : tensor<6x7x6x6xf32>
  %tanh_softplus2 = stablehlo.tanh %softplus2 : tensor<6x7x6x6xf32>
  %mish2 = stablehlo.multiply %mish1, %tanh_softplus2 : tensor<6x7x6x6xf32>

  return %mish2 : tensor<6x7x6x6xf32>
}

func.func @main(%arg0: tensor<7x7xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x7xf32>) -> tensor<6x1xf32> {
