  // %arg1 = gemm.bias: tensor<7xf32>
  // %arg2 = input: tensor<6x7xf32>

  // Perform GEMM: x @ W^T + b
  // Note: PyTorch Linear weight shape is (out_features, in_features) = (7,7)
  // Input shape: (6,7)
  // We want: (6,7) @ (7,7)^T = (6,7) @ (7,7) = (6,7)
  // So we transpose weight to (7,7) (actually same shape), but dot_general contracting dims are input feature dims.
  // Contract input dim 1 with weight dim 1 (in_features)
  // Batch dims empty
  %weight_t = "stablehlo.transpose"(%arg0) {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>
