  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %add = stablehlo.add %dot, %bias_broadcast : tensor<6x7xf32>

  // max over dim=1 with keepdim=True
  // Reduce max over dim=1 (the feature dim)
  %init_max = stablehlo.constant dense<-inf> : tensor<f32>
  %max_reduce = "stablehlo.reduce"(%add, %init_max) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.maximum %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<6xf32>

  // Broadcast max_reduce from (6) to (6x1)
  %max_keepdim = "stablehlo.broadcast_in_dim"(%max_reduce) {broadcast_dimensions = array<i64: 0>} : (tensor<6xf32>) -> tensor<6x1xf32>

  // Compute mean over dim=1 with keepdim=True
  %init_zero = stablehlo.constant dense<0.0> : tensor<f32>
  %sum_reduce = "stablehlo.reduce"(%add, %init_zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<6xf32>

  // Divide sum by 7 (size of dim=1)
  %seven = stablehlo.constant dense<7.0> : tensor<f32>
  %seven_broadcast = "stablehlo.broadcast_in_dim"(%seven) {broadcast_dimensions = array<i64>} : (tensor<f32>) -> tensor<f32> // scalar broadcast to scalar (no-op)
  %mean = stablehlo.divide %sum_reduce, %seven : tensor<6xf32>

  // Broadcast mean from (6) to (6x1)
  %mean_keepdim = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = array<i64: 0>} : (tensor<6xf32>) -> tensor<6x1xf32>

  // Subtract mean_keepdim from max_keepdim
  %sub = stablehlo.subtract %max_keepdim, %mean_keepdim : tensor<6x1xf32>

