  %sqrt2_broadcast = "stablehlo.broadcast_in_dim"(%sqrt2) {broadcast_dimensions = array<i64>} : (tensor<f32>) -> tensor<f32> // scalar no-op
  %div = stablehlo.divide %sub, %sqrt2 : tensor<6x1xf32>

  // Compute erf(div)
  %erf = "chlo.erf"(%div) : (tensor<6x1xf32>) -> tensor<6x1xf32>

  // Compute 1 + erf(div)
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_broadcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64>} : (tensor<f32>) -> tensor<f32> // scalar no-op
  %one_tensor = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<f32>) -> tensor<6x1xf32>
  %one_plus_erf = stablehlo.add %one_tensor, %erf : tensor<6x1xf32>

  // Multiply by 0.5
  %half = stablehlo.constant dense<0.5> : tensor<f32>
  %half_tensor = "stablehlo.broadcast_in_dim"(%half) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<f32>) -> tensor<6x1xf32>
  %mul1 = stablehlo.multiply %one_plus_erf, %half_tensor : tensor<6x1xf32>

  // Multiply by x (sub)
  %gelu = stablehlo.multiply %sub, %mul1 : tensor<6x1xf32>

  return %gelu : tensor<6x1xf32>
}

