  // Add conv.bias (%arg2) to conv output
  // %arg2 shape: tensor<6xf32> (one bias per output channel)
  // conv output shape: tensor<6x6x4x4xf32> (batch=6, out_channels=6, height=4, width=4)
  // Need to broadcast %arg2 from [6] to [6x6x4x4]:
  // broadcast_in_dim with broadcast_dimensions = [1] (the channel dimension)
  %conv_bias_broadcast = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = array<i64: 1>} : (tensor<6xf32>) -> tensor<6x6x4x4xf32>

  %conv_plus_bias = stablehlo.add %conv, %conv_bias_broadcast : tensor<6x6x4x4xf32>

  // Minimum with constant 0.5
  // Create constant tensor 0.5 scalar
  %cst_0_5 = stablehlo.constant dense<0.5> : tensor<f32>
  // Broadcast scalar 0.5 to conv output shape
  %cst_0_5_broadcast = "stablehlo.broadcast_in_dim"(%cst_0_5) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x4x4xf32>

  %min = stablehlo.minimum %conv_plus_bias, %cst_0_5_broadcast : tensor<6x6x4x4xf32>

  // Add bias parameter %arg0: tensor<6x1x1xf32>
  // Need to broadcast %arg0 from [6x1x1] to [6x6x4x4]
  // %arg0 dims: [6,1,1]
  // output dims: [6,6,4,4]
  // broadcast_in_dim with broadcast_dimensions = [0,1,2] is invalid because input rank=3, output rank=4
  // We must reshape %arg0 to 6x1x1x1 to broadcast to 6x6x4x4
  %arg0_reshaped = stablehlo.reshape %arg0 : (tensor<6x1x1xf32>) -> tensor<6x1x1x1xf32>
  // broadcast_in_dim with broadcast_dimensions = [0,1,2,3]
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg0_reshaped) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<6x1x1x1xf32>) -> tensor<6x6x4x4xf32>

  %add_bias = stablehlo.add %min, %bias_broadcast : tensor<6x6x4x4xf32>

  // Multiply by scaling factor 2.0
  %cst_2 = stablehlo.constant dense<2.0> : tensor<f32>
  // Broadcast scalar 2.0 to output shape
  %cst_2_broadcast = "stablehlo.broadcast_in_dim"(%cst_2) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x4x4xf32>

  %scaled = stablehlo.multiply %add_bias, %cst_2_broadcast : tensor<6x6x4x4xf32>

  return %scaled : tensor<6x6x4x4xf32>
}

func.func @main(%arg0: tensor<6x1x1xf32>, %arg1: tensor<6x7x3x3xf32>, %arg2: tensor<6xf32>, %arg3: tensor<6x7x6x6xf32>) -> tensor<6x6x4x4xf32> {
  // Convolution parameters:
  // input: %arg3: tensor<6x7x6x6xf32>  (batch=6, in_channels=7, height=6, width=6)
  // weight: %arg1: tensor<6x7x3x3xf32> (out_channels=6, in_channels=7, kernel=3x3)
  // bias: %arg2: tensor<6xf32> (conv.bias)
  // additional bias: %arg0: tensor<6x1x1xf32> (to add after min)
  // scaling factor: 2.0 (constant)
  //
  // Output shape after conv with stride=1, padding=0, dilation=1:
  // output height/width = (6 - 3 + 1) = 4
  // output tensor shape: [6, 6, 4, 4]

  // Convolution dimension numbers:
  // input: [b, f, h, w] = [6,7,6,6]
  // kernel: [o, i, h, w] = [6,7,3,3]
  // output: [b, f, h, w] = [6,6,4,4]
  //
  // dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>
  // which means:
  // input dims: b=0, f=1, spatial dims=2,3
  // kernel dims: o=0, i=1, spatial dims=2,3
  // output dims: b=0, f=1, spatial dims=2,3

  %c_window_strides = stablehlo.constant dense<1, 1> : tensor<2xi64>
  %c_padding = stablehlo.constant dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>
  %c_lhs_dilation = stablehlo.constant dense<1, 1> : tensor<2xi64>
  %c_rhs_dilation = stablehlo.constant dense<1, 1> : tensor<2xi64>
  %c_feature_group_count = stablehlo.constant dense<1> : tensor<i64>
  %c_batch_group_count = stablehlo.constant dense<1> : tensor<i64>

  %conv = "stablehlo.convolution"(%arg3, %arg1) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 1, 1>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x7x6x6xf32>, tensor<6x7x3x3xf32>) -> tensor<6x6x4x4xf32>

  // Add conv.bias (%arg2) to conv output:
  // %arg2 shape: tensor<6xf32> (one bias per output channel)
  // conv output shape: tensor<6x6x4x4xf32> (batch=6, out_channels=6, h=4, w=4)
  // Need to broadcast %arg2 from [6] to [6x6x4x4]:
  // broadcast dimensions: [1] means %arg2 dims map to output dim 1 (channels)
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = array<i64: 1>} : (tensor<6xf32>) -> tensor<6x6x4x4xf32>

  %conv_plus_bias = stablehlo.add %conv, %bias_broadcast : tensor<6x6x4x4xf32>

  // Minimum with constant 0.5:
  // Create constant scalar tensor 0.5
  %c_0_5 = stablehlo.constant dense<0.5> : tensor<f32>
  // Broadcast scalar 0.5 to conv output shape [6x6x4x4]
  %c_0_5_broadcast = "stablehlo.broadcast_in_dim"(%c_0_5) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x4x4xf32>

  %min_result = stablehlo.minimum %conv_plus_bias, %c_0_5_broadcast : tensor<6x6x4x4xf32>

  // Add additional bias %arg0 (shape 6x1x1) to min_result:
  // %arg0 shape: tensor<6x1x1xf32>
  // min_result shape: tensor<6x6x4x4xf32>
  // Broadcast %arg0 to [6x6x4x4]:
  // %arg0 dims: 0,1,2
  // min_result dims: 0,1,2,3
  // We want to broadcast %arg0 dims 0->0, 1->1, 2->2, so broadcast_dimensions = [0,1,2]
  %bias2_broadcast = "stablehlo.broadcast_in_dim"(%arg0) {broadcast_dimensions = array<i64: 0, 1, 2>} : (tensor<6x1x1xf32>) -> tensor<6x6x4x4xf32>

  %add_bias2 = stablehlo.add %min_result, %bias2_broadcast : tensor<6x6x4x4xf32>

  // Multiply by scaling factor 2.0:
  %c_2_0 = stablehlo.constant dense<2.0> : tensor<f32>
  // Broadcast scalar 2.0 to output shape
  %c_2_0_broadcast = "stablehlo.broadcast_in_dim"(%c_2_0) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x4x4xf32>

  %scaled = stablehlo.multiply %add_bias2, %c_2_0_broadcast : tensor<6x6x4x4xf32>

  return %scaled : tensor<6x6x4x4xf32>
}

func.func @main(%arg0: tensor<6x1x1xf32>, %arg1: tensor<6x7x3x3xf32>, %arg2: tensor<6xf32>, %arg3: tensor<6x7x6x6xf32>) -> tensor<6x6x4x4xf32> {
  // %arg0 = bias parameter, shape [6,1,1]
  // %arg1 = conv.weight parameter, shape [6,7,3,3]
  // %arg2 = conv.bias parameter, shape [6]
  // %arg3 = input tensor, shape [6,7,6,6]

  // Perform convolution:
  // PyTorch Conv2d default layout is NCHW, kernel OIHW
  // StableHLO convolution dimension_numbers: input [b,f,0,1], kernel [o,i,0,1], output [b,f,0,1]
  // window_strides = [1,1], padding = 0, lhs_dilation = 1, rhs_dilation = 1
  %conv = "stablehlo.convolution"(%arg3, %arg1) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 1, 1>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x7x6x6xf32>, tensor<6x7x3x3xf32>) -> tensor<6x6x4x4xf32>

  // Add conv.bias (%arg2) to conv output:
  // conv output shape: [6,6,4,4]
  // conv.bias shape: [6]
  // Broadcast conv.bias to [6,6,4,4]
  %conv_bias_bcast = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = array<i64: 0>} : (tensor<6xf32>) -> tensor<6x1x1x1xf32>
  // Need to reshape broadcast to [6,6,4,4], so broadcast conv.bias along dims 1,2,3
  %conv_bias_bcast_reshaped = "stablehlo.broadcast_in_dim"(%conv_bias_bcast) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<6x1x1x1xf32>) -> tensor<6x6x4x4xf32>
  %conv_plus_bias = stablehlo.add %conv, %conv_bias_bcast_reshaped : tensor<6x6x4x4xf32>

  // Clamp with minimum constant 0.5
  %cst_0_5 = stablehlo.constant dense<0.5> : tensor<f32>
  // Broadcast scalar 0.5 to shape [6,6,4,4]
  %cst_0_5_bcast = "stablehlo.broadcast_in_dim"(%cst_0_5) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x4x4xf32>
  %clamped = stablehlo.minimum %conv_plus_bias, %cst_0_5_bcast : tensor<6x6x4x4xf32>

  // Add bias parameter %arg0 (shape [6x1x1]) to clamped output:
  // Broadcast %arg0 from [6x1x1] to [6x6x4x4]
  // %arg0 shape: [6,1,1], need to broadcast to [6,6,4,4]
  // Broadcast dims: arg0 dims 0->0, 1->1, 2->2, but arg0 has rank 3, output rank 4
  // So first broadcast_in_dim from [6x1x1] to [6x1x1x1] by adding a trailing dimension
  %arg0_4d = "stablehlo.broadcast_in_dim"(%arg0) {broadcast_dimensions = array<i64: 0, 1, 2>} : (tensor<6x1x1xf32>) -> tensor<6x1x1x1xf32>
  // Then broadcast to [6x6x4x4]
  %arg0_bcast = "stablehlo.broadcast_in_dim"(%arg0_4d) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<6x1x1x1xf32>) -> tensor<6x6x4x4xf32>
  %added_bias = stablehlo.add %clamped, %arg0_bcast : tensor<6x6x4x4xf32>

  // Multiply by scaling factor 2.0 (scalar)
  %cst_2 = stablehlo.constant dense<2.0> : tensor<f32>
  // Broadcast scalar 2.0 to [6x6x4x4]
  %cst_2_bcast = "stablehlo.broadcast_in_dim"(%cst_2) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x4x4xf32>
  %scaled = stablehlo.multiply %added_bias, %cst_2_bcast : tensor<6x6x4x4xf32>

  return %scaled : tensor<6x6x4x4xf32>
}

func.func @main(%arg0: tensor<6x7x8xf32>) -> tensor<6x8xf32> {
  %cst_zero = stablehlo.constant dense<0.0> : tensor<f32>
  %cst_seven = stablehlo.constant dense<7.0> : tensor<f32>
  %init = stablehlo.constant dense<0.0> : tensor<f32>
  %sum = "stablehlo.reduce"(%arg0, %init) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %add = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%add) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x7x8xf32>, tensor<f32>) -> tensor<6x8xf32>
  %result = stablehlo.divide %sum, %cst_seven : tensor<6x8xf32>
  return %result : tensor<6x8xf32>
}

func.func @main(%subtract: tensor<7xf32>, %weight: tensor<7x7xf32>, %bias: tensor<7xf32>, %input: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // Save original input for residual add
  %original_x = %input : tensor<6x7xf32>

  // GEMM: x @ weight^T + bias
  // weight shape: [7,7], input shape: [6,7]
  // We want: output shape [6,7] = input [6,7] * weight^T [7,7]
  // So contract input dim 1 with weight dim 1, batch dims empty
  %weight_t = "stablehlo.transpose"(%weight) {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>
  %gemm = "stablehlo.dot_general"(%input, %weight_t) {dot_dimension_numbers = #stablehlo.dot<lhs_batching_dimensions = [], rhs_batching_dimensions = [], lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [1]>} : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>
  %gemm_bias = "stablehlo.broadcast_in_dim"(%bias) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %x1 = stablehlo.add %gemm, %gemm_bias : tensor<6x7xf32>

  // Subtract: x - subtract (broadcast subtract from [7] to [6x7])
  %subtract_bcast = "stablehlo.broadcast_in_dim"(%subtract) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %x2 = stablehlo.subtract %x1, %subtract_bcast : tensor<6x7xf32>

  // GlobalAvgPool: mean over dim=1, keepdim=True
  // mean = sum / dim_size
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %init_sum = "stablehlo.broadcast_in_dim"(%zero_f32) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<f32>) -> tensor<6x7xf32>
  %dim_size = stablehlo.constant dense<7.0> : tensor<f32>
  %sum = "stablehlo.reduce"(%x2, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %add = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%add) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<6xf32>
  // sum shape: [6], need to broadcast to [6x1]
  %sum_reshaped = "stablehlo.broadcast_in_dim"(%sum) {broadcast_dimensions = array<i64: 0>} : (tensor<6xf32>) -> tensor<6x1xf32>
  // divide sum by 7.0 to get mean
  %dim_size_bcast = "stablehlo.broadcast_in_dim"(%dim_size) {broadcast_dimensions = array<i64: 1>} : (tensor<f32>) -> tensor<1xf32>
  %dim_size_bcast2 = "stablehlo.broadcast_in_dim"(%dim_size_bcast) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<1xf32>) -> tensor<6x1xf32>
  %mean = stablehlo.divide %sum_reshaped, %dim_size_bcast2 : tensor<6x1xf32>

  // LogSumExp: logsumexp over dim=1, keepdim=True
  // logsumexp(x) = log(sum(exp(x)))
  // x shape: [6x7], but here mean shape is [6x1], so logsumexp over dim=1 is trivial (dim=1 size=1)
  // But to follow spec, we do logsumexp on x2 (shape 6x7) over dim=1 keepdim=True
  // So redo logsumexp on x2:
  %exp_x2 = stablehlo.exponential %x2 : tensor<6x7xf32>
  %zero_f32_2 = stablehlo.constant dense<0.0> : tensor<f32>
  %sum_exp = "stablehlo.reduce"(%exp_x2, %zero_f32_2) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %add = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%add) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<6xf32>
  %sum_exp_reshaped = "stablehlo.broadcast_in_dim"(%sum_exp) {broadcast_dimensions = array<i64: 0>} : (tensor<6xf32>) -> tensor<6x1xf32>
  %log_sum_exp = stablehlo.log %sum_exp_reshaped : tensor<6x1xf32>

  // GELU: approximate GELU using erf: 0.5 * x * (1 + erf(x / sqrt(2)))
  // sqrt(2) constant
  %sqrt_2 = stablehlo.constant dense<1.4142135381698608> : tensor<f32>
  %sqrt_2_bcast = "stablehlo.broadcast_in_dim"(%sqrt_2) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<f32>) -> tensor<6x1xf32>
  %x_div_sqrt2 = stablehlo.divide %log_sum_exp, %sqrt_2_bcast : tensor<6x1xf32>
  %erf_x = chlo.erf %x_div_sqrt2 : tensor<6x1xf32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_bcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<f32>) -> tensor<6x1xf32>
  %one_plus_erf = stablehlo.add %one_bcast, %erf_x : tensor<6x1xf32>
  %half = stablehlo.constant dense<0.5> : tensor<f32>
  %half_bcast = "stablehlo.broadcast_in_dim"(%half) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<f32>) -> tensor<6x1xf32>
  %half_times_x = stablehlo.multiply %half_bcast, %log_sum_exp : tensor<6x1xf32>
  %gelu = stablehlo.multiply %half_times_x, %one_plus_erf : tensor<6x1xf32>

  // ResidualAdd: gelu + original_x
  // gelu shape: [6x1], original_x shape: [6x7]
  // Broadcast gelu along dim=1 to [6x7]
  %gelu_bcast = "stablehlo.broadcast_in_dim"(%gelu) {broadcast_dimensions = array<i64: 0} } : (tensor<6x1xf32>) -> tensor<6x7xf32>
  %residual = stablehlo.add %gelu_bcast, %original_x : tensor<6x7xf32>

  return %residual : tensor<6x7xf32>
}

func.func @main(%arg0: tensor<6x7x8xf32>) -> tensor<6x8xf32> {
  %cst_zero = stablehlo.constant dense<0.0> : tensor<f32>
  %cst_seven = stablehlo.constant dense<7.0> : tensor<f32>
  %init = stablehlo.constant dense<0.0> : tensor<f32>
  %sum = "stablehlo.reduce"(%arg0, %init) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %add = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%add) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x7x8xf32>, tensor<f32>) -> tensor<6x8xf32>
  %result = stablehlo.divide %sum, %cst_seven : tensor<6x8xf32>
  return %result : tensor<6x8xf32>
}

func.func @main(%arg0: tensor<7xf32>, %arg1: tensor<7x7xf32>, %arg2: tensor<7xf32>, %arg3: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // original_x = %arg3 (input)
  %original_x = %arg3 : tensor<6x7xf32>

  // Gemm: x = %arg3 @ %arg1^T + %arg2
  // dot_general with contracting dims: lhs contract dim 1, rhs contract dim 1
  // lhs_batching_dims = [0], rhs_batching_dims = []
  // lhs shape: 6x7, rhs shape: 7x7
  // We want to do x @ W^T, where W is 7x7, so W^T is 7x7 (same shape)
  // Actually, PyTorch Linear does x @ W^T + b, where W is (out_features x in_features)
  // Here gemm.weight is 7x7, so W shape is (out_features x in_features) = 7x7
  // Input x shape is (batch_size x in_features) = 6x7
  // So x @ W^T is (6x7) @ (7x7) = 6x7
  // So we do dot_general with contracting dims lhs:1, rhs:1, no batching dims
  %dot = "stablehlo.dot_general"(%arg3, %arg1) {dot_dimension_numbers = #stablehlo.dot<lhs_batching_dimensions = [], rhs_batching_dimensions = [], lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [1]>} : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

  // Add bias %arg2 (7xf32) to each row of %dot (6x7xf32)
  // Broadcast bias to (6x7)
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %x_with_bias = stablehlo.add %dot, %bias_broadcast : tensor<6x7xf32>

  // Subtract: x = x - subtract (7xf32)
  // Broadcast subtract to (6x7)
  %subtract_broadcast = "stablehlo.broadcast_in_dim"(%arg0) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %x_sub = stablehlo.subtract %x_with_bias, %subtract_broadcast : tensor<6x7xf32>

  // GlobalAvgPool: mean over dim=1, keepdim=True
  // mean = sum / dim_size
  // sum over dim=1
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %init = "stablehlo.broadcast_in_dim"(%zero_f32) {broadcast_dimensions = array<i64: 0} : () -> tensor<f32> // scalar zero
  %init_tensor = stablehlo.constant dense<0.0> : tensor<f32> // will use for reduce init

  // Reduce sum over dim=1
  %sum = "stablehlo.reduce"(%x_sub, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<6xf32>

  // Broadcast sum to (6x1)
  %sum_broadcast = "stablehlo.broadcast_in_dim"(%sum) {broadcast_dimensions = array<i64: 0>} : (tensor<6xf32>) -> tensor<6x1xf32>

  // Divide sum by 7 (dim size)
  %seven = stablehlo.constant dense<7.0> : tensor<f32>
  %seven_broadcast = "stablehlo.broadcast_in_dim"(%seven) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<6xf32>
  %seven_broadcast_2d = "stablehlo.broadcast_in_dim"(%seven_broadcast) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<6xf32>) -> tensor<6x1xf32>
  %mean = stablehlo.divide %sum_broadcast, %seven_broadcast_2d : tensor<6x1xf32>

  // LogSumExp over dim=1, keepdim=True
  // Input to logsumexp is mean (6x1), so dim=1 is size 1, logsumexp is just log(exp(x)) = x
  // But we follow the formula anyway:
  // logsumexp(x) = log(sum(exp(x)))
  // Since dim=1 size=1, sum(exp(x)) = exp(x), log(exp(x))=x
  // So logsumexp(mean, dim=1, keepdim=True) = mean itself
  // So we can skip computation and just keep mean as is
  %logsumexp = %mean : tensor<6x1xf32>

  // GELU on logsumexp output
  // GELU(x) = 0.5 * x * (1 + erf(x / sqrt(2)))
  // Compute x / sqrt(2)
  %sqrt2 = stablehlo.constant dense<1.4142135623730951> : tensor<f32>
  %sqrt2_broadcast = "stablehlo.broadcast_in_dim"(%sqrt2) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<f32>) -> tensor<6x1xf32>
  %x_div_sqrt2 = stablehlo.divide %logsumexp, %sqrt2_broadcast : tensor<6x1xf32>

  // Compute erf(x / sqrt(2))
  %erf = "chlo.erf"(%x_div_sqrt2) : (tensor<6x1xf32>) -> tensor<6x1xf32>

  // Compute 1 + erf(...)
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_broadcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<f32>) -> tensor<6x1xf32>
  %one_plus_erf = stablehlo.add %one_broadcast, %erf : tensor<6x1xf32>

  // Multiply x * (1 + erf(...))
  %x_times_one_plus_erf = stablehlo.multiply %logsumexp, %one_plus_erf : tensor<6x1xf32>

  // Multiply by 0.5
  %half = stablehlo.constant dense<0.5> : tensor<f32>
  %half_broadcast = "stablehlo.broadcast_in_dim"(%half) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<f32>) -> tensor<6x1xf32>
  %gelu = stablehlo.multiply %half_broadcast, %x_times_one_plus_erf : tensor<6x1xf32>

  // ResidualAdd: x = gelu + original_x
  // gelu shape: 6x1, original_x shape: 6x7
  // Broadcast gelu to 6x7
  %gelu_broadcast = "stablehlo.broadcast_in_dim"(%gelu) {broadcast_dimensions = array<i64: 0} } : (tensor<6x1xf32>) -> tensor<6x7xf32>
  %residual_add = stablehlo.add %gelu_broadcast, %original_x : tensor<6x7xf32>

  return %residual_add : tensor<6x7xf32>
}

