func.func @main(%subtract: tensor<7xf32>, %weight: tensor<7x7xf32>, %bias: tensor<7xf32>, %input: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // Save original input for residual add
  %original_x = %input : tensor<6x7xf32>

  // GEMM: x = input @ weight^T + bias
  // weight shape: [7,7], we want to do input [6x7] * weight^T [7x7] = [6x7]
  // So contract dimension 1 of input with dimension 1 of weight (weight's second dim)
  // But weight is [7x7], we want to contract input dim 1 with weight dim 0 (first dim)
  // So we transpose weight to [7x7] swapping dims 0 and 1
  %weight_t = "stablehlo.transpose"(%weight) {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>
  %dot = "stablehlo.dot_general"(%input, %weight_t) {dot_dimension_numbers = #stablehlo.dot<lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>} : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>
  %x = stablehlo.add %dot, %bias : tensor<6x7xf32>

  // Subtract: x = x - subtract
  // subtract shape: [7], broadcast to [6x7]
  %subtract_broadcast = "stablehlo.broadcast_in_dim"(%subtract) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %x_sub = stablehlo.subtract %x, %subtract_broadcast : tensor<6x7xf32>

  // GlobalAvgPool: mean over dim=1 (features), keepdim=True
  // mean = sum / size
  // sum over dim=1
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %sum = "stablehlo.reduce"(%x_sub, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<6xf32>

  // divide by 7 (size of dim 1)
  %seven = stablehlo.constant dense<7.0> : tensor<f32>
  %seven_broadcast = "stablehlo.broadcast_in_dim"(%seven) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<6xf32>
  %mean = stablehlo.divide %sum, %seven_broadcast : tensor<6xf32>

  // keepdim=True means shape [6x1], so broadcast dim 1
  %mean_keepdim = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = array<i64: 0>} : (tensor<6xf32>) -> tensor<6x1xf32>

  // LogSumExp over dim=1, keepdim=True
  // Since input shape is [6x1], logsumexp over dim=1 is just log(exp(x)) = x
  // But to follow the formula, we do:
  // logsumexp(x) = log(sum(exp(x)))
  // sum over dim=1 (which is size 1)
  %exp = stablehlo.exponential %mean_keepdim : tensor<6x1xf32>
  %zero_2 = stablehlo.constant dense<0.0> : tensor<f32>
  %sum_exp = "stablehlo.reduce"(%exp, %zero_2) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x1xf32>, tensor<f32>) -> tensor<6xf32>
  // broadcast sum_exp to [6x1]
  %sum_exp_broadcast = "stablehlo.broadcast_in_dim"(%sum_exp) {broadcast_dimensions = array<i64: 0>} : (tensor<6xf32>) -> tensor<6x1xf32>
  %logsumexp = stablehlo.log %sum_exp_broadcast : tensor<6x1xf32>

  // GELU activation on logsumexp result
  // GELU(x) = 0.5 * x * (1 + erf(x / sqrt(2)))
  // Compute x / sqrt(2)
  %sqrt2 = stablehlo.constant dense<1.4142135623730951> : tensor<f32>
  %sqrt2_broadcast = "stablehlo.broadcast_in_dim"(%sqrt2) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<6x1xf32>
  %x_div_sqrt2 = stablehlo.divide %logsumexp, %sqrt2_broadcast : tensor<6x1xf32>
  // erf(x / sqrt(2))
  %erf = chlo.erf %x_div_sqrt2 : tensor<6x1xf32> -> tensor<6x1xf32>
  // 1 + erf(...)
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_broadcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<6x1xf32>
  %one_plus_erf = stablehlo.add %one_broadcast, %erf : tensor<6x1xf32>
  // 0.5 * x
  %half = stablehlo.constant dense<0.5> : tensor<f32>
  %half_broadcast = "stablehlo.broadcast_in_dim"(%half) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<6x1xf32>
  %half_x = stablehlo.multiply %half_broadcast, %logsumexp : tensor<6x1xf32>
  // GELU = 0.5 * x * (1 + erf(...))
  %gelu = stablehlo.multiply %half_x, %one_plus_erf : tensor<6x1xf32>

  // ResidualAdd: add gelu result to original input
  // gelu shape: [6x1], original_x shape: [6x7]
  // broadcast gelu along dim 1 to [6x7]
  %gelu_broadcast = "stablehlo.broadcast_in_dim"(%gelu) {broadcast_dimensions = array<i64: 0>} : (tensor<6x1xf32>) -> tensor<6x7xf32>
  %residual = stablehlo.add %gelu_broadcast, %original_x : tensor<6x7xf32>

  "stablehlo.return"(%residual) : tensor<6x7xf32>
}

