func.func @main(%subtract: tensor<7xf32>, %weight: tensor<7x7xf32>, %bias: tensor<7xf32>, %input: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // %input shape: [6,7]
  // %weight shape: [7,7] (gemm.weight)
  // %subtract shape: [7]
  // %bias shape: [7]

  // GEMM: x = input @ weight^T + bias
  // weight is [7,7], input is [6,7]
  // We want input [6,7] dot weight^T [7,7]^T = [6,7] dot [7,7] = [6,7]
  // So contract dimension is input dim 1 and weight dim 1 (contracting over dim 1)
  // lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [1]
  // lhs_batching_dimensions = [], rhs_batching_dimensions = []
  // Result shape: [6,7]

  // Transpose weight to get weight^T
  %weight_t = "stablehlo.transpose"(%weight) {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>

  %gemm = "stablehlo.dot_general"(%input, %weight_t) {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [],
      rhs_batching_dimensions = [],
      lhs_contracting_dimensions = [1],
      rhs_contracting_dimensions = [1]>
  } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

  // Add bias: broadcast bias [7] to [6,7]
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%bias) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %gemm_bias = stablehlo.add %gemm, %bias_broadcast : tensor<6x7xf32>

  // Subtract: x = gemm_bias - subtract
  // subtract shape: [7], broadcast to [6,7]
  %subtract_broadcast = "stablehlo.broadcast_in_dim"(%subtract) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %subtracted = stablehlo.subtract %gemm_bias, %subtract_broadcast : tensor<6x7xf32>

  // Save original input for residual add later
  %original_input = %input

  // GlobalAvgPool: mean over dim=1 (features dimension)
  // mean = sum / size
  // sum over dim=1
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %sum = "stablehlo.reduce"(%subtracted, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<6xf32>

  // Divide sum by 7.0 (size of dim 1)
  %seven = stablehlo.constant dense<7.0> : tensor<f32>
  %seven_broadcast = "stablehlo.broadcast_in_dim"(%seven) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<6xf32>
  %mean = stablehlo.divide %sum, %seven_broadcast : tensor<6xf32>

  // Keepdim=True means output shape [6,1], so broadcast mean to [6,1]
  %mean_2d = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = array<i64: 0>} : (tensor<6xf32>) -> tensor<6x1xf32>

  // LogSumExp over dim=1 with keepdim=True
  // Input to logsumexp is mean_2d shape [6,1]
  // logsumexp(x) = log(sum(exp(x)))
  // sum over dim=1 (dim=1 size=1)
  // exp
  %exp_mean = stablehlo.exponential %mean_2d : tensor<6x1xf32>

  // sum over dim=1
  %zero_2d = stablehlo.constant dense<0.0> : tensor<f32>
  %sum_exp = "stablehlo.reduce"(%exp_mean, %zero_2d) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x1xf32>, tensor<f32>) -> tensor<6xf32>

  // Broadcast sum_exp to [6,1]
  %sum_exp_2d = "stablehlo.broadcast_in_dim"(%sum_exp) {broadcast_dimensions = array<i64: 0>} : (tensor<6xf32>) -> tensor<6x1xf32>

  // log
  %log_sum_exp = stablehlo.log %sum_exp_2d : tensor<6x1xf32>

  // GELU activation on log_sum_exp
  // GELU(x) = 0.5 * x * (1 + erf(x / sqrt(2)))
  // constants
  %half = stablehlo.constant dense<0.5> : tensor<f32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %sqrt2 = stablehlo.constant dense<1.4142135623730951> : tensor<f32>  // sqrt(2)

  // Broadcast constants to shape [6,1]
  %half_b = "stablehlo.broadcast_in_dim"(%half) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<6x1xf32>
  %one_b = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<6x1xf32>
  %sqrt2_b = "stablehlo.broadcast_in_dim"(%sqrt2) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<6x1xf32>

  // x / sqrt(2)
  %x_div_sqrt2 = stablehlo.divide %log_sum_exp, %sqrt2_b : tensor<6x1xf32>

  // erf(x / sqrt(2))
  %erf_val = chlo.erf %x_div_sqrt2 : tensor<6x1xf32>

  // 1 + erf(...)
  %one_plus_erf = stablehlo.add %one_b, %erf_val : tensor<6x1xf32>

  // x * (1 + erf(...))
  %x_mul = stablehlo.multiply %log_sum_exp, %one_plus_erf : tensor<6x1xf32>

  // 0.5 * x * (1 + erf(...))
  %gelu = stablehlo.multiply %half_b, %x_mul : tensor<6x1xf32>

  // ResidualAdd: add gelu output to original input
  // gelu shape: [6,1], original_input shape: [6,7]
  // broadcast gelu along dim=1 to [6,7]
  %gelu_broadcast = "stablehlo.broadcast_in_dim"(%gelu) {broadcast_dimensions = array<i64: 0>} : (tensor<6x1xf32>) -> tensor<6x7xf32>

  %residual_add = stablehlo.add %gelu_broadcast, %original_input : tensor<6x7xf32>

  "stablehlo.return"(%residual_add) : tensor<6x7xf32>
}

