func.func @main(%arg0: tensor<7xf32>, %arg1: tensor<7x7xf32>, %arg2: tensor<7xf32>, %arg3: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // %arg3: input x, shape [6,7]
  // %arg1: matmul.weight, shape [7,7]
  // %arg2: matmul.bias, shape [7]
  // %arg0: add_value, shape [7]

  // Linear layer: x @ weight^T + bias
  // matmul.weight shape is [7,7], input shape [6,7]
  // We want to do dot_general with contracting dims: input last dim (1), weight last dim (1)
  // But weight needs to be transposed to [7,7] (same shape), but we want to contract input dim 1 with weight dim 0
  // So we do dot_general with lhs_contracting_dimensions=[1], rhs_contracting_dimensions=[0]
  // Result shape: [6,7]

  %0 = "stablehlo.dot_general"(%arg3, %arg1) {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [],
      rhs_batching_dimensions = [],
      lhs_contracting_dimensions = [1],
      rhs_contracting_dimensions = [0]>
  } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

  // Add bias: broadcast bias [7] to [6,7]
  %1 = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %2 = stablehlo.add %0, %1 : tensor<6x7xf32>

  // Add add_value: broadcast add_value [7] to [6,7]
