  %c_half = stablehlo.constant dense<0.5> : tensor<f32>
  %c_half_broadcast = "stablehlo.broadcast_in_dim"(%c_half) {broadcast_dimensions = array<i64: []>} : (tensor<f32>) -> tensor<>  // scalar

  %11 = stablehlo.multiply %7, %c_half_broadcast : tensor<6x7xf32>
  %12 = stablehlo.multiply %11, %10 : tensor<6x7xf32>

  // Hardtanh with min_val=-1, max_val=1
  %c_min = stablehlo.constant dense<-1.0> : tensor<f32>
  %c_min_broadcast = "stablehlo.broadcast_in_dim"(%c_min) {broadcast_dimensions = array<i64: []>} : (tensor<f32>) -> tensor<>  // scalar
  %c_max = stablehlo.constant dense<1.0> : tensor<f32>
  %c_max_broadcast = "stablehlo.broadcast_in_dim"(%c_max) {broadcast_dimensions = array<i64: []>} : (tensor<f32>) -> tensor<>  // scalar

  %13 = stablehlo.maximum %12, %c_min_broadcast : tensor<6x7xf32>
  %14 = stablehlo.minimum %13, %c_max_broadcast : tensor<6x7xf32>

  return %14 : tensor<6x7xf32>
}

func.func @main(%arg0: tensor<7xf32>, %arg1: tensor<7x7xf32>, %arg2: tensor<7xf32>, %arg3: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // %arg0 = add_value (tensor<7xf32>)
  // %arg1 = matmul.weight (tensor<7x7xf32>)
  // %arg2 = matmul.bias (tensor<7xf32>)
  // %arg3 = input x (tensor<6x7xf32>)

  // Perform matmul: x @ weight^T
  // weight shape: [7,7], input shape: [6,7]
  // We want to do dot_general with contracting dims: input dim 1 and weight dim 1 (weight's second dim)
  // But weight is [7x7], we want to multiply input [6x7] with weight^T [7x7]^T = [7x7] transposed dims [1,0]
  // So we transpose weight to get [7x7] -> [7x7] (actually same shape but permuted dims)
  // Actually weight is square, but we must transpose to get correct contraction dims.
  // Contract input dim 1 with weight dim 1 after transpose (which is original dim 0)
  // So transpose weight with permutation [1,0]
