  %sigmoid = stablehlo.logistic %x_add : tensor<6x7xf32>
  %swish = stablehlo.multiply %x_add, %sigmoid : tensor<6x7xf32>

  // Tanh
  %tanh = stablehlo.tanh %swish : tensor<6x7xf32>

