  %const_one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_broadcast = "stablehlo.broadcast_in_dim"(%const_one) {broadcast_dimensions = array<i64: []>} : (tensor<f32>) -> tensor<6x7xf32>
  %one_plus_erf = stablehlo.add %one_broadcast, %erf : tensor<6x7xf32>

