  %const_half = stablehlo.constant dense<0.5> : tensor<f32>
  %half_broadcast = "stablehlo.broadcast_in_dim"(%const_half) {broadcast_dimensions = array<i64: []>} : (tensor<f32>) -> tensor<6x7xf32>
