func.func @main(%arg0: tensor<6x6x3x3xf32>, %arg1: tensor<8x6x7x8xf32>) -> tensor<8x6x9x10xf32> {
  // %arg0: conv_transpose2d.weight with shape [in_channels=6, out_channels=6, kernel_h=3, kernel_w=3]
  // %arg1: input tensor with shape [batch=8, in_channels=6, height=7, width=8]

  // Step 1: Reverse the kernel spatial dimensions (height and width)
  // Reverse dims 2 and 3 (kernel height and width)
  %reversed_kernel = "stablehlo.reverse"(%arg0) {dimensions = array<i64: 2, 3>} : (tensor<6x6x3x3xf32>) -> tensor<6x6x3x3xf32>

  // Step 2: Perform convolution with the reversed kernel and input
  // Convolution dimension numbers:
  // Input (lhs): [b, f, h, w] = [batch, in_channels, height, width]
  // Kernel (rhs): [o, i, kh, kw] = [out_channels, in_channels, kernel_h, kernel_w]
  // Output: [b, f, h, w] = [batch, out_channels, height_out, width_out]
  //
  // For ConvTranspose2d, the weight shape is (in_channels, out_channels, kh, kw),
  // but stablehlo.convolution expects kernel shape (out_channels, in_channels, kh, kw).
  // So we must swap the first two dims of the kernel.
  //
  // We do this by a transpose of the first two dims of reversed_kernel:
  %kernel_transposed = "stablehlo.transpose"(%reversed_kernel) {permutation = array<i64: 1, 0, 2, 3>} : (tensor<6x6x3x3xf32>) -> tensor<6x6x3x3xf32>

  // Now %kernel_transposed shape is [out_channels=6, in_channels=6, 3, 3]

  // Set convolution attributes for transposed convolution:
  // stride = [1,1]
  // padding = [[0,0],[0,0]] (no padding)
  // lhs_dilation = [1,1] (no dilation)
  // rhs_dilation = [1,1] (no dilation)
  // feature_group_count = 1
  // batch_group_count = 1
  //
  // dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>
  //
  // This means:
  // lhs dims: b=batch, f=feature=in_channels, 0=height, 1=width
  // rhs dims: o=out_channels, i=in_channels, 0=kernel_h, 1=kernel_w
  // output dims: b=batch, f=feature=out_channels, 0=height_out, 1=width_out

  %conv = "stablehlo.convolution"(%arg1, %kernel_transposed) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 1, 1>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<8x6x7x8xf32>, tensor<6x6x3x3xf32>) -> tensor<8x6x5x6xf32>

  // The output shape from above convolution is [8, 6, 5, 6].
  // But the expected output shape is [8, 6, 9, 10].
  //
  // For ConvTranspose2d with stride=1, padding=0, output_padding=0,
  // output spatial size = (input_size - 1) * stride - 2*padding + kernel_size + output_padding
  // = (7-1)*1 - 0 + 3 + 0 = 9 height
  // = (8-1)*1 - 0 + 3 + 0 = 10 width
  //
  // The convolution above produced smaller spatial dims because it is a normal convolution.
  // To get the transposed convolution output, we must do a dilation on the input (lhs_dilation)
  // and adjust padding accordingly.
  //
  // So redo convolution with lhs_dilation = stride = [1,1] (already 1),
  // but we must set lhs_dilation = stride = 1 (already 1),
  // and padding = [kernel_size - 1 - padding, kernel_size - 1 - padding] = [2, 2]
  //
  // So padding = [[2,2],[2,2]] to get output shape 9x10.

  %conv_correct = "stablehlo.convolution"(%arg1, %kernel_transposed) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[2, 2], [2, 2]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 1, 1>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<8x6x7x8xf32>, tensor<6x6x3x3xf32>) -> tensor<8x6x9x10xf32>

  return %conv_correct : tensor<8x6x9x10xf32>
}

