  // Reduce sum of squared differences over dims 2 and 3 (H,W)
  %var_sum = "stablehlo.reduce"(%diff_sq, %c0) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum2 = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum2) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2, 3>} : (tensor<6x7x8x8xf32>, tensor<f32>) -> tensor<6x7xf32>

  // Divide by 64 to get variance
  %var = stablehlo.divide %var_sum, %c64_6_7 : tensor<6x7xf32>

  // Step 4: Add epsilon 1e-5 to variance
  %c_eps = stablehlo.constant dense<0.00001> : tensor<f32>
  // Broadcast epsilon scalar to [6,7]
  %c_eps_1 = stablehlo.reshape %c_eps : (tensor<f32>) -> tensor<1xf32>
  %c_eps_6_7 = "stablehlo.broadcast_in_dim"(%c_eps_1) {broadcast_dimensions = array<i64:>} : (tensor<1xf32>) -> tensor<6x7xf32>
  %var_eps = stablehlo.add %var, %c_eps_6_7 : tensor<6x7xf32>

  // Step 5: Compute rsqrt of variance + eps
  %std_inv = stablehlo.rsqrt %var_eps : tensor<6x7xf32>

  // Step 6: Broadcast std_inv to [6,7,8,8]
  %std_inv_bcast = "stablehlo.broadcast_in_dim"(%std_inv) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<6x7xf32>) -> tensor<6x7x8x8xf32>

  // Step 7: Multiply (x - mean) * rsqrt(var + eps)
  %out = stablehlo.multiply %diff, %std_inv_bcast : tensor<6x7x8x8xf32>

  // Return normalized output
  return %out : tensor<6x7x8x8xf32>
}

func.func @main(%arg0: tensor<6x7x8x8xf32>) -> tensor<6x7x8x8xf32> {
  // InstanceNorm2d with affine=False, track_running_stats=False, eps=1e-5
  // Input shape: [N=6, C=7, H=8, W=8]
  // Normalize each instance per channel over spatial dims (H,W)
  // Compute mean over dims [2,3]
  %cst0 = stablehlo.constant dense<0.0> : tensor<f32>
  %cst_eps = stablehlo.constant dense<0.00001> : tensor<f32>

  // Compute mean over dims [2,3]
  %mean = "stablehlo.reduce"(%arg0, %cst0) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2, 3>} : (tensor<6x7x8x8xf32>, tensor<f32>) -> tensor<6x7xf32>

  // Compute divisor = H*W = 64 as f32 constant
  %cst64 = stablehlo.constant dense<64.0> : tensor<f32>

  // mean = sum / 64
  %mean_div = stablehlo.divide %mean, %cst64 : tensor<6x7xf32>

  // Broadcast mean to input shape [6,7,8,8]
  %mean_bcast = "stablehlo.broadcast_in_dim"(%mean_div) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<6x7xf32>) -> tensor<6x7x1x1xf32>
  %mean_bcast_reshape = "stablehlo.broadcast_in_dim"(%mean_bcast) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<6x7x1x1xf32>) -> tensor<6x7x8x8xf32>

  // Compute (x - mean)
  %x_centered = stablehlo.subtract %arg0, %mean_bcast_reshape : tensor<6x7x8x8xf32>

  // Compute squared difference (x - mean)^2
  %sq_diff = stablehlo.multiply %x_centered, %x_centered : tensor<6x7x8x8xf32>

  // Compute variance sum over dims [2,3]
  %var_sum = "stablehlo.reduce"(%sq_diff, %cst0) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2, 3>} : (tensor<6x7x8x8xf32>, tensor<f32>) -> tensor<6x7xf32>

  // variance = var_sum / 64
  %var = stablehlo.divide %var_sum, %cst64 : tensor<6x7xf32>

  // variance + eps
  %var_eps = stablehlo.add %var, %cst_eps : tensor<6x7xf32>

  // sqrt(variance + eps)
  %stddev = stablehlo.sqrt %var_eps : tensor<6x7xf32>

  // Broadcast stddev to input shape [6,7,8,8]
  %stddev_bcast = "stablehlo.broadcast_in_dim"(%stddev) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<6x7xf32>) -> tensor<6x7x1x1xf32>
  %stddev_bcast_reshape = "stablehlo.broadcast_in_dim"(%stddev_bcast) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<6x7x1x1xf32>) -> tensor<6x7x8x8xf32>

  // Normalize: (x - mean) / stddev
  %normalized = stablehlo.divide %x_centered, %stddev_bcast_reshape : tensor<6x7x8x8xf32>

  // Return normalized output
  "stablehlo.return"(%normalized) : tensor<6x7x8x8xf32>
}

