func.func @main(%arg0: tensor<7x7xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x7xf32>) -> tensor<6x1xf32> {
  // Linear: x @ W^T + b
  // %arg0 = weight (7x7), %arg1 = bias (7), %arg2 = input (6x7)
  // We want: output = %arg2 (6x7) dot %arg0^T (7x7) + %arg1 (7)
  // dot_general with contracting dims: input dim 1 and weight dim 1 (weight rows)
  // But weight is 7x7, we want to contract input dim 1 with weight dim 1 (the second dim)
  // Actually, PyTorch Linear does input @ weight.T + bias
  // So weight.T shape is 7x7 (same shape), but transpose dims 0 and 1
  %weight_t = "stablehlo.transpose"(%arg0) {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>
  %dot = "stablehlo.dot_general"(%arg2, %weight_t) {dot_dimension_numbers = #stablehlo.dot<lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>} : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>
  // Add bias: broadcast bias (7) to (6x7)
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %linear_out = stablehlo.add %dot, %bias_broadcast : tensor<6x7xf32>

  // LogSumExp over dim=1, keepdim=True
  // Steps:
  // 1) max over dim=1 for numerical stability
  %init_max = stablehlo.constant dense<-3.4028235e+38> : tensor<f32>  // -inf approx
  %max = "stablehlo.reduce"(%linear_out, %init_max) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.maximum %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<6xf32>
  // 2) broadcast max to shape (6x7)
  %max_broadcast = "stablehlo.broadcast_in_dim"(%max) {broadcast_dimensions = array<i64: 0>} : (tensor<6xf32>) -> tensor<6x7xf32>
  // 3) subtract max from linear_out
  %shifted = stablehlo.subtract %linear_out, %max_broadcast : tensor<6x7xf32>
  // 4) exp(shifted)
  %exp_shifted = stablehlo.exponential %shifted : tensor<6x7xf32>
  // 5) sum exp_shifted over dim=1
  %init_zero = stablehlo.constant dense<0.0> : tensor<f32>
  %sum_exp = "stablehlo.reduce"(%exp_shifted, %init_zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<6xf32>
  // 6) log(sum_exp)
  %log_sum_exp = stablehlo.log %sum_exp : tensor<6xf32>
  // 7) add max back
  %lse = stablehlo.add %log_sum_exp, %max : tensor<6xf32>
  // 8) keepdim=True means shape (6x1), broadcast lse to (6x1)
  %lse_reshaped = "stablehlo.broadcast_in_dim"(%lse) {broadcast_dimensions = array<i64: 0>} : (tensor<6xf32>) -> tensor<6x1xf32>

  // LeakyReLU with negative_slope=0.01 applied twice
  // LeakyReLU(x) = max(0,x) + negative_slope * min(0,x)
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  // First LeakyReLU
  %max0 = stablehlo.maximum %lse_reshaped, %zero : tensor<6x1xf32>
  %min0 = stablehlo.minimum %lse_reshaped, %zero : tensor<6x1xf32>
  %neg_slope = stablehlo.constant dense<0.01> : tensor<f32>
  %neg_slope_broadcast = "stablehlo.broadcast_in_dim"(%neg_slope) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x1xf32>
  %scaled_min0 = stablehlo.multiply %min0, %neg_slope_broadcast : tensor<6x1xf32>
  %leaky1 = stablehlo.add %max0, %scaled_min0 : tensor<6x1xf32>
  // Second LeakyReLU
  %max1 = stablehlo.maximum %leaky1, %zero : tensor<6x1xf32>
  %min1 = stablehlo.minimum %leaky1, %zero : tensor<6x1xf32>
  %scaled_min1 = stablehlo.multiply %min1, %neg_slope_broadcast : tensor<6x1xf32>
  %leaky2 = stablehlo.add %max1, %scaled_min1 : tensor<6x1xf32>

  // GELU applied twice
  // GELU(x) = 0.5 * x * (1 + erf(x / sqrt(2)))
  // Precompute constant sqrt(2)
  %sqrt2 = stablehlo.constant dense<1.4142135623730951> : tensor<f32>
  %sqrt2_broadcast = "stablehlo.broadcast_in_dim"(%sqrt2) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x1xf32>
  // First GELU
  %x_div_sqrt2 = stablehlo.divide %leaky2, %sqrt2_broadcast : tensor<6x1xf32>
  %erf_x = chlo.erf %x_div_sqrt2 : tensor<6x1xf32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_broadcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x1xf32>
  %one_plus_erf = stablehlo.add %one_broadcast, %erf_x : tensor<6x1xf32>
  %half = stablehlo.constant dense<0.5> : tensor<f32>
  %half_broadcast = "stablehlo.broadcast_in_dim"(%half) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x1xf32>
  %mul1 = stablehlo.multiply %leaky2, %half_broadcast : tensor<6x1xf32>
  %gelu1 = stablehlo.multiply %mul1, %one_plus_erf : tensor<6x1xf32>
  // Second GELU
  %x_div_sqrt2_2 = stablehlo.divide %gelu1, %sqrt2_broadcast : tensor<6x1xf32>
  %erf_x_2 = chlo.erf %x_div_sqrt2_2 : tensor<6x1xf32>
  %one_plus_erf_2 = stablehlo.add %one_broadcast, %erf_x_2 : tensor<6x1xf32>
  %mul1_2 = stablehlo.multiply %gelu1, %half_broadcast : tensor<6x1xf32>
  %gelu2 = stablehlo.multiply %mul1_2, %one_plus_erf_2 : tensor<6x1xf32>

  return %gelu2 : tensor<6x1xf32>
}

