func.func @main(%arg0: tensor<6x7x8x8xf32>) -> tensor<6x7x8x8xf32> {
  // InstanceNorm2d forward in training mode:
  // input shape: [N=6, C=7, H=8, W=8]
  // For each instance (n,c), compute mean and variance over spatial dims (H,W).
  // output = (x - mean) / sqrt(var + eps)
  // eps = 1e-5 (typical default)

  %c_eps = stablehlo.constant dense<1.00000005e-5> : tensor<f32>

  // Compute mean over dims 2 and 3 (H,W)
  // Step 1: sum over dim 3 (W)
  %c0 = stablehlo.constant dense<0.0> : tensor<f32>
  %sum_w = "stablehlo.reduce"(%arg0, %c0) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %add = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%add) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 3>} : (tensor<6x7x8x8xf32>, tensor<f32>) -> tensor<6x7x8xf32>

  // Step 2: sum over dim 2 (H)
  %sum_hw = "stablehlo.reduce"(%sum_w, %c0) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %add2 = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%add2) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2>} : (tensor<6x7x8xf32>, tensor<f32>) -> tensor<6x7xf32>

  // Compute mean = sum_hw / (H*W) = sum_hw / 64
  %c64 = stablehlo.constant dense<64.0> : tensor<f32>
  %mean = stablehlo.divide %sum_hw, %c64 : tensor<6x7xf32>

  // Broadcast mean back to input shape [6x7x8x8]
  %mean_bcast = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<6x7xf32>) -> tensor<6x7x1x1xf32>
  %mean_bcast_reshaped = "stablehlo.broadcast_in_dim"(%mean_bcast) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<6x7x1x1xf32>) -> tensor<6x7x8x8xf32>

  // Compute (x - mean)
  %x_minus_mean = stablehlo.subtract %arg0, %mean_bcast_reshaped : tensor<6x7x8x8xf32>

  // Compute variance:
  // Step 1: (x - mean)^2
  %sq_diff = stablehlo.multiply %x_minus_mean, %x_minus_mean : tensor<6x7x8x8xf32>

  // Sum over dim 3 (W)
  %sum_sq_w = "stablehlo.reduce"(%sq_diff, %c0) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %add3 = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%add3) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 3>} : (tensor<6x7x8x8xf32>, tensor<f32>) -> tensor<6x7x8xf32>

  // Sum over dim 2 (H)
  %sum_sq_hw = "stablehlo.reduce"(%sum_sq_w, %c0) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %add4 = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%add4) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2>} : (tensor<6x7x8xf32>, tensor<f32>) -> tensor<6x7xf32>

  // variance = sum_sq_hw / 64
  %var = stablehlo.divide %sum_sq_hw, %c64 : tensor<6x7xf32>

  // Add eps to variance
  %var_eps = stablehlo.add %var, %c_eps : tensor<6x7xf32>

  // sqrt(var + eps)
  %stddev = stablehlo.sqrt %var_eps : tensor<6x7xf32>

  // Broadcast stddev back to input shape [6x7x8x8]
  %stddev_bcast = "stablehlo.broadcast_in_dim"(%stddev) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<6x7xf32>) -> tensor<6x7x1x1xf32>
  %stddev_bcast_reshaped = "stablehlo.broadcast_in_dim"(%stddev_bcast) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<6x7x1x1xf32>) -> tensor<6x7x8x8xf32>

  // Normalize: (x - mean) / stddev
  %out = stablehlo.divide %x_minus_mean, %stddev_bcast_reshaped : tensor<6x7x8x8xf32>

  return %out : tensor<6x7x8x8xf32>
}

