  // input shape: [N=6, C=7, H=8, W=8]
  // For each instance (n,c), compute mean and variance over spatial dims (H,W)
  // output = (input - mean) / sqrt(variance + eps)
  // eps = 1e-5 (typical default)

  %c_eps = stablehlo.constant dense<0.00001> : tensor<f32>

