  // init zero for sum
  %c_zero = stablehlo.constant dense<0.0> : tensor<f32>
  %init_sum = stablehlo.broadcast_in_dim %c_zero {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<1xf32>
