  // The output shape after reducing dims 2,3 is [6,7]
  // So init tensor shape is [6,7] filled with 0.0
  %c_zero_6x7 = stablehlo.constant dense<0.0> : tensor<6x7xf32>

  // Reduce sum over dims 2 and 3
  %sum_hw = "stablehlo.reduce"(%arg0, %c_zero_6x7) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %add = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%add) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2, 3>} : (tensor<6x7x8x8xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

