  // So broadcast_in_dim with broadcast_dimensions = [] is scalar to scalar, to get [6,7] we broadcast scalar to [6,7]
  // So broadcast_dimensions = [] and input shape scalar, output shape [6,7]
  %c_64_6x7 = "stablehlo.broadcast_in_dim"(%c_64) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7xf32>

  %mean = stablehlo.divide %sum_hw, %c_64_6x7 : tensor<6x7xf32>

  // Compute variance:
  // var = mean((x - mean)^2) over dims 2,3
  // First compute (x - mean) with broadcasting mean to [6,7,8,8]
  // Broadcast mean [6,7] to [6,7,8,8]
  %mean_bcast = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<6x7xf32>) -> tensor<6x7x8x8xf32>

  %diff = stablehlo.subtract %arg0, %mean_bcast : tensor<6x7x8x8xf32>

  %diff_sq = stablehlo.multiply %diff, %diff : tensor<6x7x8x8xf32>

  // Reduce sum of diff_sq over dims 2,3
  %c_zero_6x7_2 = stablehlo.constant dense<0.0> : tensor<6x7xf32>
  %sum_sq = "stablehlo.reduce"(%diff_sq, %c_zero_6x7_2) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %add = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%add) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2, 3>} : (tensor<6x7x8x8xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

  // variance = sum_sq / 64
  %var = stablehlo.divide %sum_sq, %c_64_6x7 : tensor<6x7xf32>

  // Add eps to variance
  %c_eps_6x7 = "stablehlo.broadcast_in_dim"(%c_eps) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7xf32>
  %var_eps = stablehlo.add %var, %c_eps_6x7 : tensor<6x7xf32>

  // sqrt(var + eps)
  %stddev = stablehlo.sqrt %var_eps : tensor<6x7xf32>

  // Broadcast stddev to [6,7,8,8]
  %stddev_bcast = "stablehlo.broadcast_in_dim"(%stddev) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<6x7xf32>) -> tensor<6x7x8x8xf32>

  // Normalize: (x - mean) / stddev
  %out = stablehlo.divide %diff, %stddev_bcast : tensor<6x7x8x8xf32>

  return %out : tensor<6x7x8x8xf32>
}

