func.func @main(%conv_transpose_weight: tensor<7x7x3x3xf32>, %conv_transpose_bias: tensor<7xf32>, %input: tensor<6x7x6x6xf32>) -> tensor<6x7x12x12xf32> {
  // Transposed convolution parameters:
  // input: [6,7,6,6], weight: [7,7,3,3], bias: [7]
  // stride=2, padding=1, output_padding=1
  // dimension_numbers for ConvTranspose (NCHW):
  // lhs (input): [b, f, h, w] = [6,7,6,6]
  // rhs (kernel): [i, o, h, w] = [7,7,3,3] but conv_transpose.weight is [7,7,3,3] (out_channels, in_channels, kH, kW)
  // For ConvTranspose, we use convolution with lhs_dilation=stride, rhs reversed spatial dims, and padding adjusted.
  // stablehlo.convolution expects kernel layout [o, i, h, w], so we must transpose conv_transpose_weight from [out_c, in_c, kH, kW] to [in_c, out_c, kH, kW]
  // because conv_transpose_weight is [7,7,3,3], and input channels = 7, output channels = 7
  // So we transpose conv_transpose_weight from [O,I,H,W] to [I,O,H,W] for convolution rhs.

  // Transpose conv_transpose_weight from [7,7,3,3] (O,I,H,W) to [7,7,3,3] (I,O,H,W)
  %weight_transposed = stablehlo.transpose %conv_transpose_weight {permutation = array<i64: 1, 0, 2, 3>} : tensor<7x7x3x3xf32> -> tensor<7x7x3x3xf32>

  // Reverse spatial dims of kernel for transposed convolution (flip kernel spatially)
  %weight_reversed = "stablehlo.reverse"(%weight_transposed) {dimensions = array<i64: 2, 3>} : tensor<7x7x3x3xf32> -> tensor<7x7x3x3xf32>

  // Convolution with lhs_dilation=stride (2,2), rhs_dilation=1, padding adjusted for output_padding=1
  // padding formula for transposed conv:
  // padding = kernel_size - 1 - padding
  // kernel_size=3, padding=1 => padding = 3-1-1=1
  // So padding low and high = 1 for each spatial dim
  // output_padding=1 means output size is increased by 1, so we add 1 to padding high for each spatial dim
  // So padding low = 1, padding high = 2 for each spatial dim

  %conv = "stablehlo.convolution"(%input, %weight_reversed) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[1, 2], [1, 2]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 2, 2>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x7x6x6xf32>, tensor<7x7x3x3xf32>) -> tensor<6x7x12x12xf32>

  // Add bias: conv output shape [6,7,12,12], bias shape [7]
  // Broadcast bias to [6,7,12,12]
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%conv_transpose_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7x12x12xf32>

  %conv_bias = stablehlo.add %conv, %bias_broadcast : tensor<6x7x12x12xf32>

  // Mish activation: x * tanh(softplus(x)) = x * tanh(log(1 + exp(x)))
  // Compute softplus = log(1 + exp(x))
  %exp_conv_bias = stablehlo.exponential %conv_bias : tensor<6x7x12x12xf32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  // Broadcast 1.0 to tensor<6x7x12x12xf32>
  %one_broadcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64:>} : (tensor<f32>) -> tensor<6x7x12x12xf32>
  %exp_plus_one = stablehlo.add %exp_conv_bias, %one_broadcast : tensor<6x7x12x12xf32>
  %softplus = stablehlo.log %exp_plus_one : tensor<6x7x12x12xf32>
  %tanh_softplus = stablehlo.tanh %softplus : tensor<6x7x12x12xf32>
  %mish = stablehlo.multiply %conv_bias, %tanh_softplus : tensor<6x7x12x12xf32>

  // Add add_value = 0.5
  %add_value = stablehlo.constant dense<0.5> : tensor<f32>
  %add_value_broadcast = "stablehlo.broadcast_in_dim"(%add_value) {broadcast_dimensions = array<i64:>} : (tensor<f32>) -> tensor<6x7x12x12xf32>
  %mish_plus = stablehlo.add %mish, %add_value_broadcast : tensor<6x7x12x12xf32>

  // Hardtanh activation with min_val=-1, max_val=1
  %min_val = stablehlo.constant dense<-1.0> : tensor<f32>
  %max_val = stablehlo.constant dense<1.0> : tensor<f32>
  %min_val_broadcast = "stablehlo.broadcast_in_dim"(%min_val) {broadcast_dimensions = array<i64:>} : (tensor<f32>) -> tensor<6x7x12x12xf32>
  %max_val_broadcast = "stablehlo.broadcast_in_dim"(%max_val) {broadcast_dimensions = array<i64:>} : (tensor<f32>) -> tensor<6x7x12x12xf32>
  %clamped_min = stablehlo.maximum %mish_plus, %min_val_broadcast : tensor<6x7x12x12xf32>
  %hardtanh = stablehlo.minimum %clamped_min, %max_val_broadcast : tensor<6x7x12x12xf32>

  // Multiply by scale = 2
  %scale = stablehlo.constant dense<2.0> : tensor<f32>
  %scale_broadcast = "stablehlo.broadcast_in_dim"(%scale) {broadcast_dimensions = array<i64:>} : (tensor<f32>) -> tensor<6x7x12x12xf32>
  %output = stablehlo.multiply %hardtanh, %scale_broadcast : tensor<6x7x12x12xf32>

  return %output : tensor<6x7x12x12xf32>
}

func.func @main(%conv_transpose_weight: tensor<7x7x3x3xf32>, %conv_transpose_bias: tensor<7xf32>, %input: tensor<6x7x6x6xf32>) -> tensor<6x7x12x12xf32> {
  // Transposed convolution parameters:
  // input: [6,7,6,6], weight: [7,7,3,3], bias: [7]
  // stride=2, padding=1, output_padding=1
  // dimension_numbers for ConvTranspose (NCHW):
  // conv_transpose is implemented as convolution with lhs_dilation and rhs_dilation
  // StableHLO convolution dimension_numbers: input [b,f,h,w], kernel [o,i,h,w], output [b,f,h,w]
  // For ConvTranspose2d, lhs_dilation = stride, rhs_dilation = 1, padding adjusted accordingly
  // output_padding is handled by adjusting padding high side by output_padding

  // lhs = input
  // rhs = weight
  // lhs_dilation = stride = [2,2]
  // rhs_dilation = [1,1]
  // padding = padding - output_padding on high side: 
  // Given padding=1, output_padding=1, so padding low = 1, padding high = 1 + output_padding = 2
  // But for transposed conv, padding is usually set as:
  // padding = [[padding, padding + output_padding], [padding, padding + output_padding]]
  // So padding = [[1,2],[1,2]]

  // Define dimension_numbers attribute for convolution:
  // input: [b,f,h,w], kernel: [o,i,h,w], output: [b,f,h,w]
  // dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>
  // feature_group_count = 1, batch_group_count = 1

  %lhs_dilation = stablehlo.constant dense<2, 2> : tensor<2xi64>
  %rhs_dilation = stablehlo.constant dense<1, 1> : tensor<2xi64>
  %window_strides = stablehlo.constant dense<1, 1> : tensor<2xi64>  // stride for convolution window is 1 for transposed conv
  %padding = stablehlo.constant dense<[[1, 2], [1, 2]]> : tensor<2x2xi64>

  %conv = "stablehlo.convolution"(%input, %conv_transpose_weight) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[1, 2], [1, 2]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 2, 2>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x7x6x6xf32>, tensor<7x7x3x3xf32>) -> tensor<6x7x12x12xf32>

  // Add bias: broadcast bias from [7] to [6,7,12,12]
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%conv_transpose_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<1x7x1x1xf32>
  %bias_broadcast_reshape = stablehlo.reshape %bias_broadcast : (tensor<1x7x1x1xf32>) -> tensor<6x7x12x12xf32> // broadcast_in_dim already broadcasts to output shape, but stablehlo.broadcast_in_dim requires explicit shape, so we do reshape to output shape
  // Actually, broadcast_in_dim requires output shape, so better to broadcast directly to output shape:
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%conv_transpose_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7x12x12xf32>

  %conv_bias = stablehlo.add %conv, %bias_broadcast : tensor<6x7x12x12xf32>

  // Mish activation: x * tanh(softplus(x))
  // softplus(x) = log(1 + exp(x))
  %exp_x = stablehlo.exponential %conv_bias : tensor<6x7x12x12xf32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_broadcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7x12x12xf32>
  %exp_x_plus_one = stablehlo.add %exp_x, %one_broadcast : tensor<6x7x12x12xf32>
  %softplus = stablehlo.log %exp_x_plus_one : tensor<6x7x12x12xf32>
  %tanh_softplus = stablehlo.tanh %softplus : tensor<6x7x12x12xf32>
  %mish = stablehlo.multiply %conv_bias, %tanh_softplus : tensor<6x7x12x12xf32>

  // Add add_value = 0.5
  %add_value = stablehlo.constant dense<0.5> : tensor<f32>
  %add_value_broadcast = "stablehlo.broadcast_in_dim"(%add_value) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7x12x12xf32>
  %mish_plus_add = stablehlo.add %mish, %add_value_broadcast : tensor<6x7x12x12xf32>

  // Hardtanh activation with min_val=-1, max_val=1
  %min_val = stablehlo.constant dense<-1.0> : tensor<f32>
  %max_val = stablehlo.constant dense<1.0> : tensor<f32>
  %min_val_broadcast = "stablehlo.broadcast_in_dim"(%min_val) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7x12x12xf32>
  %max_val_broadcast = "stablehlo.broadcast_in_dim"(%max_val) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7x12x12xf32>
  %clamped_min = stablehlo.maximum %mish_plus_add, %min_val_broadcast : tensor<6x7x12x12xf32>
  %hardtanh = stablehlo.minimum %clamped_min, %max_val_broadcast : tensor<6x7x12x12xf32>

  // Scale output by scale=2
  %scale = stablehlo.constant dense<2.0> : tensor<f32>
  %scale_broadcast = "stablehlo.broadcast_in_dim"(%scale) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7x12x12xf32>
  %output = stablehlo.multiply %hardtanh, %scale_broadcast : tensor<6x7x12x12xf32>

  return %output : tensor<6x7x12x12xf32>
}

func.func @main(%arg0: tensor<7x7x3x3xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x7x6x6xf32>) -> tensor<6x7x12x12xf32> {
  // Transposed convolution parameters:
  // input: %arg2: tensor<6x7x6x6xf32> (NCHW)
  // weight: %arg0: tensor<7x7x3x3xf32> (out_channels, in_channels, kernel_h, kernel_w)
  // bias: %arg1: tensor<7xf32>
  // stride=2, padding=1, output_padding=1
  // dimension_numbers for ConvTranspose:
  // input dims: [b, f, h, w] = [0,1,2,3]
  // kernel dims: [i, o, h, w] = [1,0,2,3] (transpose of conv weight dims)
  // output dims: [b, f, h, w] = [0,1,2,3]

  // StableHLO convolution expects kernel dims: [o, i, h, w]
  // For ConvTranspose, we swap input and output channels in kernel dims:
  // So we reshape weight from [7,7,3,3] (o,i,h,w) to [7,7,3,3] but swap o and i dims for conv_transpose:
  // Actually, stablehlo.convolution does not have a direct conv_transpose op.
  // We implement conv_transpose as a convolution with lhs_dilation and appropriate padding.
  // According to PyTorch docs, ConvTranspose2d is implemented as a convolution with lhs_dilation=stride,
  // padding = kernel_size - 1 - padding, and output_padding added after.

  // Compute lhs_dilation = stride = [2,2]
  // Compute padding = kernel_size - 1 - padding = 3 - 1 - 1 = 1
  // So padding = [[1,1],[1,1]]
  // output_padding = 1 (added after convolution by slicing or padding)

  // stablehlo.convolution dimension_numbers: input [b,f,h,w], kernel [o,i,h,w], output [b,f,h,w]
  // For conv_transpose, kernel input/output channels are swapped compared to conv:
  // So we swap kernel dims from [o,i,h,w] to [i,o,h,w] by reshaping and transposing.

  // Step 1: transpose kernel from [o,i,h,w] to [i,o,h,w]
  %weight_transposed = "stablehlo.transpose"(%arg0) {permutation = array<i64: 1, 0, 2, 3>} : (tensor<7x7x3x3xf32>) -> tensor<7x7x3x3xf32>

  // Step 2: convolution with lhs_dilation = stride = [2,2], rhs_dilation = [1,1], padding = [[1,1],[1,1]]
  %conv = "stablehlo.convolution"(%arg2, %weight_transposed) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[1, 1], [1, 1]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 2, 2>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 2, 3]->[b, f, 0, 1]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x7x6x6xf32>, tensor<7x7x3x3xf32>) -> tensor<6x7x12x12xf32>

  // Step 3: add bias (broadcast bias from [7] to [6x7x12x12])
  // Broadcast bias to shape [1,7,1,1]
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<1x7x1x1xf32>
  // Broadcast to [6x7x12x12]
  %bias_broadcast_full = "stablehlo.broadcast_in_dim"(%bias_broadcast) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<1x7x1x1xf32>) -> tensor<6x7x12x12xf32>
  %conv_bias = stablehlo.add %conv, %bias_broadcast_full : tensor<6x7x12x12xf32>

  // Step 4: Mish activation: x * tanh(softplus(x))
  // softplus(x) = log(1 + exp(x))
  %exp_x = stablehlo.exponential %conv_bias : tensor<6x7x12x12xf32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  // Broadcast one to shape of %conv_bias
  %one_broadcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64:>} : (tensor<f32>) -> tensor<6x7x12x12xf32>
  %exp_x_plus_one = stablehlo.add %exp_x, %one_broadcast : tensor<6x7x12x12xf32>
  %softplus = stablehlo.log %exp_x_plus_one : tensor<6x7x12x12xf32>
  %tanh_softplus = stablehlo.tanh %softplus : tensor<6x7x12x12xf32>
  %mish = stablehlo.multiply %conv_bias, %tanh_softplus : tensor<6x7x12x12xf32>

  // Step 5: add add_value = 0.5 (broadcast scalar)
  %add_value_const = stablehlo.constant dense<0.5> : tensor<f32>
  %add_value_broadcast = "stablehlo.broadcast_in_dim"(%add_value_const) {broadcast_dimensions = array<i64:>} : (tensor<f32>) -> tensor<6x7x12x12xf32>
  %mish_plus_add = stablehlo.add %mish, %add_value_broadcast : tensor<6x7x12x12xf32>

  // Step 6: Hardtanh activation with min_val=-1, max_val=1
  %min_val = stablehlo.constant dense<-1.0> : tensor<f32>
  %max_val = stablehlo.constant dense<1.0> : tensor<f32>
  %min_val_broadcast = "stablehlo.broadcast_in_dim"(%min_val) {broadcast_dimensions = array<i64:>} : (tensor<f32>) -> tensor<6x7x12x12xf32>
  %max_val_broadcast = "stablehlo.broadcast_in_dim"(%max_val) {broadcast_dimensions = array<i64:>} : (tensor<f32>) -> tensor<6x7x12x12xf32>
  %clamped_min = stablehlo.maximum %mish_plus_add, %min_val_broadcast : tensor<6x7x12x12xf32>
  %hardtanh = stablehlo.minimum %clamped_min, %max_val_broadcast : tensor<6x7x12x12xf32>

  // Step 7: multiply by scale = 2 (broadcast scalar)
  %scale_const = stablehlo.constant dense<2.0> : tensor<f32>
  %scale_broadcast = "stablehlo.broadcast_in_dim"(%scale_const) {broadcast_dimensions = array<i64:>} : (tensor<f32>) -> tensor<6x7x12x12xf32>
  %scaled = stablehlo.multiply %hardtanh, %scale_broadcast : tensor<6x7x12x12xf32>

  return %scaled : tensor<6x7x12x12xf32>
}

func.func @main(%arg0: tensor<7x7x3x3xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x7x6x6xf32>) -> tensor<6x7x12x12xf32> {
  // Transposed convolution parameters:
  // input: %arg2 (6x7x6x6)
  // weight: %arg0 (7x7x3x3) [out_channels, in_channels, kernel_h, kernel_w]
  // bias: %arg1 (7)
  // stride=2, padding=1, output_padding=1

  // stablehlo convolution dimension numbers for ConvTranspose2d:
  // PyTorch ConvTranspose2d input: NCHW (batch, in_channels, H, W)
  // weight shape: (in_channels, out_channels, kH, kW) in PyTorch, but here given as (7x7x3x3)
  // The problem states %arg0 = conv_transpose.weight with shape 7x7x3x3, which matches (out_channels, in_channels, kH, kW)
  // PyTorch ConvTranspose2d weight shape is (in_channels, out_channels, kH, kW), but here it's (out_channels, in_channels, kH, kW)
  // So we assume weight is already in (out_channels, in_channels, kH, kW) order as given.

  // For stablehlo convolution, dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>
  // This is standard conv: input batch, feature, spatial dims; kernel out_channel, in_channel, spatial dims; output batch, feature, spatial dims.

  // For ConvTranspose2d, we use convolution with lhs_dilation = stride, rhs_dilation = 1, and padding adjusted accordingly.
  // The formula for ConvTranspose2d output shape:
  // output = (input - 1) * stride - 2*padding + kernel_size + output_padding
  // Given stride=2, padding=1, kernel=3, output_padding=1:
  // output spatial = (6 - 1)*2 - 2*1 + 3 + 1 = 5*2 - 2 + 3 + 1 = 10 - 2 + 4 = 12
  // So output spatial dims are 12x12, matching the output shape.

  // stablehlo convolution for ConvTranspose2d:
  // lhs = input
  // rhs = weight
  // lhs_dilation = stride (2,2)
  // rhs_dilation = (1,1)
  // padding = [[kernel_h - 1 - padding, kernel_h - 1 - padding + output_padding], [kernel_w - 1 - padding, kernel_w - 1 - padding + output_padding]]
  // = [[3 - 1 - 1, 3 - 1 - 1 + 1], [3 - 1 - 1, 3 - 1 - 1 + 1]] = [[1, 2], [1, 2]]

  // Step 1: convolution transpose
  %c_stride = stablehlo.constant dense<2> : tensor<i64>
  %c_stride_arr = stablehlo.constant dense<[2, 2]> : tensor<2xi64>
  %c_padding = stablehlo.constant dense<[[1, 2], [1, 2]]> : tensor<2x2xi64>
  %c_lhs_dilation = stablehlo.constant dense<[2, 2]> : tensor<2xi64>
  %c_rhs_dilation = stablehlo.constant dense<[1, 1]> : tensor<2xi64>

  %conv = "stablehlo.convolution"(%arg2, %arg0) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[1, 2], [1, 2]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 2, 2>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x7x6x6xf32>, tensor<7x7x3x3xf32>) -> tensor<6x7x12x12xf32>

  // Step 2: add bias (broadcast bias over batch and spatial dims)
  // bias shape: 7
  // conv output shape: 6x7x12x12
  // broadcast bias to shape 6x7x12x12 with broadcast dims [1]
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7x12x12xf32>

  %conv_bias = stablehlo.add %conv, %bias_broadcast : tensor<6x7x12x12xf32>

  // Step 3: Mish activation: x * tanh(softplus(x))
  // softplus(x) = log(1 + exp(x))
  %exp = stablehlo.exponential %conv_bias : tensor<6x7x12x12xf32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_broadcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64:>} : (tensor<f32>) -> tensor<6x7x12x12xf32>
  %exp_plus_one = stablehlo.add %exp, %one_broadcast : tensor<6x7x12x12xf32>
  %softplus = stablehlo.log %exp_plus_one : tensor<6x7x12x12xf32>
  %tanh_softplus = stablehlo.tanh %softplus : tensor<6x7x12x12xf32>
  %mish = stablehlo.multiply %conv_bias, %tanh_softplus : tensor<6x7x12x12xf32>

  // Step 4: add add_value = 0.5 (broadcast scalar)
  %add_val = stablehlo.constant dense<0.5> : tensor<f32>
  %add_val_broadcast = "stablehlo.broadcast_in_dim"(%add_val) {broadcast_dimensions = array<i64:>} : (tensor<f32>) -> tensor<6x7x12x12xf32>
  %mish_plus = stablehlo.add %mish, %add_val_broadcast : tensor<6x7x12x12xf32>

  // Step 5: Hardtanh activation with min_val=-1, max_val=1
  %min_val = stablehlo.constant dense<-1.0> : tensor<f32>
  %max_val = stablehlo.constant dense<1.0> : tensor<f32>
  %min_val_broadcast = "stablehlo.broadcast_in_dim"(%min_val) {broadcast_dimensions = array<i64:>} : (tensor<f32>) -> tensor<6x7x12x12xf32>
  %max_val_broadcast = "stablehlo.broadcast_in_dim"(%max_val) {broadcast_dimensions = array<i64:>} : (tensor<f32>) -> tensor<6x7x12x12xf32>

  %clamped_min = stablehlo.maximum %mish_plus, %min_val_broadcast : tensor<6x7x12x12xf32>
  %hardtanh = stablehlo.minimum %clamped_min, %max_val_broadcast : tensor<6x7x12x12xf32>

  // Step 6: scale output by scale=2 (broadcast scalar)
  %scale_val = stablehlo.constant dense<2.0> : tensor<f32>
  %scale_broadcast = "stablehlo.broadcast_in_dim"(%scale_val) {broadcast_dimensions = array<i64:>} : (tensor<f32>) -> tensor<6x7x12x12xf32>
  %scaled = stablehlo.multiply %hardtanh, %scale_broadcast : tensor<6x7x12x12xf32>

  return %scaled : tensor<6x7x12x12xf32>
}

