func.func @main(%arg0: tensor<7x1x1xf32>, %arg1: tensor<7x7x3x3xf32>, %arg2: tensor<7xf32>, %arg3: tensor<6x7x6x6xf32>) -> tensor<6x7x12x12xf32> {
  // Perform transposed convolution with stride=2, padding=1, output_padding=1
  // dimension_numbers: input [b,f,h,w], kernel [o,i,h,w], output [b,f,h,w]
  // feature_group_count=1, batch_group_count=1
  %conv = "stablehlo.convolution"(%arg3, %arg1) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[1, 1], [1, 1]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 2, 2>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[0, 1, 2, 3]x[0, 1, 2, 3]->[0, 1, 2, 3]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x7x6x6xf32>, tensor<7x7x3x3xf32>) -> tensor<6x7x12x12xf32>

  // Broadcast bias %arg0 (7x1x1) to output shape (6x7x12x12)
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg0) {broadcast_dimensions = array<i64: 1, 2, 3>} : (tensor<7x1x1xf32>) -> tensor<6x7x12x12xf32>

  // Add bias
  %add_bias = stablehlo.add %conv, %bias_broadcast : tensor<6x7x12x12xf32>

  // Clamp min=0.0
  %c0 = stablehlo.constant dense<0.0> : tensor<f32>
  %c0_bcast = "stablehlo.broadcast_in_dim"(%c0) {broadcast_dimensions = array<i64: } : (tensor<f32>) -> tensor<6x7x12x12xf32>
  %clamp_min = stablehlo.maximum %add_bias, %c0_bcast : tensor<6x7x12x12xf32>

  // Clamp max=1.0
  %c1 = stablehlo.constant dense<1.0> : tensor<f32>
  %c1_bcast = "stablehlo.broadcast_in_dim"(%c1) {broadcast_dimensions = array<i64: } : (tensor<f32>) -> tensor<6x7x12x12xf32>
  %clamp_max = stablehlo.minimum %clamp_min, %c1_bcast : tensor<6x7x12x12xf32>

  // Multiply by scaling_factor=2.0
  %scale = stablehlo.constant dense<2.0> : tensor<f32>
  %scale_bcast = "stablehlo.broadcast_in_dim"(%scale) {broadcast_dimensions = array<i64: } : (tensor<f32>) -> tensor<6x7x12x12xf32>
  %scaled = stablehlo.multiply %clamp_max, %scale_bcast : tensor<6x7x12x12xf32>

  // Clamp again min=0.0
  %clamp_min2 = stablehlo.maximum %scaled, %c0_bcast : tensor<6x7x12x12xf32>

  // Clamp again max=1.0
  %clamp_max2 = stablehlo.minimum %clamp_min2, %c1_bcast : tensor<6x7x12x12xf32>

  // Divide by scaling_factor=2.0
  %result = stablehlo.divide %clamp_max2, %scale_bcast : tensor<6x7x12x12xf32>

  return %result : tensor<6x7x12x12xf32>
}

