func.func @main(%arg0: tensor<7x1x1xf32>, %arg1: tensor<7x7x3x3xf32>, %arg2: tensor<7xf32>, %arg3: tensor<6x7x6x6xf32>) -> tensor<6x7x12x12xf32> {
  // %arg0 = bias parameter (7x1x1)
  // %arg1 = conv_transpose.weight (7x7x3x3)
  // %arg2 = conv_transpose.bias (7)
  // %arg3 = input (6x7x6x6)

  // Step 1: Perform transposed convolution using stablehlo.convolution with rhs_dilation = kernel dilation = stride = 2
  // dimension_numbers: input [b, f, h, w], kernel [o, i, kh, kw] -> output [b, f, oh, ow]
  // feature_group_count = 1, batch_group_count = 1
  // window_strides = [1,1] (no stride on convolution itself)
  // padding = [[1,1],[1,1]] (padding)
  // lhs_dilation = [1,1] (no dilation on input)
  // rhs_dilation = [2,2] (dilate kernel to achieve transposed conv with stride=2)
  %conv = "stablehlo.convolution"(%arg3, %arg1) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[1, 1], [1, 1]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 1, 1>,
    rhs_dilation = array<i64: 2, 2>,
    dimension_numbers = #stablehlo.conv<[b, f, 2, 3]x[o, i, 2, 3]->[b, f, 2, 3]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x7x6x6xf32>, tensor<7x7x3x3xf32>) -> tensor<6x7x12x12xf32>

  // Step 2: Add bias (7x1x1) to conv output (6x7x12x12)
  // Broadcast bias over batch and spatial dims
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg0) {broadcast_dimensions = array<i64: 1, 2, 3>} : (tensor<7x1x1xf32>) -> tensor<6x7x12x12xf32>
  %add_bias = stablehlo.add %conv, %bias_broadcast : tensor<6x7x12x12xf32>

  // Step 3: Clamp between 0.0 and 1.0
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %zero_broadcast = "stablehlo.broadcast_in_dim"(%zero) {broadcast_dimensions = array<i64{0}>} : (tensor<f32>) -> tensor<6x7x12x12xf32>
  %one_broadcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64{0}>} : (tensor<f32>) -> tensor<6x7x12x12xf32>
  %clamp_min = stablehlo.maximum %add_bias, %zero_broadcast : tensor<6x7x12x12xf32>
  %clamp_0_1 = stablehlo.minimum %clamp_min, %one_broadcast : tensor<6x7x12x12xf32>

  // Step 4: Multiply by scaling_factor = 2.0
  %scale = stablehlo.constant dense<2.0> : tensor<f32>
  %scale_broadcast = "stablehlo.broadcast_in_dim"(%scale) {broadcast_dimensions = array<i64{0}>} : (tensor<f32>) -> tensor<6x7x12x12xf32>
  %scaled = stablehlo.multiply %clamp_0_1, %scale_broadcast : tensor<6x7x12x12xf32>

  // Step 5: Clamp again between 0.0 and 1.0
  %clamp_min2 = stablehlo.maximum %scaled, %zero_broadcast : tensor<6x7x12x12xf32>
  %clamp_0_1_2 = stablehlo.minimum %clamp_min2, %one_broadcast : tensor<6x7x12x12xf32>

  // Step 6: Divide by scaling_factor = 2.0
  %result = stablehlo.divide %clamp_0_1_2, %scale_broadcast : tensor<6x7x12x12xf32>

  return %result : tensor<6x7x12x12xf32>
}

func.func @main(%bias: tensor<7x1x1xf32>, %conv_weight: tensor<7x7x3x3xf32>, %conv_bias: tensor<7xf32>, %input: tensor<6x7x6x6xf32>) -> tensor<6x7x12x12xf32> {
  // Perform transposed convolution with conv_transpose parameters:
  // input: [6,7,6,6], weight: [7,7,3,3], stride=2, padding=1, output_padding=1
  // dimension_numbers: input [b,f,0,1], kernel [o,i,0,1], output [b,f,0,1]
  // lhs_dilation = stride = [2,2] for transposed convolution
  // rhs_dilation = [1,1]
  // padding = [[padding, padding + output_padding]] = [[1, 2], [1, 2]]
  %conv = "stablehlo.convolution"(%input, %conv_weight) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[1, 2], [1, 2]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 2, 2>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x7x6x6xf32>, tensor<7x7x3x3xf32>) -> tensor<6x7x12x12xf32>

  // Broadcast bias (7x1x1) to output shape (6x7x12x12)
  // bias shape: [7,1,1], output shape: [6,7,12,12]
  // broadcast dims: bias dims 0->1, 1->2, 2->3
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%bias) {broadcast_dimensions = array<i64: 1, 2, 3>} : (tensor<7x1x1xf32>) -> tensor<6x7x12x12xf32>

  // Add bias to conv output
  %add_bias = stablehlo.add %conv, %bias_broadcast : tensor<6x7x12x12xf32>

  // Clamp to [0.0, 1.0]
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %clamp_min = stablehlo.maximum %add_bias, %zero : tensor<6x7x12x12xf32>
  %clamp_0_1 = stablehlo.minimum %clamp_min, %one : tensor<6x7x12x12xf32>

  // scaling_factor = 2.0 constant tensor scalar
  %scale = stablehlo.constant dense<2.0> : tensor<f32>

  // Multiply by scaling_factor
  %scaled = stablehlo.multiply %clamp_0_1, %scale : tensor<6x7x12x12xf32>

  // Clamp again to [0.0, 1.0]
  %clamp_min2 = stablehlo.maximum %scaled, %zero : tensor<6x7x12x12xf32>
  %clamp_0_1_2 = stablehlo.minimum %clamp_min2, %one : tensor<6x7x12x12xf32>

  // Divide by scaling_factor
  %result = stablehlo.divide %clamp_0_1_2, %scale : tensor<6x7x12x12xf32>

  return %result : tensor<6x7x12x12xf32>
}

func.func @main(%bias: tensor<7x1x1xf32>, %conv_transpose_weight: tensor<7x7x3x3xf32>, %conv_transpose_bias: tensor<7xf32>, %input: tensor<6x7x6x6xf32>) -> tensor<6x7x12x12xf32> {
  // Step 1: Perform transposed convolution using stablehlo.convolution with lhs_dilation=2 and rhs_dilation=1
  // dimension_numbers: input [b, f, h, w] = [6,7,6,6]
  // kernel [o, i, kh, kw] = [7,7,3,3]
  // output [b, f, h, w] = [6,7,12,12]
  %conv = "stablehlo.convolution"(%input, %conv_transpose_weight) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[1, 1], [1, 1]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 2, 2>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x7x6x6xf32>, tensor<7x7x3x3xf32>) -> tensor<6x7x12x12xf32>

  // Step 2: Add conv_transpose_bias (shape [7]) to conv output (shape [6x7x12x12])
  // Broadcast conv_transpose_bias to [6x7x12x12]
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%conv_transpose_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7x12x12xf32>
  %conv_plus_bias = stablehlo.add %conv, %bias_broadcast : tensor<6x7x12x12xf32>

  // Step 3: Add bias (shape [7x1x1]) to conv_plus_bias (shape [6x7x12x12])
  // Broadcast bias to [6x7x12x12]
  // bias shape: [7x1x1], broadcast dims to output dims [batch=6, feat=7, h=12, w=12]
  // bias dims correspond to output dims [feat=1, h=2, w=3], so broadcast_dimensions = [1, 2, 3]
  %bias_broadcast2 = "stablehlo.broadcast_in_dim"(%bias) {broadcast_dimensions = array<i64: 1, 2, 3>} : (tensor<7x1x1xf32>) -> tensor<6x7x12x12xf32>
  %add_bias = stablehlo.add %conv_plus_bias, %bias_broadcast2 : tensor<6x7x12x12xf32>

  // Step 4: Clamp to [0.0, 1.0]
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %clamp_min = stablehlo.maximum %add_bias, %zero : tensor<6x7x12x12xf32>
  %clamp = stablehlo.minimum %clamp_min, %one : tensor<6x7x12x12xf32>

  // Step 5: Multiply by scaling_factor = 2.0
  %scale = stablehlo.constant dense<2.0> : tensor<f32>
  // Broadcast scale scalar to tensor<6x7x12x12xf32>
  %scale_broadcast = "stablehlo.broadcast_in_dim"(%scale) {broadcast_dimensions = array<i64: } : (tensor<f32>) -> tensor<6x7x12x12xf32>
  // Actually broadcast_dimensions empty array means scalar broadcast to all dims
  %scale_broadcast = "stablehlo.broadcast_in_dim"(%scale) {broadcast_dimensions = array<i64: } : (tensor<f32>) -> tensor<6x7x12x12xf32>
  // But stablehlo.broadcast_in_dim requires broadcast_dimensions length == operand rank (0 here), so empty array is correct
  // So we write it once:
  %scale_broadcast = "stablehlo.broadcast_in_dim"(%scale) {broadcast_dimensions = array<i64: } : (tensor<f32>) -> tensor<6x7x12x12xf32>
  // Multiply
  %scaled = stablehlo.multiply %clamp, %scale_broadcast : tensor<6x7x12x12xf32>

  // Step 6: Clamp again to [0.0, 1.0]
  %clamp2_min = stablehlo.maximum %scaled, %zero : tensor<6x7x12x12xf32>
  %clamp2 = stablehlo.minimum %clamp2_min, %one : tensor<6x7x12x12xf32>

  // Step 7: Divide by scaling_factor = 2.0
  %divided = stablehlo.divide %clamp2, %scale_broadcast : tensor<6x7x12x12xf32>

  // Return final result
  return %divided : tensor<6x7x12x12xf32>
}

func.func @main(%ln_weight: tensor<6x7x7xf32>, %ln_bias: tensor<6x7x7xf32>, %x: tensor<16x6x7x7xf32>) -> tensor<16x6x7x7xf32> {
  // Compute mean over last 3 dims: dims = [1,2,3]
  %c0 = stablehlo.constant dense<0.0> : tensor<f32>
  %mean = "stablehlo.reduce"(%x, %c0) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1, 2, 3>} : (tensor<16x6x7x7xf32>, tensor<f32>) -> tensor<16xf32>
  // Normalize mean by dividing by 6*7*7=294
  %c294 = stablehlo.constant dense<294.0> : tensor<f32>
  %mean_div = stablehlo.divide %mean, %c294 : tensor<16xf32>
  // Broadcast mean_div to shape 16x6x7x7
  %mean_bcast = "stablehlo.broadcast_in_dim"(%mean_div) {broadcast_dimensions = array<i64: 0} : (tensor<16xf32>) -> tensor<16x1x1x1xf32>
  %mean_bcast2 = "stablehlo.broadcast_in_dim"(%mean_bcast) {broadcast_dimensions = array<i64: 0,1,2,3>} : (tensor<16x1x1x1xf32>) -> tensor<16x6x7x7xf32>

  // Compute variance: mean of squared differences
  %diff = stablehlo.subtract %x, %mean_bcast2 : tensor<16x6x7x7xf32>
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<16x6x7x7xf32>
  %var_sum = "stablehlo.reduce"(%diff_sq, %c0) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1, 2, 3>} : (tensor<16x6x7x7xf32>, tensor<f32>) -> tensor<16xf32>
  %var = stablehlo.divide %var_sum, %c294 : tensor<16xf32>
  // Broadcast var to shape 16x6x7x7
  %var_bcast = "stablehlo.broadcast_in_dim"(%var) {broadcast_dimensions = array<i64: 0} : (tensor<16xf32>) -> tensor<16x1x1x1xf32>
  %var_bcast2 = "stablehlo.broadcast_in_dim"(%var_bcast) {broadcast_dimensions = array<i64: 0,1,2,3>} : (tensor<16x1x1x1xf32>) -> tensor<16x6x7x7xf32>

  // epsilon constant
  %epsilon = stablehlo.constant dense<1.0e-5> : tensor<f32>
  %var_eps = stablehlo.add %var_bcast2, %epsilon : tensor<16x6x7x7xf32>
  %rsqrt_var = stablehlo.rsqrt %var_eps : tensor<16x6x7x7xf32>

  // Broadcast ln.weight and ln.bias from 6x7x7 to 16x6x7x7
  %ln_weight_bcast = "stablehlo.broadcast_in_dim"(%ln_weight) {broadcast_dimensions = array<i64: 1, 2, 3>} : (tensor<6x7x7xf32>) -> tensor<16x6x7x7xf32>
  %ln_bias_bcast = "stablehlo.broadcast_in_dim"(%ln_bias) {broadcast_dimensions = array<i64: 1, 2, 3>} : (tensor<6x7x7xf32>) -> tensor<16x6x7x7xf32>

  // Normalize: (x - mean) * rsqrt_var
  %normed = stablehlo.multiply %diff, %rsqrt_var : tensor<16x6x7x7xf32>
  // Scale and shift: normed * weight + bias
  %scaled = stablehlo.multiply %normed, %ln_weight_bcast : tensor<16x6x7x7xf32>
  %shifted = stablehlo.add %scaled, %ln_bias_bcast : tensor<16x6x7x7xf32>

  return %shifted : tensor<16x6x7x7xf32>
}

func.func @main(%ln_weight: tensor<6x7x7xf32>, %ln_bias: tensor<6x7x7xf32>, %x: tensor<16x6x7x7xf32>) -> tensor<16x6x7x7xf32> {
  // Compute mean over last 3 dims (axes 1,2,3) for each batch element
  %c0 = stablehlo.constant dense<0.0> : tensor<f32>
  %mean = "stablehlo.reduce"(%x, %c0) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1, 2, 3>} : (tensor<16x6x7x7xf32>, tensor<f32>) -> tensor<16xf32>

  // Compute divisor = 1/(6*7*7) = 1/294
  %c294 = stablehlo.constant dense<294.0> : tensor<f32>
  %c1 = stablehlo.constant dense<1.0> : tensor<f32>
  %inv_count = stablehlo.divide %c1, %c294 : tensor<f32>

  // mean = mean * inv_count
  %mean_scaled = stablehlo.multiply %mean, %inv_count : tensor<16xf32>

  // Broadcast mean_scaled to shape 16x6x7x7
  %mean_bcast = "stablehlo.broadcast_in_dim"(%mean_scaled) {broadcast_dimensions = array<i64: 0>} : (tensor<16xf32>) -> tensor<16x1x1x1xf32>
  %mean_bcast2 = "stablehlo.broadcast_in_dim"(%mean_bcast) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<16x1x1x1xf32>) -> tensor<16x6x7x7xf32>

  // Compute x - mean
  %x_centered = stablehlo.subtract %x, %mean_bcast2 : tensor<16x6x7x7xf32>

  // Compute variance: mean of squared differences
  %x_centered_sq = stablehlo.multiply %x_centered, %x_centered : tensor<16x6x7x7xf32>
  %var_sum = "stablehlo.reduce"(%x_centered_sq, %c0) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1, 2, 3>} : (tensor<16x6x7x7xf32>, tensor<f32>) -> tensor<16xf32>
  %var = stablehlo.multiply %var_sum, %inv_count : tensor<16xf32>

  // Broadcast var to 16x6x7x7
  %var_bcast = "stablehlo.broadcast_in_dim"(%var) {broadcast_dimensions = array<i64: 0>} : (tensor<16xf32>) -> tensor<16x1x1x1xf32>
  %var_bcast2 = "stablehlo.broadcast_in_dim"(%var_bcast) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<16x1x1x1xf32>) -> tensor<16x6x7x7xf32>

  // epsilon constant for numerical stability
  %epsilon = stablehlo.constant dense<1e-5> : tensor<f32>

  // var + epsilon
  %var_eps = stablehlo.add %var_bcast2, %epsilon : tensor<16x6x7x7xf32>

  // rsqrt(var + epsilon)
  %inv_std = stablehlo.rsqrt %var_eps : tensor<16x6x7x7xf32>

  // Broadcast ln.weight and ln.bias from 6x7x7 to 16x6x7x7
  %ln_weight_bcast = "stablehlo.broadcast_in_dim"(%ln_weight) {broadcast_dimensions = array<i64: 1, 2, 3>} : (tensor<6x7x7xf32>) -> tensor<16x6x7x7xf32>
  %ln_bias_bcast = "stablehlo.broadcast_in_dim"(%ln_bias) {broadcast_dimensions = array<i64: 1, 2, 3>} : (tensor<6x7x7xf32>) -> tensor<16x6x7x7xf32>

  // normalized = (x - mean) * inv_std
  %normalized = stablehlo.multiply %x_centered, %inv_std : tensor<16x6x7x7xf32>

  // output = normalized * weight + bias
  %scaled = stablehlo.multiply %normalized, %ln_weight_bcast : tensor<16x6x7x7xf32>
  %output = stablehlo.add %scaled, %ln_bias_bcast : tensor<16x6x7x7xf32>

  return %output : tensor<16x6x7x7xf32>
}

func.func @main(%ln_weight: tensor<6x7x7xf32>, %ln_bias: tensor<6x7x7xf32>, %x: tensor<16x6x7x7xf32>) -> tensor<16x6x7x7xf32> {
