  %var_bcast_reshaped = "stablehlo.broadcast_in_dim"(%var_bcast) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<16x1x1x1xf32>) -> tensor<16x6x7x7xf32>

  // epsilon constant for numerical stability
  %epsilon = stablehlo.constant dense<1.000000e-05> : tensor<f32>
  %epsilon_bcast = "stablehlo.broadcast_in_dim"(%epsilon) {broadcast_dimensions = array<i64:>} : (tensor<f32>) -> tensor<f32>
  %epsilon_bcast_reshaped = "stablehlo.broadcast_in_dim"(%epsilon) {broadcast_dimensions = array<i64:>} : (tensor<f32>) -> tensor<f32>
  // broadcast epsilon to shape [16x6x7x7]
  %epsilon_bcast_4d = "stablehlo.broadcast_in_dim"(%epsilon) {broadcast_dimensions = array<i64: } : (tensor<f32>) -> tensor<16x6x7x7xf32>
