  %mean_bcast = "stablehlo.broadcast_in_dim"(%mean_div) {broadcast_dimensions = array<i64: 0>} : (tensor<16xf32>) -> tensor<16x1xf32>
  %mean_bcast2 = "stablehlo.broadcast_in_dim"(%mean_bcast) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<16x1xf32>) -> tensor<16x6x1xf32>
  %mean_bcast3 = "stablehlo.broadcast_in_dim"(%mean_bcast2) {broadcast_dimensions = array<i64: 0, 1, 2>} : (tensor<16x6x1xf32>) -> tensor<16x6x7xf32>
  %mean_bcast4 = "stablehlo.broadcast_in_dim"(%mean_bcast3) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<16x6x7xf32>) -> tensor<16x6x7x7xf32>

  // Compute (x - mean)
  %x_centered = stablehlo.subtract %x, %mean_bcast4 : tensor<16x6x7x7xf32>

