  }) {dimensions = array<i64: 1, 2, 3>} : (tensor<16x6x7x7xf32>, tensor<f32>) -> tensor<16xf32>

  // variance = var_sum / 294
  %var = stablehlo.divide %var_sum, %c294 : tensor<16xf32>

  // Broadcast variance to shape 16x6x7x7
  %var_bcast = "stablehlo.broadcast_in_dim"(%var) {broadcast_dimensions = array<i64: 0>} : (tensor<16xf32>) -> tensor<16x1xf32>
