  }) {dimensions = array<i64: 3>} : (tensor<6x6x7x7xf32>, tensor<f32>) -> tensor<6x6x7xf32>

  // broadcast max to shape [6,6,7,7]
  %max_bcast = "stablehlo.broadcast_in_dim"(%max) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<6x6x7xf32>) -> tensor<6x6x7x7xf32>

  // subtract max from qk_scaled
