func.func @main(%arg0: tensor<6x6x7x8xf32>, %arg1: tensor<6x6x7x8xf32>, %arg2: tensor<6x6x7x8xf32>) -> tensor<6x6x7x8xf32> {
  // %arg0 = Q, %arg1 = K, %arg2 = V

  // Step 1: Compute QK^T scaled by 1/sqrt(embedding_dimension)
  // Transpose K from [6,6,7,8] to [6,6,8,7]
  %k_t = "stablehlo.transpose"(%arg1) {permutation = array<i64: 0, 1, 3, 2>} : (tensor<6x6x7x8xf32>) -> tensor<6x6x8x7xf32>

  // Dot general: batch dims = [0,1], contracting dims = [3] of Q and [2] of K^T
  // Q shape: [6,6,7,8], K^T shape: [6,6,8,7]
  // Result shape: [6,6,7,7]
  %qk = "stablehlo.dot_general"(%arg0, %k_t) {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [0, 1],
      rhs_batching_dimensions = [0, 1],
      lhs_contracting_dimensions = [3],
      rhs_contracting_dimensions = [2]>
  } : (tensor<6x6x7x8xf32>, tensor<6x6x8x7xf32>) -> tensor<6x6x7x7xf32>

  // Step 2: Scale by 1/sqrt(embedding_dimension)
  // embedding_dimension = 8, sqrt(8) ≈ 2.828427
  %scale = stablehlo.constant dense<0.35355338> : tensor<f32>  // 1/2.828427 = 0.35355338

  // Broadcast scale to [6,6,7,7]
  %scale_bcast = "stablehlo.broadcast_in_dim"(%scale) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x7x7xf32>

  %scaled_qk = stablehlo.multiply %qk, %scale_bcast : tensor<6x6x7x7xf32>

  // Step 3: Compute softmax over last dimension (dim=3) of scaled_qk
  // softmax(x) = exp(x - max(x)) / sum(exp(x - max(x)))

  // Compute max over dim=3
  %init_max = stablehlo.constant dense<-3.4028235e+38> : tensor<f32>  // -inf for max reduction
  %max = "stablehlo.reduce"(%scaled_qk, %init_max) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.maximum %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 3>} : (tensor<6x6x7x7xf32>, tensor<f32>) -> tensor<6x6x7xf32>

  // Broadcast max to shape [6,6,7,7]
  %max_bcast = "stablehlo.broadcast_in_dim"(%max) {broadcast_dimensions = array<i64: 0, 1, 2>} : (tensor<6x6x7xf32>) -> tensor<6x6x7x7xf32>

  // Subtract max for numerical stability
  %shifted = stablehlo.subtract %scaled_qk, %max_bcast : tensor<6x6x7x7xf32>

  // Exponentiate
  %exp = stablehlo.exponential %shifted : tensor<6x6x7x7xf32>

  // Compute sum over dim=3
  %init_zero = stablehlo.constant dense<0.0> : tensor<f32>
  %sum_exp = "stablehlo.reduce"(%exp, %init_zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 3>} : (tensor<6x6x7x7xf32>, tensor<f32>) -> tensor<6x6x7xf32>

  // Broadcast sum_exp to shape [6,6,7,7]
  %sum_exp_bcast = "stablehlo.broadcast_in_dim"(%sum_exp) {broadcast_dimensions = array<i64: 0, 1, 2>} : (tensor<6x6x7xf32>) -> tensor<6x6x7x7xf32>

  // Divide exp by sum_exp to get softmax
  %softmax = stablehlo.divide %exp, %sum_exp_bcast : tensor<6x6x7x7xf32>

  // Step 4: Multiply softmax weights by V
  // V shape: [6,6,7,8]
  // Dot general: batch dims = [0,1,2], contracting dims = [3] of softmax and [2] of V
  // softmax shape: [6,6,7,7], V shape: [6,6,7,8]
  // Result shape: [6,6,7,8]
  %out = "stablehlo.dot_general"(%softmax, %arg2) {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [0, 1, 2],
      rhs_batching_dimensions = [0, 1, 2],
      lhs_contracting_dimensions = [3],
      rhs_contracting_dimensions = [2]>
  } : (tensor<6x6x7x7xf32>, tensor<6x6x7x8xf32>) -> tensor<6x6x7x8xf32>

  return %out : tensor<6x6x7x8xf32>
}

func.func @main(%arg0: tensor<6x6x7x8xf32>, %arg1: tensor<6x6x7x8xf32>, %arg2: tensor<6x6x7x8xf32>) -> tensor<6x6x7x8xf32> {
  // %arg0 = Q, %arg1 = K, %arg2 = V

  // Step 1: Compute QK^T scaled by 1/sqrt(embedding_dimension)
  // Transpose K on last two dims: from [6,6,7,8] to [6,6,8,7]
  %k_t = "stablehlo.transpose"(%arg1) {permutation = array<i64: 0, 1, 3, 2>} : (tensor<6x6x7x8xf32>) -> tensor<6x6x8x7xf32>

  // Dot general Q and K^T:
  // Batch dims: [0,1]
  // Contract dims: Q last dim 3, K^T second last dim 2
  // Result shape: [6,6,7,7]
  %qk = "stablehlo.dot_general"(%arg0, %k_t) {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [0, 1],
      rhs_batching_dimensions = [0, 1],
      lhs_contracting_dimensions = [3],
      rhs_contracting_dimensions = [2]>
  } : (tensor<6x6x7x8xf32>, tensor<6x6x8x7xf32>) -> tensor<6x6x7x7xf32>

  // Step 2: Scale by 1/sqrt(embedding_dimension)
  // embedding_dimension = 8, sqrt(8) ≈ 2.828427
  %scale_val = stablehlo.constant dense<0.35355338> : tensor<f32>  // 1/2.828427 = 0.35355338
  // Broadcast scale_val to shape [6,6,7,7]
  %scale = "stablehlo.broadcast_in_dim"(%scale_val) {broadcast_dimensions = array<i64: []>} : (tensor<f32>) -> tensor<f32>
  // Actually broadcast_in_dim requires rank of operand = rank of result, so reshape scale_val to scalar tensor and broadcast:
  %scale_broadcast = "stablehlo.broadcast_in_dim"(%scale_val) {broadcast_dimensions = array<i64: } : (tensor<f32>) -> tensor<6x6x7x7xf32>
  // But stablehlo.broadcast_in_dim requires broadcast_dimensions length = rank(operand)
  // So we do broadcast_in_dim with empty broadcast_dimensions for scalar to scalar is invalid.
  // Instead, we do broadcast_in_dim with broadcast_dimensions = [] for scalar to scalar, then reshape to scalar tensor, then broadcast.
  // Let's do it stepwise:

  // Actually, stablehlo.broadcast_in_dim requires size(broadcast_dimensions) = rank(operand)
  // For scalar operand rank=0, broadcast_dimensions = [] is valid.
  // So broadcast_in_dim(%scale_val) {broadcast_dimensions = []} : (tensor<f32>) -> tensor<6x6x7x7xf32> is invalid because rank(operand)=0, rank(result)=4
  // So we must reshape scale_val to tensor<1xf32> then broadcast_in_dim with broadcast_dimensions=[0] to tensor<6x6x7x7xf32> is invalid because 1 != 4
  // Instead, we can use stablehlo.broadcast_in_dim with scalar operand and broadcast_dimensions = [] to get scalar, then multiply with qk which broadcasts scalar automatically.
  // But StableHLO semantics say no implicit broadcast.
  // So we must broadcast explicitly.

  // So create a constant tensor of shape [6,6,7,7] filled with scale_val.
  %scale_tensor = stablehlo.constant dense<0.35355338> : tensor<f32>
  %scale_bcast = "stablehlo.broadcast_in_dim"(%scale_tensor) {broadcast_dimensions = array<i64: } : (tensor<f32>) -> tensor<6x6x7x7xf32>
  // But again, broadcast_dimensions length must equal rank(operand) = 0, so array<i64: > is empty array, valid.
  // So this broadcasts scalar to tensor<6x6x7x7xf32>.

  // Multiply qk by scale_bcast
  %scaled_qk = stablehlo.multiply %qk, %scale_bcast : tensor<6x6x7x7xf32>

  // Step 3: Compute softmax over last dimension (dim=3) of scaled_qk
  // softmax(x) = exp(x - max(x)) / sum(exp(x - max(x)))

  // Compute max over last dim (dim=3), keepdims = true for broadcasting
  %init_max = stablehlo.constant dense<-3.4028235e+38> : tensor<f32>  // -inf for max reduction
  %max = "stablehlo.reduce"(%scaled_qk, %init_max) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.maximum %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 3>} : (tensor<6x6x7x7xf32>, tensor<f32>) -> tensor<6x6x7xf32>

  // Broadcast max back to shape [6,6,7,7] for subtraction
  %max_bcast = "stablehlo.broadcast_in_dim"(%max) {broadcast_dimensions = array<i64: 0, 1, 2>} : (tensor<6x6x7xf32>) -> tensor<6x6x7x7xf32>

  // Subtract max from scaled_qk
  %shifted = stablehlo.subtract %scaled_qk, %max_bcast : tensor<6x6x7x7xf32>

  // Exponentiate
  %exp = stablehlo.exponential %shifted : tensor<6x6x7x7xf32>

  // Compute sum over last dim (dim=3) of exp
  %init_zero = stablehlo.constant dense<0.0> : tensor<f32>
  %sum_exp = "stablehlo.reduce"(%exp, %init_zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 3>} : (tensor<6x6x7x7xf32>, tensor<f32>) -> tensor<6x6x7xf32>

  // Broadcast sum_exp back to shape [6,6,7,7]
  %sum_exp_bcast = "stablehlo.broadcast_in_dim"(%sum_exp) {broadcast_dimensions = array<i64: 0, 1, 2>} : (tensor<6x6x7xf32>) -> tensor<6x6x7x7xf32>

  // Divide exp by sum_exp to get softmax
  %softmax = stablehlo.divide %exp, %sum_exp_bcast : tensor<6x6x7x7xf32>

  // Step 4: Multiply softmax weights by V
  // V shape: [6,6,7,8]
  // softmax shape: [6,6,7,7]
  // We want to do dot_general over last dim of softmax (dim=3) and second last dim of V (dim=2)
  // Batch dims: [0,1]
  // Contract dims: softmax dim 3, V dim 2
  // Result shape: [6,6,7,8]

  %out = "stablehlo.dot_general"(%softmax, %arg2) {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [0, 1],
      rhs_batching_dimensions = [0, 1],
      lhs_contracting_dimensions = [3],
      rhs_contracting_dimensions = [2]>
  } : (tensor<6x6x7x7xf32>, tensor<6x6x7x8xf32>) -> tensor<6x6x7x8xf32>

  return %out : tensor<6x6x7x8xf32>
}

func.func @main(%arg0: tensor<12x12xf32>, %arg1: tensor<12x12xf32>) -> tensor<f32> {
  // Compute log(predictions) = log(%arg0)
  %log_pred = stablehlo.log %arg0 : tensor<12x12xf32>

  // Compute element-wise multiplication: targets * log(predictions)
  %mul = stablehlo.multiply %arg1, %log_pred : tensor<12x12xf32>

  // Sum all elements in %mul to get scalar sum
  %init = stablehlo.constant dense<0.0> : tensor<f32>
  %sum = "stablehlo.reduce"(%mul, %init) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0, 1>} : (tensor<12x12xf32>, tensor<f32>) -> tensor<f32>

  // Divide sum by batch size (12) to get mean over batch dimension
  %batch_size = stablehlo.constant dense<12.0> : tensor<f32>
  %mean = stablehlo.divide %sum, %batch_size : tensor<f32>

  // Return negative mean as KL divergence with reduction='batchmean'
  %neg = stablehlo.negate %mean : tensor<f32>
  return %neg : tensor<f32>
}

func.func @main(%arg0: tensor<12x12xf32>, %arg1: tensor<12x12xf32>) -> tensor<f32> {
  // Compute log(predictions) = log(%arg0)
  %log_pred = stablehlo.log %arg0 : tensor<12x12xf32>

  // Compute element-wise multiplication: targets * log(predictions)
  %mul = stablehlo.multiply %arg1, %log_pred : tensor<12x12xf32>

  // Compute element-wise subtraction: targets - targets * log(predictions)
  %sub = stablehlo.subtract %arg1, %mul : tensor<12x12xf32>

  // Sum over last dimension (dim=1) to get shape tensor<12xf32>
  %init_sum = stablehlo.constant dense<0.0> : tensor<f32>
  %sum_dim1 = "stablehlo.reduce"(%sub, %init_sum) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %c : tensor<f32>
  }) {dimensions = array<i64: 1>} : (tensor<12x12xf32>, tensor<f32>) -> tensor<12xf32>

  // Sum over batch dimension (dim=0) to get scalar tensor<f32>
  %init_sum2 = stablehlo.constant dense<0.0> : tensor<f32>
  %sum_dim0 = "stablehlo.reduce"(%sum_dim1, %init_sum2) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %c : tensor<f32>
  }) {dimensions = array<i64: 0>} : (tensor<12xf32>, tensor<f32>) -> tensor<f32>

  // Divide by batch size (12) to get mean
  %batch_size = stablehlo.constant dense<12.0> : tensor<f32>
  %result = stablehlo.divide %sum_dim0, %batch_size : tensor<f32>

  return %result : tensor<f32>
}

func.func @main(%arg0: tensor<12x12xf32>, %arg1: tensor<12x12xf32>) -> tensor<f32> {
  // Compute log(predictions) elementwise
  %log_pred = stablehlo.log %arg0 : tensor<12x12xf32>

  // Compute elementwise: log(predictions) - targets
  %diff = stablehlo.subtract %log_pred, %arg1 : tensor<12x12xf32>

  // Compute elementwise: targets * (log(predictions) - targets)
  %mul = stablehlo.multiply %arg1, %diff : tensor<12x12xf32>

  // Sum all elements of %mul to get scalar sum
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %sum = "stablehlo.reduce"(%mul, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0, 1>} : (tensor<12x12xf32>, tensor<f32>) -> tensor<f32>

  // Divide sum by total number of elements (12*12=144) to get batchmean reduction
  %denominator = stablehlo.constant dense<144.0> : tensor<f32>
  %result = stablehlo.divide %sum, %denominator : tensor<f32>

  return %result : tensor<f32>
}

func.func @main(%arg0: tensor<12x12xf32>, %arg1: tensor<12x12xf32>) -> tensor<f32> {
  // Compute log(predictions) elementwise
  %log_pred = stablehlo.log %arg0 : tensor<12x12xf32>

  // Compute elementwise: log(predictions) - targets
  %diff = stablehlo.subtract %log_pred, %arg1 : tensor<12x12xf32>

  // Compute elementwise: targets * (log(predictions) - targets)
  %mul = stablehlo.multiply %arg1, %diff : tensor<12x12xf32>

  // Initialize zero scalar for reduce init
  %zero = stablehlo.constant dense<0.0> : tensor<f32>

  // Sum over all elements (reduce all dims 0 and 1)
  %sum = "stablehlo.reduce"(%mul, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0, 1>} : (tensor<12x12xf32>, tensor<f32>) -> tensor<f32>

  // Compute batchmean: divide sum by batch size (12)
  %batch_size = stablehlo.constant dense<12.0> : tensor<f32>
  %result = stablehlo.divide %sum, %batch_size : tensor<f32>

  return %result : tensor<f32>
}

func.func @main(%arg0: tensor<16x16xf32>, %arg1: tensor<16xf32>, %arg2: tensor<16xf32>, %arg3: tensor<16xf32>, %arg4: tensor<16x16xf32>) -> tensor<16x16xf32> {
  // Fully connected layer: x @ fc.weight^T + fc.bias
  // %arg0 = fc.weight (16x16), %arg1 = fc.bias (16), %arg4 = input (16x16)
  // We need to do dot_general with contracting dims: input last dim (1), weight last dim (1)
  // But weight is (16x16), we want to multiply input (16x16) with weight^T (16x16)
  // So transpose weight to (16x16) (actually same shape), but transpose dims [1,0]
  %weight_t = "stablehlo.transpose"(%arg0) {permutation = array<i64: 1, 0>} : (tensor<16x16xf32>) -> tensor<16x16xf32>
  %fc_dot = "stablehlo.dot_general"(%arg4, %weight_t) {dot_dimension_numbers = #stablehlo.dot<lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [1]>} : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
  %fc_out = "stablehlo.add"(%fc_dot, "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>}) : (tensor<16x16xf32>, tensor<16xf32>) -> tensor<16x16xf32>

  // GroupNorm:
  // num_groups = 16, num_channels = 16, so each group has 1 channel (C=16, G=16)
  // Input shape: (N=16, C=16)
  // Reshape to (N=16, G=16, C_per_group=1)
  %reshape1 = "stablehlo.reshape"(%fc_out) : (tensor<16x16xf32>) -> tensor<16x16x1xf32>

  // Compute mean over C_per_group dimension (dim=2)
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %mean = "stablehlo.reduce"(%reshape1, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2>} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>
  // mean shape: (16,16)

  // Compute variance: mean of (x - mean)^2 over dim=2
  // Broadcast mean to shape (16,16,1)
  %mean_broadcast = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<16x16xf32>) -> tensor<16x16x1xf32>
  %diff = "stablehlo.subtract"(%reshape1, %mean_broadcast) : (tensor<16x16x1xf32>, tensor<16x16x1xf32>) -> tensor<16x16x1xf32>
  %sq_diff = "stablehlo.multiply"(%diff, %diff) : (tensor<16x16x1xf32>, tensor<16x16x1xf32>) -> tensor<16x16x1xf32>
  %var = "stablehlo.reduce"(%sq_diff, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum2 = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%sum2) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2>} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>

  // variance shape: (16,16)
  // Since C_per_group=1, mean and variance are over single element, so var=0, but we keep formula

  // Add eps=1e-5 to variance
  %eps = stablehlo.constant dense<0.00001> : tensor<f32>
  %eps_broadcast = "stablehlo.broadcast_in_dim"(%eps) {broadcast_dimensions = array<i64:>} : (tensor<f32>) -> tensor<f32>
  %var_eps = "stablehlo.add"(%var, %eps_broadcast) : (tensor<16x16xf32>, tensor<f32>) -> tensor<16x16xf32>

  // Compute rsqrt(var + eps)
  %inv_std = "stablehlo.rsqrt" %var_eps : tensor<16x16xf32>

  // Broadcast mean and inv_std to (16,16,1)
  %mean_broadcast2 = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<16x16xf32>) -> tensor<16x16x1xf32>
  %inv_std_broadcast = "stablehlo.broadcast_in_dim"(%inv_std) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<16x16xf32>) -> tensor<16x16x1xf32>

  // Normalize: (x - mean) * inv_std
  %x_centered = "stablehlo.subtract"(%reshape1, %mean_broadcast2) : (tensor<16x16x1xf32>, tensor<16x16x1xf32>) -> tensor<16x16x1xf32>
  %x_norm = "stablehlo.multiply"(%x_centered, %inv_std_broadcast) : (tensor<16x16x1xf32>, tensor<16x16x1xf32>) -> tensor<16x16x1xf32>

  // Apply affine transform: x_norm * gn.weight + gn.bias
  // %arg2 = gn.weight (16), %arg3 = gn.bias (16)
  // Broadcast gn.weight and gn.bias to (16,16,1)
  %gn_weight_broadcast = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16x1xf32>
  %gn_bias_broadcast = "stablehlo.broadcast_in_dim"(%arg3) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16x1xf32>
  %scaled = "stablehlo.multiply"(%x_norm, %gn_weight_broadcast) : (tensor<16x16x1xf32>, tensor<16x16x1xf32>) -> tensor<16x16x1xf32>
  %shifted = "stablehlo.add"(%scaled, %gn_bias_broadcast) : (tensor<16x16x1xf32>, tensor<16x16x1xf32>) -> tensor<16x16x1xf32>

  // Reshape back to (16,16)
  %gn_out = "stablehlo.reshape"(%shifted) : (tensor<16x16x1xf32>) -> tensor<16x16xf32>

  // LeakyReLU with negative_slope=0.01
  // leaky_relu(x) = max(0,x) + negative_slope * min(0,x)
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %zero_broadcast = "stablehlo.broadcast_in_dim"(%zero) {broadcast_dimensions = array<i64:>} : (tensor<f32>) -> tensor<f32>
  %zero_tensor = "stablehlo.broadcast_in_dim"(%zero) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<f32>) -> tensor<16x16xf32>
  %max_part = "stablehlo.maximum"(%gn_out, %zero_tensor) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
  %min_part = "stablehlo.minimum"(%gn_out, %zero_tensor) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
  %slope = stablehlo.constant dense<0.01> : tensor<f32>
  %slope_broadcast = "stablehlo.broadcast_in_dim"(%slope) {broadcast_dimensions = array<i64:>} : (tensor<f32>) -> tensor<f32>
  %slope_tensor = "stablehlo.broadcast_in_dim"(%slope_broadcast) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<f32>) -> tensor<16x16xf32>
  %scaled_min = "stablehlo.multiply

