  %neg_slope = stablehlo.constant dense<0.01> : tensor<f32>
  %neg_slope_broadcast = "stablehlo.broadcast_in_dim"(%neg_slope) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<f32>
  %gn_out_neg = stablehlo.multiply %gn_out, %neg_slope_broadcast : tensor<16x16xf32>
  %leaky_relu = "stablehlo.select"(%cond, %gn_out, %gn_out_neg) : (tensor<16x16xi1>, tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Element-wise sum: x + x = 2 * x
