  // Add bias: broadcast bias from [16] to [16x16] on dimension 1
  %fc_bias_bcast = "stablehlo.broadcast_in_dim"(%fc_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
