  %c0f = stablehlo.constant dense<0.0> : tensor<f32>
  %c1f = stablehlo.constant dense<1.0> : tensor<f32>

  // Create a 1D tensor [0,1,2,3,4,5,6,7]
  %iota = "stablehlo.iota"() {iota_dimension = 0 : i64} : () -> tensor<8xi32>

  // Broadcast idx from shape [4] to [4x8], broadcast idx along dim 1
