  // Broadcast iota from shape [8] to [4x8], broadcast iota along dim 0
  %iota_bcast = "stablehlo.broadcast_in_dim"(%iota) {broadcast_dimensions = array<i64: 1>} : (tensor<8xi32>) -> tensor<4x8xi32>

  // Compare idx_bcast == iota_bcast
  %eq = "stablehlo.compare"(%idx_bcast, %iota_bcast) {comparison_direction = #stablehlo<comparison_direction EQ>, compare_type = #stablehlo<comparison_type SIGNED>} : (tensor<4x8xi32>, tensor<4x8xi32>) -> tensor<4x8xi1>

  // Check idx in range 0 <= idx < 8
  %c0 = stablehlo.constant dense<0> : tensor<i32>
  %ge0 = "stablehlo.compare"(%idx, %c0) {comparison_direction = #stablehlo<comparison_direction GE>, compare_type = #stablehlo<comparison_type SIGNED>} : (tensor<4xi32>, tensor<i32>) -> tensor<4xi1>
