  // dimension_numbers = [b, f, 0, 1, 2]x[o, i, 0, 1, 2]->[b, f, 0, 1, 2]
  // batch = 6, input features = 3, output features = 16
  // kernel spatial dims = 3x3x3
  // input spatial dims = 16x7x7
