  // Broadcast bias to [6x16x14x5x5]
  %bias_broadcast2 = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1, 2, 3, 4>} : (tensor<16x1x1x1xf32>) -> tensor<6x16x14x5x5xf32>

  %multiplied = stablehlo.multiply %tanh, %bias_broadcast2 : tensor<6x16x14x5x5xf32>

  // Apply sigmoid (logistic)
  %sigmoid = stablehlo.logistic %multiplied : tensor<6x16x14x5x5xf32>

