// conv dimension_numbers attribute
// We define it here as a symbol attribute for reuse
// This is required by stablehlo.convolution op
// The attribute is a dictionary with key "dimension_numbers" and value a conv dimension numbers attribute
// The syntax is #stablehlo.conv<[input dims]x[kernel dims]->[output dims]>
//
// We define it as a global attribute for clarity
// The attribute is used in the convolution op above
// The attribute is not part of the function body but must be present in the module
// So we add it here after the function

// Note: MLIR stablehlo dialect expects conv dimension numbers attribute to be defined as a symbol attribute
// with the name #stablehlo.conv and the value as shown below

// The attribute is:
// input dims: [b, f, 0, 1, 2]
// kernel dims: [o, i, 0, 1, 2]
// output dims: [b, f, 0, 1, 2]

module attributes {
  #stablehlo.conv = {
    input_batch_dimension = 0 : i64,
    input_feature_dimension = 1 : i64,
    input_spatial_dimensions = [2, 3, 4] : array<i64>,
    kernel_output_feature_dimension = 0 : i64,
    kernel_input_feature_dimension = 1 : i64,
    kernel_spatial_dimensions = [2, 3, 4] : array<i64>,
    output_batch_dimension = 0 : i64,
    output_feature_dimension = 1 : i64,
    output_spatial_dimensions = [2, 3, 4] : array<i64>
