  // x + 0.044715 * x^3
  %x_plus = stablehlo.add %arg0, %x_cube_scaled : tensor<6x7xf32>

  // sqrt(2/pi) * (x + 0.044715 * x^3)
  %u = stablehlo.multiply %x_plus, %c1 : tensor<6x7xf32>

  // erf(u)
  %erf_u = chlo.erf %u : tensor<6x7xf32>

  // 1 + erf(u)
  %one_plus_erf = stablehlo.add %c3, %erf_u : tensor<6x7xf32>

  // 0.5 * x
  %half_x = stablehlo.multiply %arg0, %c2 : tensor<6x7xf32>

  // GELU output: 0.5 * x * (1 + erf(u))
  %gelu = stablehlo.multiply %half_x, %one_plus_erf : tensor<6x7xf32>

  return %gelu : tensor<6x7xf32>
}

