  // Instead, broadcast mean_div to [14,8,2,16,16] by first reshaping mean_div to [14,8,1,1,1]
  %mean_reshaped = stablehlo.reshape %mean_div : (tensor<14x8xf32>) -> tensor<14x8x1x1x1xf32>
  %mean_bcast_full = "stablehlo.broadcast_in_dim"(%mean_reshaped) {broadcast_dimensions = array<i64: 0, 1, 2, 3, 4>} : (tensor<14x8x1x1x1xf32>) -> tensor<14x8x2x16x16xf32>

  // Compute (x - mean)
  %x_centered = stablehlo.subtract %x_reshaped, %mean_bcast_full : tensor<14x8x2x16x16xf32>

  // Compute squared difference (x - mean)^2
  %x_centered_sq = stablehlo.multiply %x_centered, %x_centered : tensor<14x8x2x16x16xf32>

  // Compute variance: reduce mean of squared differences over dims [2,3,4]
  %init_var = stablehlo.constant dense<0.0> : tensor<f32>
  %var_sum = "stablehlo.reduce"(%x_centered_sq, %init_var) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2, 3, 4>} : (tensor<14x8x2x16x16xf32>, tensor<f32>) -> tensor<14x8xf32>

  // Divide by 512 to get variance
  %var = stablehlo.divide %var_sum, %c_512 : tensor<14x8xf32>

  // Add epsilon to variance
  %var_eps = stablehlo.add %var, %c_eps : tensor<14x8xf32>

  // Compute rsqrt(variance + epsilon)
  %inv_std = stablehlo.rsqrt %var_eps : tensor<14x8xf32>

  // Broadcast inv_std to input shape [14,8,2,16,16]
  %inv_std_reshaped = stablehlo.reshape %inv_std : (tensor<14x8xf32>) -> tensor<14x8x1x1x1xf32>
  %inv_std_bcast = "stablehlo.broadcast_in_dim"(%inv_std_reshaped) {broadcast_dimensions = array<i64: 0, 1, 2, 3, 4>} : (tensor<14x8x1x1x1xf32>) -> tensor<14x8x2x16x16xf32>

  // Normalize: (x - mean) * inv_std
  %x_norm = stablehlo.multiply %x_centered, %inv_std_bcast : tensor<14x8x2x16x16xf32>

  // Reshape normalized tensor back to [14,16,16,16]
  %x_norm_reshaped = stablehlo.reshape %x_norm : (tensor<14x8x2x16x16xf32>) -> tensor<14x16x16x16xf32>

  // Broadcast gn.weight and gn.bias from [16] to [14,16,16,16]
  %gn_weight_reshaped = stablehlo.reshape %gn_weight : (tensor<16xf32>) -> tensor<1x16x1x1xf32>
  %gn_weight_bcast = "stablehlo.broadcast_in_dim"(%gn_weight_reshaped) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<1x16x1x1xf32>) -> tensor<14x16x16x16xf32>
  %gn_bias_reshaped = stablehlo.reshape %gn_bias : (tensor<16xf32>) -> tensor<1x16x1x1xf32>
  %gn_bias_bcast = "stablehlo.broadcast_in_dim"(%gn_bias_reshaped) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<1x16x1x1xf32>) -> tensor<14x16x16x16xf32>

  // Apply scale and bias: x_norm * weight + bias
  %scaled = stablehlo.multiply %x_norm_reshaped, %gn_weight_bcast : tensor<14x16x16x16xf32>
  %shifted = stablehlo.add %scaled, %gn_bias_bcast : tensor<14x16x16x16xf32>

  // Return result
  return %shifted : tensor<14x16x

