func.func @main(%x: tensor<7x3xf32>) -> tensor<7x3xf32> {
  // Compute x^2 elementwise
  %x_squared = stablehlo.multiply %x, %x : tensor<7x3xf32>

  // Create zero constant for reduction init
  %zero = stablehlo.constant dense<0.0> : tensor<f32>

  // Reduce sum over dimension 1 (columns) to get sum of squares per row
  %sum_squares = "stablehlo.reduce"(%x_squared, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<7x3xf32>, tensor<f32>) -> tensor<7xf32>

  // Compute sqrt of sum_squares (L2 norm per row)
  %l2_norm = stablehlo.sqrt %sum_squares : tensor<7xf32>

  // Broadcast l2_norm from shape [7] to [7,3] along dimension 0
  %l2_norm_broadcast = "stablehlo.broadcast_in_dim"(%l2_norm) {broadcast_dimensions = array<i64: 0>} : (tensor<7xf32>) -> tensor<7x3xf32>

  // Divide x by broadcasted l2_norm to normalize rows
  %out = stablehlo.divide %x, %l2_norm_broadcast : tensor<7x3xf32>

  "stablehlo.return"(%out) : tensor<7x3xf32>
}

