func.func @main(%arg0: tensor<16x16xf32>, %arg1: tensor<16xf32>, %arg2: tensor<16xf32>, %arg3: tensor<16xf32>, %arg4: tensor<16x16xf32>) -> tensor<16x16xf32> {
  // %arg0 = gemm.weight (16x16)
  // %arg1 = gemm.bias (16)
  // %arg2 = group_norm.weight (16)
  // %arg3 = group_norm.bias (16)
  // %arg4 = input (16x16)

  // GEMM: x = input @ weight^T + bias
  // weight is (16x16), input is (16x16)
  // PyTorch Linear does x @ weight^T + bias, so we transpose weight
  %weight_t = "stablehlo.transpose"(%arg0) {permutation = array<i64: 1, 0>} : (tensor<16x16xf32>) -> tensor<16x16xf32>
  %gemm_dot = "stablehlo.dot_general"(%arg4, %weight_t) {dot_dimension_numbers = #stablehlo.dot<lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [1]>} : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
  // Broadcast bias (16) to (16x16) along dimension 1
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %gemm_out = stablehlo.add %gemm_dot, %bias_broadcast : tensor<16x16xf32>

  // GroupNorm with num_groups=16, out_features=16
  // Each group has 1 channel (16 channels / 16 groups)
  // Input shape: (N=16, C=16)
  // Reshape to (N=16, G=16, C_per_group=1)
  %reshape1 = stablehlo.reshape %gemm_out : (tensor<16x16xf32>) -> tensor<16x16x1xf32>

  // Compute mean over C_per_group dimension (dim=2)
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %mean = "stablehlo.reduce"(%reshape1, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2>} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>
  // Divide by C_per_group=1 (no-op)
  // mean shape: (16x16)

  // Compute variance: mean of (x - mean)^2 over dim=2
  // Broadcast mean to (16x16x1)
  %mean_broadcast = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<16x16xf32>) -> tensor<16x16x1xf32>
  %diff = stablehlo.subtract %reshape1, %mean_broadcast : tensor<16x16x1xf32>
  %sq_diff = stablehlo.multiply %diff, %diff : tensor<16x16x1xf32>
  %var = "stablehlo.reduce"(%sq_diff, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2>} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>
  // Divide by C_per_group=1 (no-op)
  // var shape: (16x16)

  // Compute inv_std = 1 / sqrt(var + eps)
  %eps = stablehlo.constant dense<1.0e-5> : tensor<f32>
  %var_eps = stablehlo.add %var, %eps : tensor<16x16xf32>
  %sqrt_var = stablehlo.sqrt %var_eps : tensor<16x16xf32>
  %inv_std = stablehlo.divide %zero_f32, %sqrt_var : tensor<16x16xf32> // 0 / sqrt_var = 0, wrong, fix below

  // Correct inv_std = 1 / sqrt_var
  // stablehlo.divide %one, %sqrt_var
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %inv_std = stablehlo.divide %one, %sqrt_var : tensor<16x16xf32>

  // Normalize: (x - mean) * inv_std
  %diff2 = stablehlo.subtract %gemm_out, %mean : tensor<16x16xf32>
  %normalized = stablehlo.multiply %diff2, %inv_std : tensor<16x16xf32>

  // Apply affine transform: normalized * weight + bias
  // group_norm.weight and bias are (16), broadcast to (16x16) along dim=1
  %weight_broadcast = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %bias_gn_broadcast = "stablehlo.broadcast_in_dim"(%arg3) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %scaled = stablehlo.multiply %normalized, %weight_broadcast : tensor<16x16xf32>
  %shifted = stablehlo.add %scaled, %bias_gn_broadcast : tensor<16x16xf32>

  // HardTanh clamp between -2.0 and 2.0
  %min_val = stablehlo.constant dense<-2.0> : tensor<f32>
  %max_val = stablehlo.constant dense<2.0> : tensor<f32>
  %min_broadcast = "stablehlo.broadcast_in_dim"(%min_val) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<16x16xf32>
  %max_broadcast = "stablehlo.broadcast_in_dim"(%max_val) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<16x16xf32>
  %clamp_min = stablehlo.maximum %shifted, %min_broadcast : tensor<16x16xf32>
  %clamp_max = stablehlo.minimum %clamp_min, %max_broadcast : tensor<16x16xf32>

  "stablehlo.return"(%clamp_max) : tensor<16x16xf32>
}

