  %sqrt_sum = stablehlo.sqrt %sum_squares : tensor<7xf32>
  %sqrt_sum_broadcast = "stablehlo.broadcast_in_dim"(%sqrt_sum) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<7xf32>) -> tensor<7x3xf32>
  %out = stablehlo.divide %x, %sqrt_sum_broadcast : tensor<7x3xf32>
  return %out : tensor<7x3xf32>
}

func.func @main(%arg0: tensor<16x16xf32>, %arg1: tensor<16xf32>, %arg2: tensor<16xf32>, %arg3: tensor<16xf32>, %arg4: tensor<16x16xf32>) -> tensor<16x16xf32> {
  // %arg4: input tensor (batch_size=16, in_features=16)
  // %arg0: gemm.weight (out_features=16, in_features=16)
  // %arg1: gemm.bias (out_features=16)
  // %arg2: group_norm.weight (out_features=16)
  // %arg3: group_norm.bias (out_features=16)

  // GEMM: x = input @ weight^T + bias
  // dot_general with contracting dims: input (16x16), weight (16x16)
  // We want input (16x16) dot weight^T (16x16) -> (16x16)
  // So transpose weight to get (16x16) -> (16x16) (actually same shape, but transpose swaps dims)
  %weight_t = "stablehlo.transpose"(%arg0) {permutation = array<i64: 1, 0>} : (tensor<16x16xf32>) -> tensor<16x16xf32>
  %dot = "stablehlo.dot_general"(%arg4, %weight_t) {dot_dimension_numbers = #stablehlo.dot<lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [1]>} : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
  %x1 = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %x2 = stablehlo.add %dot, %x1 : tensor<16x16xf32>

  // GroupNorm:
  // num_groups=16, out_features=16, so group size = 1 (16/16=1)
  // Reshape x2 (16x16) -> (16,16,1) to group channels
  %x3 = stablehlo.reshape %x2 : (tensor<16x16xf32>) -> tensor<16x16x1xf32>

  // Compute mean over group dimension (dim=2)
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %init_mean = stablehlo.broadcast_in_dim %zero_f32 {broadcast_dimensions = array<i64: 0} : (tensor<f32>) -> tensor<16x16xf32>
  %mean = "stablehlo.reduce"(%x3, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>

  // mean = sum / group_size (1)
  // group_size = 1, so mean unchanged
  // Reshape mean to (16x16x1) for broadcasting
  %mean_reshaped = stablehlo.reshape %mean : (tensor<16x16xf32>) -> tensor<16x16x1xf32>

  // Compute variance: var = mean((x - mean)^2)
  %x_minus_mean = stablehlo.subtract %x3, %mean_reshaped : tensor<16x16x1xf32>
  %sq = stablehlo.multiply %x_minus_mean, %x_minus_mean : tensor<16x16x1xf32>
  %var_sum = "stablehlo.reduce"(%sq, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>

  // var = var_sum / group_size (1)
  // group_size=1, so var = var_sum unchanged
  %var_reshaped = stablehlo.reshape %var_sum : (tensor<16x16xf32>) -> tensor<16x16x1xf32>

  // epsilon constant for numerical stability
  %epsilon = stablehlo.constant dense<1.000000e-05> : tensor<f32>

  // var + epsilon
  %var_eps = stablehlo.add %var_reshaped, %epsilon : tensor<16x16x1xf32>

  // inv_std = rsqrt(var + epsilon)
  %inv_std = stablehlo.rsqrt %var_eps : tensor<16x16x1xf32>

  // Normalize: (x - mean) * inv_std
  %x_norm = stablehlo.multiply %x_minus_mean, %inv_std : tensor<16x16x1xf32>

  // Reshape normalized to (16x16)
  %x_norm_2d = stablehlo.reshape %x_norm : (tensor<16x16x1xf32>) -> tensor<16x16xf32>

  // Apply group_norm.weight and group_norm.bias (both shape 16)
  // Broadcast weight and bias to (16x16)
  %weight_broadcast = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg3) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>

  // scale = x_norm * weight
  %scaled = stablehlo.multiply %x_norm_2d, %weight_broadcast : tensor<16x16xf32>
  // shift = scaled + bias
  %shifted = stablehlo.add %scaled, %bias_broadcast : tensor<16x16xf32>

  // HardTanh clamp between -2.0 and 2.0
  %min_val = stablehlo.constant dense<-2.0> : tensor<f32>
  %max_val = stablehlo.constant dense<2.0> : tensor<f32>
  %min_broadcast = "stablehlo.broadcast_in_dim"(%min_val) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<16x16xf32>
