  %gemm = "stablehlo.dot_general"(%arg4, %weight_t) {dot_dimension_numbers = #stablehlo.dot<lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [1]>} : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Broadcast bias (16) to (16x16) on dimension 1
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %gemm_bias = stablehlo.add %gemm, %bias_broadcast : tensor<16x16xf32>

  // GroupNorm:
  // num_groups = 16, out_features = 16, so each group has 1 channel (C=16, G=16, C/G=1)
  // Input shape: (N=16, C=16)
  // GroupNorm reshapes to (N, G, C/G) = (16,16,1)
  // Compute mean and variance over axis=2 (the group channels)
  // Then normalize: (x - mean) / sqrt(var + eps)
  // Then scale and shift by weight and bias (both shape (16))
  // weight and bias are per channel, so broadcast to (N,C)
  // eps = 1e-5 (typical default)

  // Reshape gemm_bias (16x16) -> (16x16x1)
  %gemm_bias_reshaped = stablehlo.reshape %gemm_bias : (tensor<16x16xf32>) -> tensor<16x16x1xf32>

  // Compute mean over axis=2 (last axis)
  %init_zero = stablehlo.constant dense<0.0> : tensor<f32>
  %mean = "stablehlo.reduce"(%gemm_bias_reshaped, %init_zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2>} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>

  // Divide mean by group size (1)
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %mean_div = stablehlo.divide %mean, %one : tensor<16x16xf32>

  // Broadcast mean_div back to (16x16x1)
  %mean_broadcast = "stablehlo.broadcast_in_dim"(%mean_div) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<16x16xf32>) -> tensor<16x16x1xf32>

  // Compute variance: mean of (x - mean)^2 over axis=2
  %diff = stablehlo.subtract %gemm_bias_reshaped, %mean_broadcast : tensor<16x16x1xf32>
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<16x16x1xf32>
  %init_zero_var = stablehlo.constant dense<0.0> : tensor<f32>
  %var = "stablehlo.reduce"(%diff_sq, %init_zero_var) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2>} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>

  // Divide variance by group size (1)
  %var_div = stablehlo.divide %var, %one : tensor<16x16xf32>

  // Broadcast var_div back to (16x16x1)
  %var_broadcast = "stablehlo.broadcast_in_dim"(%var_div) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<16x16xf32>) -> tensor<16x16x1xf32>

  // eps constant
  %eps = stablehlo.constant dense<0.00001> : tensor<f32>

  // var + eps
  %var_eps = stablehlo.add %var_broadcast, %eps : tensor<16x16x1xf32>

  // sqrt(var + eps)
  %stddev = stablehlo.sqrt %var_eps : tensor<16x16x1xf32>

  // Normalize: (x - mean) / stddev
  %norm = stablehlo.divide %diff, %stddev : tensor<16x16x1xf32>

  // Reshape norm back to (16x16)
  %norm_reshaped = stablehlo.reshape %norm : (tensor<16x16x1xf32>) -> tensor<16x16xf32>

  // Apply group_norm.weight and group_norm.bias (both shape 16)
  // Broadcast weight and bias to (16x16) on dimension 1
  %weight_broadcast = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %bias_broadcast_gn = "stablehlo.broadcast_in_dim"(%arg3) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>

  // scale * norm + bias
  %scaled = stablehlo.multiply %norm_reshaped, %weight_broadcast : tensor<16x16xf32>
  %group_norm_out = stablehlo.add %scaled, %bias_broadcast_gn : tensor<16x16xf32>

  // HardTanh clamp between -2.0 and 2.0
  %min_val = stablehlo.constant dense<-2.0> : tensor<f32>
  %max_val = stablehlo.constant dense<2.0> : tensor<f32>

  // Broadcast min and max to (16x16)
  %min_broadcast = "stablehlo.broadcast_in_dim"(%min_val) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<16x16xf32>
  %max_broadcast = "stablehlo.broadcast_in_dim"(%max_val) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<16x16xf32>

  %clamp_min = stablehlo.maximum %group_norm_out, %min_broadcast : tensor<16x16xf32>
  %clamp_max = stablehlo.minimum %clamp_min, %max_broadcast : tensor<16x16xf32>

  "stablehlo.return"(%clamp_max) : tensor<16x16xf32>
}

func.func @main(%arg0: tensor<16x16xf32>, %arg1: tensor<16xf32>, %arg2: tensor<16xf32>, %arg3: tensor<16xf32>, %arg4: tensor<16x16xf32>) -> tensor<16x16xf32> {
