  %gemm_out = stablehlo.add %dot, %bias_broadcast : tensor<16x16xf32>

  // GroupNorm:
  // num_groups = 16, out_features = 16, so each group has 1 channel (C=16, G=16, channels_per_group=1)
  // Input shape: [N=16, C=16]
  // Reshape to [N=16, G=16, channels_per_group=1]
