  // Broadcast group_norm.weight and group_norm.bias from [16] to [16x16x1]
  %weight_broadcast = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %weight_broadcast_3d = "stablehlo.broadcast_in_dim"(%weight_broadcast) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<16x16xf32>) -> tensor<16x16x1xf32>
  %bias_broadcast_gn = "stablehlo.broadcast_in_dim"(%arg3) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %bias_broadcast_3d = "stablehlo.broadcast_in_dim"(%bias_broadcast_gn) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<16x16xf32>) -> tensor<16x16x1xf32>

  // Normalize: (x - mean) * inv_std
  %x_norm = stablehlo.multiply %x_centered, %inv_std : tensor<16x16x1xf32>

  // Scale and shift: x_norm * weight + bias
  %scaled = stablehlo.multiply %x_norm, %weight_broadcast_3d : tensor<16x16x1xf32>
