func.func @main(%arg0: tensor<6x6xf32>, %arg1: tensor<6x6xf32>) -> tensor<f32> {
  // Compute diff = predictions - targets
  %diff = stablehlo.subtract %arg0, %arg1 : tensor<6x6xf32>

  // abs_diff = abs(diff)
  %abs_diff = stablehlo.abs %diff : tensor<6x6xf32>

  // constant 1.0 for comparison
  %c1 = stablehlo.constant dense<1.0> : tensor<f32>
  // broadcast 1.0 to shape 6x6
  %c1_bcast = "stablehlo.broadcast_in_dim"(%c1) {broadcast_dimensions = array<i64:  }> : (tensor<f32>) -> tensor<6x6xf32>

  // compare abs_diff < 1.0
  %cmp = "stablehlo.compare"(%abs_diff, %c1_bcast) {comparison_direction = #stablehlo<comparison_direction LT>, compare_type = #stablehlo<comparison_type FLOAT>} : (tensor<6x6xf32>, tensor<6x6xf32>) -> tensor<6x6xi1>

  // For abs_diff < 1: 0.5 * diff^2
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<6x6xf32>
  %c05 = stablehlo.constant dense<0.5> : tensor<f32>
  %c05_bcast = "stablehlo.broadcast_in_dim"(%c05) {broadcast_dimensions = array<i64:  }> : (tensor<f32>) -> tensor<6x6xf32>
  %loss1 = stablehlo.multiply %c05_bcast, %diff_sq : tensor<6x6xf32>

  // For abs_diff >= 1: abs_diff - 0.5
  %c05_bcast_neg = %c05_bcast  // reuse 0.5 broadcast
  %loss2 = stablehlo.subtract %abs_diff, %c05_bcast_neg : tensor<6x6xf32>

  // select loss = where cmp true loss1 else loss2
  %loss = "stablehlo.select"(%cmp, %loss1, %loss2) : (tensor<6x6xi1>, tensor<6x6xf32>, tensor<6x6xf32>) -> tensor<6x6xf32>

  // sum all elements of loss
  %init = stablehlo.constant dense<0.0> : tensor<f32>
  %sum = "stablehlo.reduce"(%loss, %init) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0, 1>} : (tensor<6x6xf32>, tensor<f32>) -> tensor<f32>

  // normalize by number of elements (36)
  %c36 = stablehlo.constant dense<36.0> : tensor<f32>
  %result = stablehlo.divide %sum, %c36 : tensor<f32>

  return %result : tensor<f32>
}

