  %c0_5_bcast_2 = %c0_5_bcast  // reuse broadcasted 0.5
  %loss2 = stablehlo.subtract %abs_diff, %c0_5_bcast_2 : tensor<6x6xf32>

  // Select loss1 where cond true else loss2
  %loss = "stablehlo.select"(%cond, %loss1, %loss2) : (tensor<6x6xi1>, tensor<6x6xf32>, tensor<6x6xf32>) -> tensor<6x6xf32>

  // Sum all elements of loss tensor to get scalar output
  %init = stablehlo.constant dense<0.0> : tensor<f32>
  %sum = "stablehlo.reduce"(%loss, %init) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0, 1>} : (tensor<6x6xf32>, tensor<f32>) -> tensor<f32>

  func.return %sum : tensor<f32>
}

func.func @main(%bias: tensor<7x1x1xf32>, %conv_weight: tensor<7x8x3x3xf32>, %conv_bias: tensor<7xf32>, %input: tensor<6x8x8x8xf32>) -> tensor<6x7x1x1xf32> {
