  // Broadcast bias from [7x1x1] to [6x7x6x6]
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%bias) {broadcast_dimensions = array<i64: 1, 2, 3>} : (tensor<7x1x1xf32>) -> tensor<6x7x6x6xf32>
  %biased = stablehlo.add %scaled, %bias_broadcast : tensor<6x7x6x6xf32>

