  // Window dimensions: [1, 1, 4, 4] (batch and channel dims window=1)
  // Window strides: [1, 1, 4, 4]
  // Padding: 0
  %init = stablehlo.constant dense<-3.4028235e+38> : tensor<f32>  // -inf for max pooling init
  %maxpool = "stablehlo.reduce_window"(%biased, %init) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %max = stablehlo.maximum %a, %b : tensor<f32>
