}

func.func @main(%arg0: tensor<7x1x1xf32>, %arg1: tensor<7x8x3x3xf32>, %arg2: tensor<7xf32>, %arg3: tensor<6x8x8x8xf32>) -> tensor<6x7x1x1xf32> {
  // %arg0 = bias (7x1x1)
  // %arg1 = conv.weight (7x8x3x3)
  // %arg2 = conv.bias (7)
  // %arg3 = input (6x8x8x8)

  // Step 1: Convolution
  // dimension_numbers = [b, f, h, w] x [o, i, kh, kw] -> [b, f, h, w]
  // Here: input shape: [6,8,8,8], kernel shape: [7,8,3,3]
  // Output shape: [6,7,6,6] because:
  // output_height = floor((0 + (8-1)*1 + 1 + 0 - ((3-1)*1 + 1))/1) + 1 = floor((7 + 1 - 3)/1) + 1 = floor(5) + 1 = 6
