  %padding = stablehlo.constant dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>
  %window_strides = array<i64: 1, 1>
  %lhs_dilation = array<i64: 1, 1>
  %rhs_dilation = array<i64: 1, 1>
  %feature_group_count = 1 : i64
  %batch_group_count = 1 : i64
  %conv = "stablehlo.convolution"(%arg3, %arg1) {
    window_strides = %window_strides,
    padding = %padding,
    lhs_dilation = %lhs_dilation,
    rhs_dilation = %rhs_dilation,
    dimension_numbers = #stablehlo.conv<[b, f, 2, 3]x[o, i, 2, 3]->[b, f, 2, 3]>,
    feature_group_count = %feature_group_count,
    batch_group_count = %batch_group_count
  } : (tensor<6x8x8x8xf32>, tensor<7x8x3x3xf32>) -> tensor<6x7x6x6xf32>

  // Step 2: Add conv.bias (7) to conv output (6x7x6x6)
  // Broadcast conv.bias from [7] to [6x7x6x6]
  %conv_bias_broadcast = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7x6x6xf32>
  %conv_plus_bias = stablehlo.add %conv, %conv_bias_broadcast : tensor<6x7x6x6xf32>

  // Step 3: Apply tanh activation
  %tanh = stablehlo.tanh %conv_plus_bias : tensor<6x7x6x6xf32>

  // Step 4: Multiply by scaling factor 2.0
  %scale = stablehlo.constant dense<2.0> : tensor<f32>
  // Broadcast scale scalar to tensor<6x7x6x6xf32>
  %scale_broadcast = "stablehlo.broadcast_in_dim"(%scale) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7x6x6xf32>
  %scaled = stablehlo.multiply %tanh, %scale_broadcast : tensor<6x7x6x6xf32>

