func.func @main(%arg0: tensor<7x1x1xf32>, %arg1: tensor<7x8x3x3xf32>, %arg2: tensor<7xf32>, %arg3: tensor<6x8x8x8xf32>) -> tensor<6x7x1x1xf32> {
  // %arg0 = bias (7x1x1)
  // %arg1 = conv.weight (7x8x3x3)
  // %arg2 = conv.bias (7)
  // %arg3 = input (6x8x8x8)

  // Convolution:
  // dimension_numbers = [b, f, h, w] x [o, i, kh, kw] -> [b, f, h, w]
  // Here b=batch, f=feature, h=height, w=width
  // Input shape: 6x8x8x8 (b=6, f=8, h=8, w=8)
  // Weight shape: 7x8x3x3 (o=7, i=8, kh=3, kw=3)
  // Output shape: 6x7x6x6 (b=6, f=7, h=6, w=6) because:
  // output_h = floor((8 + 0 + 0 - 3)/1) + 1 = 6
  // output_w = floor((8 + 0 + 0 - 3)/1) + 1 = 6

  %zero = stablehlo.constant dense<0> : tensor<i64>
  %one = stablehlo.constant dense<1> : tensor<i64>

  %conv = "stablehlo.convolution"(%arg3, %arg1) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 1, 1>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 2, 3]x[o, i, 2, 3]->[b, f, 2, 3]>,
    feature_group_count = 1 : i64,
