  %tanh = stablehlo.tanh %conv_plus_bias : tensor<6x7x6x6xf32>

  // Scaling factor = 2.0 (constant scalar)
  %scale = stablehlo.constant dense<2.0> : tensor<f32>
  // Broadcast scale to tensor<6x7x6x6xf32>
  %scale_broadcast = "stablehlo.broadcast_in_dim"(%scale) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7x6x6xf32>
  %scaled = stablehlo.multiply %tanh, %scale_broadcast : tensor<6x7x6x6xf32>

  // Add bias (7x1x1) to scaled output (6x7x6x6)
  // Broadcast bias from [7x1x1] to [6x7x6x6]
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg0) {broadcast_dimensions = array<i64: 1, 2, 3>} : (tensor<7x1x1xf32>) -> tensor<6x7x6x6xf32>
  %biased = stablehlo.add %scaled, %bias_broadcast : tensor<6x7x6x6xf32>

