  // So output shape: 6x7x2x2

  // Initial value for max pooling: -inf
  %neg_inf = stablehlo.constant dense<0xFF800000> : tensor<f32>

  %maxpool = "stablehlo.reduce_window"(%biased, %neg_inf) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %max = stablehlo.maximum %a, %b : tensor<f32>
      stablehlo.return %max : tensor<f32>
  }) {
    window_dimensions = array<i64: 1, 1, 4, 4>,
    window_strides = array<i64: 1, 1, 4, 4>,
    padding = dense<[[0, 0], [0, 0], [0, 0], [0, 0]]> : tensor<4x2xi64>
