    window_strides = array<i64: 1, 1, 2, 2>,
    padding = dense<[[0, 0], [0, 0], [0, 0], [0, 0]]> : tensor<4x2xi64>
  } : (tensor<6x7x2x2xf32>, tensor<f32>) -> tensor<6x7x1x1xf32>

  return %maxpool2 : tensor<6x7x1x1xf32>
}

func.func @main(%arg0: tensor<6x6xf32>, %arg1: tensor<6x6xf32>) -> tensor<f32> {
  // Compute difference: diff = predictions - targets
  %diff = stablehlo.subtract %arg0, %arg1 : tensor<6x6xf32>

  // Compute absolute difference: abs_diff = abs(diff)
  %abs_diff = stablehlo.abs %diff : tensor<6x6xf32>

  // Constant 1.0 for comparison
  %c1 = stablehlo.constant dense<1.000000e+00> : tensor<f32>
  // Broadcast 1.0 to shape 6x6
  %c1_broadcast = "stablehlo.broadcast_in_dim"(%c1) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6xf32>

  // Compare abs_diff < 1.0
  %cond = "stablehlo.compare"(%abs_diff, %c1_broadcast) {comparison_direction = #stablehlo<comparison_direction LT>, compare_type = #stablehlo<comparison_type FLOAT>} : (tensor<6x6xf32>, tensor<6x6xf32>) -> tensor<6x6xi1>

  // Compute 0.5 * diff^2
  %diff_squared = stablehlo.multiply %diff, %diff : tensor<6x6xf32>
  %c0_5 = stablehlo.constant dense<5.000000e-01> : tensor<f32>
  %c0_5_broadcast = "stablehlo.broadcast_in_dim"(%c0_5) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6xf32>
  %half_diff_squared = stablehlo.multiply %c0_5_broadcast, %diff_squared : tensor<6x6xf32>

  // Compute abs_diff - 0.5
  %c0_5_broadcast_2 = %c0_5_broadcast : tensor<6x6xf32>  // reuse broadcasted 0.5
  %abs_diff_minus_half = stablehlo.subtract %abs_diff, %c0_5_broadcast_2 : tensor<6x6xf32>

  // Select: if abs_diff < 1 then 0.5*diff^2 else abs_diff - 0.5
  %smooth_l1 = "stablehlo.select"(%cond, %half_diff_squared, %abs_diff_minus_half) : (tensor<6x6xi1>, tensor<6x6xf32>, tensor<6x6xf32>) -> tensor<6x6xf32>

  // Sum all elements to get scalar loss
  %c0 = stablehlo.constant dense<0.000000e+00> : tensor<f32>
  %loss = "stablehlo.reduce"(%smooth_l1, %c0) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0, 1>} : (tensor<6x6xf32>, tensor<f32>) -> tensor<f32>

  return %loss : tensor<f32>
}

func.func @main(%arg0: tensor<6x6xf32>, %arg1: tensor<6x6xf32>) -> tensor<f32> {
  // Compute difference: diff = predictions - targets
  %diff = stablehlo.subtract %arg0, %arg1 : tensor<6x6xf32>

  // Compute absolute difference: abs_diff = abs(diff)
  %abs_diff = stablehlo.abs %diff : tensor<6x6xf32>

  // Constant 1.0 for comparison
  %c1 = stablehlo.constant dense<1.000000e+00> : tensor<f32>
  // Broadcast constant 1.0 to shape 6x6
  %c1_broadcast = "stablehlo.broadcast_in_dim"(%c1) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6xf32>

  // Compare abs_diff < 1.0
  %cond = "stablehlo.compare"(%abs_diff, %c1_broadcast) {comparison_direction = #stablehlo<comparison_direction LT>, compare_type = #stablehlo<comparison_type FLOAT>} : (tensor<6x6xf32>, tensor<6x6xf32>) -> tensor<6x6xi1>

  // Compute quadratic term: 0.5 * diff^2
  %diff_squared = stablehlo.multiply %diff, %diff : tensor<6x6xf32>
