  %loss_per_element = "stablehlo.select"(%cond, %quadratic, %linear) : (tensor<6x6xi1>, tensor<6x6xf32>, tensor<6x6xf32>) -> tensor<6x6xf32>

  // Sum all elements: reduce over dimensions 0 and 1
  %init = stablehlo.constant dense<0.000000e+00> : tensor<f32>
  %sum = "stablehlo.reduce"(%loss_per_element, %init) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
