  %x3 = stablehlo.multiply %x2, %scale_bcast : tensor<6x7xf32>

  // BatchNorm1d forward training mode:
  // Compute mean over batch dimension (dim 0)
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %sum = "stablehlo.reduce"(%x3, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>

  // mean = sum / 6
  %six = stablehlo.constant dense<6.0> : tensor<f32>
  %six_bcast = "stablehlo.broadcast_in_dim"(%six) {broadcast_dimensions = array<i64:>} : (tensor<f32>) -> tensor<7xf32>
  %mean = stablehlo.divide %sum, %six_bcast : tensor<7xf32>

  // Compute variance: mean of (x - mean)^2 over batch dim 0
  // broadcast mean to (6x7)
  %mean_bcast = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %diff = stablehlo.subtract %x3, %mean_bcast : tensor<6x7xf32>
  %sq = stablehlo.multiply %diff, %diff : tensor<6x7xf32>
  %var_sum = "stablehlo.reduce"(%sq, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>
  %var = stablehlo.divide %var_sum, %six_bcast : tensor<7xf32>

  // Compute invstd = 1 / sqrt(var + eps)
  %eps = stablehlo.constant dense<1.000000e-05> : tensor<f32>
  %var_eps = stablehlo.add %var, %eps : tensor<7xf32>
  %sqrt_var_eps = stablehlo.sqrt %var_eps : tensor<7xf32>
  %invstd = stablehlo.divide %six_bcast, %sqrt_var_eps : tensor<7xf32>  // 6.0 / sqrt(...) to get invstd * N for batchnorm formula

  // Actually, batchnorm formula is:
  // y = bn_weight * (x - mean) * invstd + bn_bias
  // So we need invstd = 1 / sqrt(var + eps)
  // Let's compute invstd = 1 / sqrt(var + eps)
  %invstd = stablehlo.divide %six, %sqrt_var_eps : tensor<7xf32> // This is incorrect, fix below

  // Correction: invstd = 1 / sqrt(var + eps)
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %invstd = stablehlo.divide %one, %sqrt_var_eps : tensor<7xf32>

  // Broadcast invstd, bn_weight, bn_bias to (6x7)
  %invstd_bcast = "stablehlo.broadcast_in_dim"(%invstd) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %bn_weight_bcast = "stablehlo.broadcast_in_dim"(%bn_weight) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %bn_bias_bcast = "stablehlo.broadcast_in_dim"(%bn_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>

  // normalized = (x3 - mean) * invstd
  %norm = stablehlo.multiply %diff, %invstd_bcast : tensor<6x7xf32>

  // scaled = norm * bn_weight
  %scaled = stablehlo.multiply %norm, %bn_weight_bcast : tensor<6x7xf32>

  // shifted = scaled + bn_bias
  %out = stablehlo.add %scaled, %bn_bias_bcast : tensor<6x7xf32>

  return %out : tensor<6x7xf32>
}

