func.func @main(%scale: tensor<7xf32>, %weight: tensor<7x7xf32>, %bias: tensor<7xf32>, %bn_weight: tensor<7xf32>, %bn_bias: tensor<7xf32>, %input: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // %x1 = gemm: input @ input * weight^T
  // weight shape: [7,7], input shape: [6,7]
  // We want to do input @ weight^T to get [6,7]
  // So transpose weight from [7,7] to [7,7] with permutation [1,0] (swap dims)
  %weight_t = "stablehlo.transpose"(%weight) {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>
  %x1 = "stablehlo.dot_general"(%input, %weight_t) {dot_dimension_numbers = #stablehlo.dot<lhs_batching_dimensions = [], rhs_batching_dimensions = [], lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>} : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

  // Add bias: broadcast bias [7] to [6x7]
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%bias) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %x2 = stablehlo.add %x1, %bias_broadcast : tensor<6x7xf32>

  // Multiply by scale: broadcast scale [7] to [6x7]
  %scale_broadcast = "stablehlo.broadcast_in_dim"(%scale) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %x3 = stablehlo.multiply %x2, %scale_broadcast : tensor<6x7xf32>

  // BatchNorm1d forward (training mode):
  // Compute mean over batch dimension (dim=0)
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %init_mean = "stablehlo.broadcast_in_dim"(%zero_f32) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<7xf32>
  %mean = "stablehlo.reduce"(%x3, %init_mean) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<7xf32>) -> tensor<7xf32>

  // Compute mean / batch_size (6)
  %batch_size_const = stablehlo.constant dense<6.0> : tensor<f32>
  %mean_div = stablehlo.divide %mean, %batch_size_const : tensor<7xf32>

  // Compute variance: mean of squared differences
  // First compute (x3 - mean) with broadcasting mean [7] to [6x7]
  %mean_broadcast = "stablehlo.broadcast_in_dim"(%mean_div) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %diff = stablehlo.subtract %x3, %mean_broadcast : tensor<6x7xf32>
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<6x7xf32>

  %zero_f32_var = stablehlo.constant dense<0.0> : tensor<f32>
  %init_var = "stablehlo.broadcast_in_dim"(%zero_f32_var) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<7xf32>
  %var = "stablehlo.reduce"(%diff_sq, %init_var) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<7xf32>) -> tensor<7xf32>

  // variance = var / batch_size
  %var_div = stablehlo.divide %var, %batch_size_const : tensor<7xf32>

  // Add eps=1e-5 to variance
  %eps = stablehlo.constant dense<0.00001> : tensor<f32>
  %eps_broadcast = "stablehlo.broadcast_in_dim"(%eps) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<7xf32>
  %var_eps = stablehlo.add %var_div, %eps_broadcast : tensor<7xf32>

  // Compute rsqrt(var + eps)
  %inv_std = stablehlo.rsqrt %var_eps : tensor<7xf32>

  // Normalize: (x3 - mean) * inv_std
  %inv_std_broadcast = "stablehlo.broadcast_in_dim"(%inv_std) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %x_norm = stablehlo.multiply %diff, %inv_std_broadcast : tensor<6x7xf32>

  // Apply bn.weight (gamma) and bn.bias (beta)
  %bn_weight_broadcast = "stablehlo.broadcast_in_dim"(%bn_weight) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %bn_bias_broadcast = "stablehlo.broadcast_in_dim"(%bn_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %x_scaled = stablehlo.multiply %x_norm, %bn_weight_broadcast : tensor<6x7xf32>
  %x_bn = stablehlo.add %x_scaled, %bn_bias_broadcast : tensor<6x7xf32>

  return %x_bn : tensor<6x7xf32>
}

func.func @main(%x: tensor<5x8xf32>, %i: tensor<i32>) -> tensor<2x8xf32> {
  %c0 = stablehlo.constant dense<0> : tensor<i32>
