  %c2 = stablehlo.constant dense<2> : tensor<i32>

  // Clamp i to be at least 0: max(i, 0)
  %i0 = "stablehlo.maximum"(%i, %c0) : (tensor<i32>, tensor<i32>) -> tensor<i32>
  // Clamp result to be at most 3: min(max(i,0), 3)
  %s = "stablehlo.minimum"(%i0, %c3) : (tensor<i32>, tensor<i32>) -> tensor<i32>

  // dynamic_slice requires rank-0 tensors for start indices
  %s0 = "stablehlo.reshape"(%s) {new_shape = array<i64: >} : (tensor<i32>) -> tensor<>  // scalar tensor
  %c0s = stablehlo.constant dense<0> : tensor<i32>
  %c0s_reshaped = "stablehlo.reshape"(%c0s) {new_shape = array<i64: >} : (tensor<i32>) -> tensor<>  // scalar tensor

  // Slice sizes: 2 rows, 8 columns
  %r = "stablehlo.dynamic_slice"(%x, %s0, %c0s_reshaped) {slice_sizes = array<i64: 2, 8>} : (tensor<5x8xf32>, tensor<>, tensor<>) -> tensor<2x8xf32>
  return %r : tensor<2x8xf32>
}

func.func @main(%scale: tensor<7xf32>, %weight: tensor<7x7xf32>, %bias: tensor<7xf32>, %bn_weight: tensor<7xf32>, %bn_bias: tensor<7xf32>, %input: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // %input: [6,7], %weight: [7,7]
  // Compute gemm: x @ weight^T + bias
  // dot_general with lhs_batching_dimensions=[0], rhs_contracting_dimensions=[1], lhs_contracting_dimensions=[1], rhs_batching_dimensions=[0]
  // But weight shape is [7,7], input [6,7], so we want to do input [6,7] x weight^T [7,7] -> [6,7]
  // So we transpose weight to [7,7] (actually weight is square, but we must transpose to get correct contraction)
  // Actually, weight is [7,7], input [6,7], so dot_general with contracting dims input:1, weight:1, no batching dims
  // But batch size is 6, so no batching dims, just normal matmul: input [6,7] x weight^T [7,7] -> [6,7]
  // So we transpose weight to get weight^T
  %weight_t = "stablehlo.transpose"(%weight) {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>
  %gemm = "stablehlo.dot_general"(%input, %weight_t) {dot_dimension_numbers = #stablehlo.dot<lhs_batching_dimensions = [], rhs_batching_dimensions = [], lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>} : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>
  // Add bias: broadcast bias [7] to [6,7]
  %bias_bcast = "stablehlo.broadcast_in_dim"(%bias) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %gemm_bias = stablehlo.add %gemm, %bias_bcast : tensor<6x7xf32>
  // Multiply by scale: broadcast scale [7] to [6,7]
  %scale_bcast = "stablehlo.broadcast_in_dim"(%scale) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %scaled = stablehlo.multiply %gemm_bias, %scale_bcast : tensor<6x7xf32>
  // BatchNorm1d forward (training mode):
  // Compute mean over batch dimension (dim 0)
  %zero = stablehlo.constant dense<0.000000e+00> : tensor<f32>
  %mean = "stablehlo.reduce"(%scaled, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>): 
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>
  // mean = sum / 6
  %six = stablehlo.constant dense<6.000000e+00> : tensor<f32>
  %six_bcast = "stablehlo.broadcast_in_dim"(%six) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<f32>
  %mean_div = stablehlo.divide %mean, %six : tensor<7xf32>
  // Broadcast mean to [6,7]
  %mean_bcast = "stablehlo.broadcast_in_dim"(%mean_div) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  // Compute variance: mean of (x - mean)^2 over batch dim 0
  %diff = stablehlo.subtract %scaled, %mean_bcast : tensor<6x7xf32>
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<6x7xf32>
  %var_sum = "stablehlo.reduce"(%diff_sq, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>): 
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>
  %var = stablehlo.divide %var_sum, %six : tensor<7xf32>
  // Broadcast var to [6,7]
  %var_bcast = "stablehlo.broadcast_in_dim"(%var) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  // eps constant
  %eps = stablehlo.constant dense<1.000000e-05> : tensor<f32>
  %eps_bcast = "stablehlo.broadcast_in_dim"(%eps) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<f32>
  // Add eps to var
  %var_eps = stablehlo.add %var, %eps : tensor<7xf32>
  // sqrt(var + eps)
  %stddev = stablehlo.sqrt %var_eps : tensor<7xf32>
  // Broadcast stddev to [6,7]
  %stddev_bcast = "stablehlo.broadcast_in_dim"(%stddev) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  // Normalize: (x - mean) / stddev
  %norm = stablehlo.divide %diff, %stddev_bcast : tensor<6x7xf32>
  // Apply bn.weight and bn.bias: broadcast bn_weight and bn_bias to [6,7]
  %bn_weight_bcast = "stablehlo.broadcast_in_dim"(%bn_weight) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %bn_bias_bcast = "stablehlo.broadcast_in_dim"(%bn_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %scaled_norm = stablehlo.multiply %norm, %bn_weight_bcast : tensor<6x7xf32>
  %out = stablehlo.add %scaled_norm, %bn_bias_bcast : tensor<6x7xf32>
  return %out : tensor<6x7xf32>
}

