  %slice_sizes = stablehlo.constant dense<[1,1]> : tensor<2xi64>
  %offset_dims = stablehlo.constant dense<> : tensor<0xi64>
  %collapsed_slice_dims = stablehlo.constant dense<[0,1]> : tensor<2xi64>
  %start_index_map = stablehlo.constant dense<[0,1]> : tensor<2xi64>
  %index_vector_dim = stablehlo.constant dense<1> : tensor<i64>

