  // Broadcast log_sum_exp to shape [6] (already shape [6])
  // Subtract log_sum_exp from gathered logits
  %log_probs = stablehlo.subtract %gather, %log_sum_exp : tensor<6xf32>

  // Compute negative log likelihood = -log_probs
  %neg_log_probs = stablehlo.negate %log_probs : tensor<6xf32>

