      stablehlo.return %sum : tensor<f32>
  }) {dimensions = array<i64: 0>} : (tensor<6xf32>, tensor<f32>) -> tensor<f32>

  // Divide sum by batch size (6)
  %batch_size = stablehlo.constant dense<6> : tensor<f32>
  %loss = stablehlo.divide %mean_loss, %batch_size : tensor<f32>

  return %loss : tensor<f32>
}

func.func @main(%arg0: tensor<6x7xf32>, %arg1: tensor<6xi64>) -> tensor<f32> {
  // Cross entropy loss:
  // input: logits (6x7), target class indices (6)
  // Steps:
  // 1) Compute log_softmax of logits along dim=1:
  //    log_softmax(x) = x - logsumexp(x)
  // 2) Gather log probabilities of the target classes
  // 3) Compute negative mean of these log probabilities

  // Step 1a: Compute max logits per batch element for numerical stability
  %c_neg_inf = stablehlo.constant dense<0xFF800000> : tensor<f32>  // -inf
  %max_logits = "stablehlo.reduce"(%arg0, %c_neg_inf) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.maximum %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<6xf32>

  // Step 1b: Broadcast max_logits back to shape 6x7
  %max_logits_bcast = "stablehlo.broadcast_in_dim"(%max_logits) {broadcast_dimensions = array<i64: 0>} : (tensor<6xf32>) -> tensor<6x7xf32>

  // Step 1c: Subtract max_logits for numerical stability
  %shifted_logits = stablehlo.subtract %arg0, %max_logits_bcast : tensor<6x7xf32>

  // Step 1d: Exponentiate shifted logits
  %exp_shifted = stablehlo.exponential %shifted_logits : tensor<6x7xf32>

  // Step 1e: Sum exp_shifted along dim=1
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %sum_exp = "stablehlo.reduce"(%exp_shifted, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<6xf32>

  // Step 1f: Compute log(sum_exp)
  %log_sum_exp = stablehlo.log %sum_exp : tensor<6xf32>

  // Step 1g: Broadcast log_sum_exp back to 6x7
  %log_sum_exp_bcast = "stablehlo.broadcast_in_dim"(%log_sum_exp) {broadcast_dimensions = array<i64: 0>} : (tensor<6xf32>) -> tensor<6x7xf32>

  // Step 1h: Compute log_softmax = shifted_logits - log_sum_exp_bcast
  %log_softmax = stablehlo.subtract %shifted_logits, %log_sum_exp_bcast : tensor<6x7xf32>

  // Step 2: Gather log probabilities of target classes
  // We have %arg1: tensor<6xi64> with class indices
  // We need to gather log_softmax[i, arg1[i]] for i in [0..5]

  // Create iota for batch dimension (0..5)
  %batch_iota = "stablehlo.iota"() {iota_dimension = 0 : i64} : () -> tensor<6xi32>
  // Convert target indices from i64 to i32 for indexing
  %target_i32 = stablehlo.convert %arg1 : (tensor<6xi64>) -> tensor<6xi32>

  // Reshape batch_iota and target_i32 to 1D tensors (already 1D)
  // Concatenate batch_iota and target_i32 to form indices for gather
  // StableHLO does not have gather op, so we simulate gather by:
  // 1) Reshape log_softmax to 42xf32 (6*7=42)
  // 2) Compute flat indices = batch_iota * 7 + target_i32
  %seven = stablehlo.constant dense<7> : tensor<i32>
  %batch_mul_seven = stablehlo.multiply %batch_iota, %seven : tensor<6xi32>
  %flat_indices = stablehlo.add %batch_mul_seven, %target_i32 : tensor<6xi32>

  // Reshape log_softmax to 42xf32
  %log_softmax_reshaped = stablehlo.reshape %log_softmax : (tensor<6x7xf32>) -> tensor<42xf32>

  // We need to gather elements at flat_indices from log_softmax_reshaped
  // StableHLO does not have gather, but we can do this by:
  // 1) Create a 42-element iota tensor
  %iota_42 = "stablehlo.iota"() {iota_dimension = 0 : i64} : () -> tensor<42xi32>
  // 2) Compare iota_42 with flat_indices broadcasted to 42x6 (or vice versa)
  //    Actually, better to compare each flat index with iota_42 and select matching elements

  // Broadcast flat_indices (6) to 42x6
  %flat_indices_bcast = "stablehlo.broadcast_in_dim"(%flat_indices) {broadcast_dimensions = array<i64: 1>} : (tensor<6xi32>) -> tensor<42x6xi32>
  // Broadcast iota_42 (42) to 42x6
  %iota_42_bcast = "stablehlo.broadcast_in_dim"(%iota_42) {broadcast_dimensions = array<i64: 0>} : (tensor<42xi32>) -> tensor<42x6xi32>

  // Compare equality: (iota_42_bcast == flat_indices_bcast) -> tensor<42x6xi1>
  %eq = "stablehlo.compare"(%iota_42_bcast, %flat_indices_bcast) {comparison_direction = #stablehlo<comparison_direction EQ>, compare_type = #stablehlo<comparison_type SIGNED>} : (tensor<42x6xi32>, tensor<42x6xi32>) -> tensor<42x6xi1>

  // Reshape log_softmax_reshaped to 42x1 to broadcast
  %log_softmax_reshaped_2d = stablehlo.reshape %log_softmax_reshaped : (tensor<42xf32>) -> tensor<42x1xf32>

  // Broadcast log_softmax_reshaped_2d to 42x6
  %log_softmax_bcast_42x6 = "stablehlo.broadcast_in_dim"(%log_softmax_reshaped_2d) {broadcast_dimensions = array<i64: 0>} : (tensor<42x1xf32>) -> tensor<42x6xf32>

  // Select elements where eq is true, else 0.0
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %zero_42x6 = "stablehlo.broadcast_in_dim"(%zero_f32) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<42x6xf32>
  %selected = "stablehlo.select"(%eq, %log_softmax_bcast_42x6, %zero_42x6) : (tensor<42x6xi1>, tensor<42x6xf32>, tensor<42x6xf32>) -> tensor<42x6xf32>

  // Sum over dimension 0 (42) to get 1 element per batch (6)
  %zero_f32_6 = stablehlo.constant dense<0.0> : tensor<f32>
  %sum_selected = "stablehlo.reduce"(%selected, %zero_f32_6) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<42x6xf32>, tensor<f32>) -> tensor<6xf32>

  // Now sum_selected contains the gathered log probabilities for each batch element

  // Step 3: Compute negative mean of these log probabilities
  // Sum over batch dimension
  %zero_f32_scalar = stablehlo.constant dense<0.0> : tensor<f32>
  %sum_log_probs = "stablehlo.reduce"(%sum_selected, %zero_f32_scalar) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<6xf32>, tensor<f32>) -> tensor<f32>

  // Compute mean by dividing by 6.0
  %six

func.func @main(%arg0: tensor<6x7xf32>, %arg1: tensor<6xi64>) -> tensor<f32> {
  // Extract batch size and number of classes from input shapes
  // batch_size = 6, num_classes = 7

  // Compute max_logits: max over classes dimension (dim=1)
  %c_f32_inf = stablehlo.constant dense<-inf> : tensor<f32>
  %max_logits = "stablehlo.reduce"(%arg0, %c_f32_inf) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.maximum %a, %b : tensor<f32>
      stablehlo.return %c : tensor<f32>
  }) {dimensions = array<i64: 1>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<6xf32>

  // Broadcast max_logits to shape 6x7 for subtraction
  %max_logits_bcast = "stablehlo.broadcast_in_dim"(%max_logits) {broadcast_dimensions = array<i64: 0>} : (tensor<6xf32>) -> tensor<6x7xf32>

  // Subtract max_logits from logits for numerical stability
  %logits_stable = stablehlo.subtract %arg0, %max_logits_bcast : tensor<6x7xf32>

  // Exponentiate stabilized logits
  %exp_logits = stablehlo.exponential %logits_stable : tensor<6x7xf32>

  // Sum of exponentials over classes dimension (dim=1)
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %sum_exp = "stablehlo.reduce"(%exp_logits, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %c : tensor<f32>
  }) {dimensions = array<i64: 1>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<6xf32>

  // Broadcast sum_exp to shape 6x7 for division
  %sum_exp_bcast = "stablehlo.broadcast_in_dim"(%sum_exp) {broadcast_dimensions = array<i64: 0>} : (tensor<6xf32>) -> tensor<6x7xf32>

  // Compute softmax probabilities: exp_logits / sum_exp
  %softmax = stablehlo.divide %exp_logits, %sum_exp_bcast : tensor<6x7xf32>

  // Prepare indices for gather: targets are indices into classes dimension
  // We need to gather softmax probabilities at positions given by targets for each batch element

  // Create batch indices [0,1,2,3,4,5]
  %batch_iota = "stablehlo.iota"() {iota_dimension = 0 : i64} : () -> tensor<6xi32>
  // Convert batch_iota to i64 to match targets type
  %batch_i64 = stablehlo.convert %batch_iota : (tensor<6xi32>) -> tensor<6xi64>

  // Stack batch indices and target indices to form gather indices of shape 6x2
  // First reshape batch_i64 and targets to 6x1
  %batch_i64_reshaped = stablehlo.reshape %batch_i64 : (tensor<6xi64>) -> tensor<6x1xi64>
  %targets_reshaped = stablehlo.reshape %arg1 : (tensor<6xi64>) -> tensor<6x1xi64>

  // Concatenate along dim=1 to get indices shape 6x2
  %gather_indices = "stablehlo.concatenate"(%batch_i64_reshaped, %targets_reshaped) {dimension = 1 : i64} : (tensor<6x1xi64>, tensor<6x1xi64>) -> tensor<6x2xi64>

  // Gather softmax probabilities at indices (batch, class)
  // stablehlo.gather is not in the provided ops, so we emulate gather by reshaping and using reduce_window or select
  // Since gather is not available, we do the following:

  // Reshape softmax to 42 (6*7) vector
  %softmax_reshaped = stablehlo.reshape %softmax : (tensor<6x7xf32>) -> tensor<42xf32>

  // Compute linear indices for gather: linear_index = batch * 7 + target
  // batch_i64 and targets are shape 6
  %num_classes_const = stablehlo.constant dense<7> : tensor<i64>
  %batch_mul = stablehlo.multiply %arg1, %num_classes_const : tensor<6xi64>
  %linear_indices = stablehlo.add %batch_mul, %arg1 : tensor<6xi64>

  // Convert linear_indices to i32 for indexing
  %linear_indices_i32 = stablehlo.convert %linear_indices : (tensor<6xi64>) -> tensor<6xi32>

  // Create iota for 42 elements for comparison
  %iota_42 = "stablehlo.iota"() {iota_dimension = 0 : i64} : () -> tensor<42xi32>

  // Broadcast linear_indices_i32 to 42x6 for comparison
  %linear_indices_i32_bcast = "stablehlo.broadcast_in_dim"(%linear_indices_i32) {broadcast_dimensions = array<i64: 1>} : (tensor<6xi32>) -> tensor<42x6xi32>

  // Broadcast iota_42 to 42x6
  %iota_42_bcast = "stablehlo.broadcast_in_dim"(%iota_42) {broadcast_dimensions = array<i64: 0>} : (tensor<42xi32>) -> tensor<42x6xi32>

  // Compare iota_42_bcast == linear_indices_i32_bcast to get mask
  %eq_mask = "stablehlo.compare"(%iota_42_bcast, %linear_indices_i32_bcast) {comparison_direction = #stablehlo<comparison_direction EQ>, compare_type = #stablehlo<comparison_type SIGNED>} : (tensor<42x6xi32>, tensor<42x6xi32>) -> tensor<42x6xi1>

  // Reshape softmax_reshaped to 42x1 for broadcasting
  %softmax_reshaped_2d = stablehlo.reshape %softmax_reshaped : (tensor<42xf32>) -> tensor<42x1xf32>

  // Broadcast softmax_reshaped_2d to 42x6
  %softmax_bcast_42x6 = "stablehlo.broadcast_in_dim"(%softmax_reshaped_2d) {broadcast_dimensions = array<i64: 0>} : (tensor<42x1xf32>) -> tensor<42x6xf32>

  // Convert eq_mask i1 to f32 for multiplication
  %eq_mask_f32 = stablehlo.convert %eq_mask : (tensor<42x6xi1>) -> tensor<42x6xf32>

  // Multiply softmax by mask to zero out non-matching indices
  %masked_softmax = stablehlo.multiply %softmax_bcast_42x6, %eq_mask_f32 : tensor<42x6xf32>

  // Sum over 42 dimension to get gathered values shape 6xf32
  %zero_f32_6 = stablehlo.constant dense<0.0> : tensor<f32>
  %gathered = "stablehlo.reduce"(%masked_softmax, %zero_f32_6) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %c : tensor<f32>
  }) {dimensions = array<i64: 0>} : (tensor<42x6xf32>, tensor<f32>) -> tensor<6xf32>

  // Compute log of gathered probabilities
  %log_gathered = stablehlo.log %gathered : tensor<6xf32>

  // Negate log probabilities
  %neg_log = stablehlo.negate %log_gathered : tensor<6xf32>

  // Sum over batch dimension to get scalar loss
  %zero_f32_scalar = stablehlo.constant dense<0.0> : tensor<f32>
  %loss = "stablehlo.reduce"(%neg_log, %zero_f32_scalar) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %c : tensor<f32>
  }) {dimensions = array<i64: 0>} : (tensor<6xf32>, tensor<f32>) -> tensor<f32>

  // Divide by batch size (6) to get mean loss
  %batch_size_const = stablehlo.constant dense<6.0> : tensor<f32>
  %mean_loss = stablehlo.divide %loss, %batch_size_const : tensor<f32>

  return %mean_loss : tensor<f32>
}

func.func @main(%conv_weight: tensor<6x7x3x3xf32>, %conv_bias: tensor<6xf32>, %input: tensor<6x7x6x6xf32>) -> tensor<6x6x4x4xf32> {
  // Convolution:
  // conv.weight shape: [6, 7, 3, 3]
  // input shape: [6, 7, 6, 6]
  // output shape: [6, 6, 4, 4] (default stride=1, padding=0)
  %conv_out = "stablehlo.convolution"(%input, %conv_weight) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 1, 1>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, i, 2, 3]x[o, i, 2, 3]->[b, o, 2, 3]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x7x6x6xf32>, tensor<6x7x3x3xf32>) -> tensor<6x6x4x4xf32>

  // Add bias: broadcast bias from [6] to [6,6,4,4]
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%conv_bias) {broadcast_dimensions = array<i64: 0>} : (tensor<6xf32>) -> tensor<6x1x1x1xf32>
  %bias_broadcast_reshaped = "stablehlo.broadcast_in_dim"(%bias_broadcast) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<6x1x1x1xf32>) -> tensor<6x6x4x4xf32>
  %biased = stablehlo.add %conv_out, %bias_broadcast_reshaped : tensor<6x6x4x4xf32>

  // InstanceNorm2d forward:
  // Input shape: [6, 6, 4, 4]
  // InstanceNorm2d normalizes per-sample per-channel over spatial dims (4x4)
  // Compute mean over dims [2,3]
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %init_mean = stablehlo.broadcast_in_dim %zero_f32 {broadcast_dimensions = array<i64: } : (tensor<f32>) -> tensor<f32> // dummy, will replace
  %init_mean = stablehlo.constant dense<0.0> : tensor<f32>
  %init_var = stablehlo.constant dense<0.0> : tensor<f32>

  // Reduce mean over dims 2 and 3
  %sum_spatial = "stablehlo.reduce"(%biased, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2, 3>} : (tensor<6x6x4x4xf32>, tensor<f32>) -> tensor<6x6xf32>

  // Compute mean = sum / (4*4=16)
  %const_16 = stablehlo.constant dense<16.0> : tensor<f32>
  %mean = stablehlo.divide %sum_spatial, %const_16 : tensor<6x6xf32>

  // Broadcast mean to [6,6,4,4]
  %mean_broadcast = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<6x6xf32>) -> tensor<6x6x1x1xf32>
  %mean_broadcast_full = "stablehlo.broadcast_in_dim"(%mean_broadcast) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<6x6x1x1xf32>) -> tensor<6x6x4x4xf32>

  // Compute (x - mean)
  %x_centered = stablehlo.subtract %biased, %mean_broadcast_full : tensor<6x6x4x4xf32>

  // Compute variance: mean of squared differences
  %x_centered_sq = stablehlo.multiply %x_centered, %x_centered : tensor<6x6x4x4xf32>
  %sum_sq = "stablehlo.reduce"(%x_centered_sq, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2, 3>} : (tensor<6x6x4x4xf32>, tensor<f32>) -> tensor<6x6xf32>

  %var = stablehlo.divide %sum_sq, %const_16 : tensor<6x6xf32>

