  %inv_std = stablehlo.rsqrt %var_eps : tensor<6x6xf32>

  // Broadcast inv_std to [6,6,4,4]
  %inv_std_broadcast = "stablehlo.broadcast_in_dim"(%inv_std) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<6x6xf32>) -> tensor<6x6x1x1xf32>
  %inv_std_broadcast_full = "stablehlo.broadcast_in_dim"(%inv_std_broadcast) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<6x6x1x1xf32>) -> tensor<6x6x4x4xf32>

  // Normalize: (x - mean) * inv_std
  %normalized = stablehlo.multiply %x_centered, %inv_std_broadcast_full : tensor<6x6x4x4xf32>

  // Divide by constant 2.0
  %const_2 = stablehlo.constant dense<2.0> : tensor<f32>
  %const_2_broadcast = stablehlo.broadcast_in_dim %const_2 {broadcast_dimensions = array<i64: } : (tensor<f32>) -> tensor<f32> // dummy, will replace
