  %const_2_broadcast_reshaped = "stablehlo.broadcast_in_dim"(%const_2_broadcast) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<f32>) -> tensor<6x6x4x4xf32>

  %output = stablehlo.divide %normalized, %const_2_broadcast_reshaped : tensor<6x6x4x4xf32>

  return %output : tensor<6x6x4x4xf32>
}

func.func @main(%conv_weight: tensor<6x7x3x3xf32>, %conv_bias: tensor<6xf32>, %input: tensor<6x7x6x6xf32>) -> tensor<6x6x4x4xf32> {
  // Perform convolution: input (N=6, C=7, H=6, W=6), weight (O=6, I=7, KH=3, KW=3)
