  // So broadcast_dimensions = [1]
  %bias_broadcast_full = "stablehlo.broadcast_in_dim"(%conv_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<6xf32>) -> tensor<6x6x4x4xf32>

  %conv_bias_added = stablehlo.add %conv, %bias_broadcast_full : tensor<6x6x4x4xf32>

  // InstanceNorm2d forward:
  // For each sample and channel, compute mean and variance over spatial dims (height=4, width=4)
  // mean shape: (6,6), variance shape: (6,6)
  // Compute mean over dims 2 and 3
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %init_mean = stablehlo.constant dense<0.0> : tensor<f32>
  %init_var = stablehlo.constant dense<0.0> : tensor<f32>

  // Compute mean over dims 2 and 3
  %mean_temp = "stablehlo.reduce"(%conv_bias_added, %init_mean) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2, 3>} : (tensor<6x6x4x4xf32>, tensor<f32>) -> tensor<6x6xf32>

  // Compute number of elements in spatial dims: 4*4=16
  %count = stablehlo.constant dense<16.0> : tensor<f32>

  // mean = sum / count
  %mean = stablehlo.divide %mean_temp, %count : tensor<6x6xf32>

  // Compute variance: mean of squared difference from mean
  // First broadcast mean to shape (6x6x4x4)
  %mean_broadcast = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<6x6xf32>) -> tensor<6x6x4x4xf32>

  // Compute (x - mean)
  %diff = stablehlo.subtract %conv_bias_added, %mean_broadcast : tensor<6x6x4x4xf32>

  // Compute (x - mean)^2
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<6x6x4x4xf32>

  // Sum squared differences over spatial dims 2 and 3
  %var_sum = "stablehlo.reduce"(%diff_sq, %init_var) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2, 3>} : (tensor<6x6x4x4xf32>, tensor<f32>) -> tensor<6x6xf32>

  // variance = var_sum / count
  %variance = stablehlo.divide %var_sum, %count : tensor<6x6xf32>

  // Compute rsqrt(variance + epsilon)
  %epsilon = stablehlo.constant dense<1.0e-5> : tensor<f32>
  %variance_eps = stablehlo.add %variance, %epsilon : tensor<6x6xf32>
  %inv_stddev = stablehlo.rsqrt %variance_eps : tensor<6x6xf32>

  // Normalize: (x - mean) * inv_stddev
  %inv_stddev_broadcast = "stablehlo.broadcast_in_dim"(%inv_stddev) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<6x6xf32>) -> tensor<6x6x4x4xf32>
  %normalized = stablehlo.multiply %diff, %inv_stddev_broadcast : tensor<6x6x4x4xf32>

  // Divide by constant 2.0
  %divisor = stablehlo.constant dense<2.0> : tensor<f32>
  %divisor_broadcast = "stablehlo.broadcast_in_dim"(%divisor) {broadcast_dimensions = array<i64:>} : (tensor<f32>) -> tensor<f32>
  %result = stablehlo.divide %normalized, %divisor_broadcast : tensor<6x6x4x4xf32>

  "stablehlo.return"(%result) : tensor<6x6x4x4xf32>
}

func.func @main(%conv_weight: tensor<6x7x3x3xf32>, %conv_bias: tensor<6xf32>, %input: tensor<6x7x6x6xf32>) -> tensor<6x6x4x4xf32> {
  // Convolution parameters:
  // input: [batch=6, in_channels=7, height=6, width=6]
  // weight: [out_channels=6, in_channels=7, kernel_h=3, kernel_w=3]
  // output shape: [6, 6, 4, 4] with stride=1, padding=0, dilation=1

  // Perform convolution
  %conv = "stablehlo.convolution"(%input, %conv_weight) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 1, 1>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, i, 2, 3]x[o, i, 2, 3]->[b, f, 2, 3]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x7x6x6xf32>, tensor<6x7x3x3xf32>) -> tensor<6x6x4x4xf32>

  // Add bias: broadcast bias from [6] to [6x6x4x4]
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%conv_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<6xf32>) -> tensor<1x6x1x1xf32>
  %bias_broadcast_reshaped = "stablehlo.broadcast_in_dim"(%bias_broadcast) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<1x6x1x1xf32>) -> tensor<6x6x4x4xf32>
  %conv_bias_added = stablehlo.add %conv, %bias_broadcast_reshaped : tensor<6x6x4x4xf32>

  // InstanceNorm2d forward:
  // For each sample (b) and channel (c), compute mean and variance over spatial dims (h,w)
  // mean = sum / (H*W)
  // variance = sum((x - mean)^2) / (H*W)
  // normalized = (x - mean) / sqrt(variance + eps)
  // eps = 1e-5

  // Constants
  %eps = stablehlo.constant dense<0.00001> : tensor<f32>
  %hw = stablehlo.constant dense<16> : tensor<f32>  // 4*4=16 spatial elements

  // Compute mean over dims 2 and 3 (h,w)
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %init_mean = "stablehlo.broadcast_in_dim"(%zero_f32) {broadcast_dimensions = array<i64>} : (tensor<f32>) -> tensor<f32> // scalar zero

  %mean = "stablehlo.reduce"(%conv_bias_added, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  }) {dimensions = array<i64: 2, 3>} : (tensor<6x6x4x4xf32>, tensor<f32>) -> tensor<6x6xf32>

  // mean = sum / 16
  %hw_broadcast = "stablehlo.broadcast_in_dim"(%hw) {broadcast_dimensions = array<i64: 2} } : (tensor<f32>) -> tensor<6x6xf32>
  %mean_div = stablehlo.divide %mean, %hw_broadcast : tensor<6x6xf32>

  // Broadcast mean to shape [6x6x4x4] for subtraction
  %mean_broadcast = "stablehlo.broadcast_in_dim"(%mean_div) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<6x6xf32>) -> tensor<6x6x1x1xf32>
  %mean_broadcast_full = "stablehlo.broadcast_in_dim"(%mean_broadcast) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<6x6x1x1xf32>) -> tensor<6x6x4x4xf32>

  // x - mean
  %x_centered = stablehlo.subtract %conv_bias_added, %mean_broadcast_full : tensor<6x6x4x4xf32>

  // Compute variance: mean of squared differences
  %x_centered_sq = stablehlo.multiply %x_centered, %x_centered : tensor<6x6x4x4xf32>

  %var_sum = "stablehlo.reduce"(%x_centered_sq, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  }) {dimensions = array<i64: 2, 3>} : (tensor<6x6x4x4xf32>, tensor<f32>) -> tensor<6x6xf32>

  // variance = var_sum / 16
  %var = stablehlo.divide %var_sum, %hw_broadcast : tensor<6x6xf32>

  // Add eps to variance
  %eps_broadcast = "stablehlo.broadcast_in_dim"(%eps) {broadcast_dimensions = array<i64: 0} } : (tensor<f32>) -> tensor<6x6xf32>
  %var_eps = stablehlo.add %var, %eps_broadcast : tensor<6x6xf32>

  // sqrt(variance + eps)
  %stddev = stablehlo.sqrt %var_eps : tensor<6x6xf32>

  // Broadcast stddev to [6x6x4x4]
  %stddev_broadcast = "stablehlo.broadcast_in_dim"(%stddev) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<6x6xf32>) -> tensor<6x6x1x1xf32>
  %stddev_broadcast_full = "stablehlo.broadcast_in_dim"(%stddev_broadcast) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<6x6x1x1xf32>) -> tensor<6x6x4x4xf32>

  // normalized = (x - mean) / stddev
  %normalized = stablehlo.divide %x_centered, %stddev_broadcast_full : tensor<6x6x4x4xf32>

  // Divide by divide_by = 2.0
  %divide_by = stablehlo.constant dense<2.0> : tensor<f32>
  %divide_by_broadcast = "stablehlo.broadcast_in_dim"(%divide_by) {broadcast_dimensions = array<i64: 0} } : (tensor<f32>) -> tensor<6x6x4x4xf32>

  %output = stablehlo.divide %normalized, %divide_by_broadcast : tensor<6x6x4x4xf32>

  return %output : tensor<6x6x4x4xf32>
}

