func.func @main(%arg0: tensor<6x7x3x3xf32>, %arg1: tensor<6xf32>, %arg2: tensor<6x7x6x6xf32>) -> tensor<6x6x4x4xf32> {
  // %arg0: conv.weight (out_channels=6, in_channels=7, kernel_h=3, kernel_w=3)
  // %arg1: conv.bias (out_channels=6)
  // %arg2: input tensor (batch=6, in_channels=7, height=6, width=6)

  // Convolution parameters:
  // input: [6,7,6,6]
  // kernel: [6,7,3,3]
  // output: [6,6,4,4] because:
  // output_h = floor((6 + 0 + 0 - (3 - 1) - 1)/1 + 1) = 4
  // output_w = same as output_h = 4

  // dimension_numbers for conv:
  // input dims: [b, f, h, w] = [0,1,2,3]
  // kernel dims: [o, i, h, w] = [0,1,2,3]
  // output dims: [b, f, h, w] = [0,1,2,3]
  // So dimension_numbers = #stablehlo.conv<[0,1,2,3]x[0,1,2,3]->[0,1,2,3]>

  %zero_i64 = stablehlo.constant dense<0> : tensor<i64>
  %one_i64 = stablehlo.constant dense<1> : tensor<i64>

  // Convolution: no padding, stride=1, dilation=1
  %conv = "stablehlo.convolution"(%arg2, %arg0) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 1, 1>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[0,1,2,3]x[0,1,2,3]->[0,1,2,3]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x7x6x6xf32>, tensor<6x7x3x3xf32>) -> tensor<6x6x4x4xf32>

  // Add bias: %arg1 shape [6], conv output shape [6,6,4,4]
  // Broadcast bias to [6,6,4,4] with broadcast_in_dim dims = [1]
  %bias_bcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<6xf32>) -> tensor<6x6x4x4xf32>

  %conv_bias = stablehlo.add %conv, %bias_bcast : tensor<6x6x4x4xf32>

  // InstanceNorm2d forward:
  // Input shape: [batch=6, channels=6, height=4, width=4]
  // InstanceNorm2d normalizes per instance per channel over spatial dims (height,width)
  // Compute mean over dims [2,3]
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>

  // Compute mean over dims 2 and 3
  %mean_h = "stablehlo.reduce"(%conv_bias, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2, 3>} : (tensor<6x6x4x4xf32>, tensor<f32>) -> tensor<6x6xf32>

  // Number of elements in spatial dims = 4*4=16
  %num_elements = stablehlo.constant dense<16.0> : tensor<f32>

  // Broadcast num_elements to mean shape [6,6]
  %num_elements_bcast = "stablehlo.broadcast_in_dim"(%num_elements) {broadcast_dimensions = array<i64: } : (tensor<f32>) -> tensor<6x6xf32>
  // Actually, broadcast_dimensions must match rank of operand (0) to rank of result (2)
  // So broadcast_dimensions = [] means scalar broadcast to all dims
  %num_elements_bcast = "stablehlo.broadcast_in_dim"(%num_elements) {broadcast_dimensions = array<i64: } : (tensor<f32>) -> tensor<6x6xf32>
  // But stablehlo.broadcast_in_dim requires broadcast_dimensions size == rank(operand) == 0
  // So broadcast_dimensions = array<i64: > (empty) is valid
  %num_elements_bcast = "stablehlo.broadcast_in_dim"(%num_elements) {broadcast_dimensions = array<i64: } : (tensor<f32>) -> tensor<6x6xf32>
  // To be explicit:
  %num_elements_bcast = "stablehlo.broadcast_in_dim"(%num_elements) {broadcast_dimensions = array<i64: } : (tensor<f32>) -> tensor<6x6xf32>

  // Divide sum by number of elements to get mean
  %mean = stablehlo.divide %mean_h, %num_elements_bcast : tensor<6x6xf32>

  // Compute variance:
  // variance = mean((x - mean)^2)
  // First broadcast mean to shape [6,6,4,4]
  %mean_bcast = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<6x6xf32>) -> tensor<6x6x4x4xf32>

  // Compute (x - mean)
  %diff = stablehlo.subtract %conv_bias, %mean_bcast : tensor<6x6x4x4xf32>

  // Compute (x - mean)^2
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<6x6x4x4xf32>

  // Reduce mean of diff_sq over dims [2,3]
  %var_sum = "stablehlo.reduce"(%diff_sq, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2, 3>} : (tensor<6x6x4x4xf32>, tensor<f32>) -> tensor<6x6xf32>

  // Divide by number of elements to get variance
  %var = stablehlo.divide %var_sum, %num_elements_bcast : tensor<6x6xf32>

  // Add epsilon for numerical stability (epsilon=1e-5)
  %epsilon = stablehlo.constant dense<0.00001> : tensor<f32>
  %epsilon_bcast = "stablehlo.broadcast_in_dim"(%epsilon) {broadcast_dimensions = array<i64: } : (tensor<f32>) -> tensor<6x6xf32>

  %var_eps = stablehlo.add %var, %epsilon_bcast : tensor<6x6xf32>

  // Compute sqrt(var + eps)
  %stddev = stablehlo.sqrt %var_eps : tensor<6x6xf32>

  // Broadcast stddev to [6,6,4,4]
  %stddev_bcast = "stablehlo.broadcast_in_dim"(%stddev) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<6x6xf32>) -> tensor<6x6x4x4xf32>

  // Normalize: (x - mean) / stddev
  %norm = stablehlo.divide %diff, %stddev_bcast : tensor<6x6x4x4xf32>

  // InstanceNorm2d affine parameters (weight=1, bias=0) are default, so no scale or shift

  // Divide by divide_by constant (2.0)
  %divide_by = stablehlo.constant dense<2.0> : tensor<f32>
  // Broadcast divide_by to output shape [6,6,4,4]
  %divide_by_bcast = "stablehlo.broadcast_in_dim"(%divide_by) {broadcast_dimensions = array<i64: } : (tensor<f32>) -> tensor<6x6x4x4xf32>

  %output = stablehlo.divide %norm, %divide_by_bcast : tensor<6x6x4x4xf32>

  return %output : tensor<6x6x4x4xf32>
}

