  // max over dim=1 keepdim=True: input shape [6x1], max over dim=1 means dim=1 size=1, so max over size 1 dimension is identity
  // But input shape is [6x1], dim=1 size=1, max over dim=1 is the same tensor
  // So max is identity here, but we must implement max reduction anyway
  // max init value is -inf
  %neg_inf = stablehlo.constant dense<0xFF800000> : tensor<f32>  // -inf
  %max = "stablehlo.reduce"(%sum_keepdim, %neg_inf) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>): 
      %c = stablehlo.maximum %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x1xf32>, tensor<f32>) -> tensor<6xf32>
  // reshape max [6] to [6x1]
  %max_keepdim = "stablehlo.broadcast_in_dim"(%max) {broadcast_dimensions = array<i64: 0>} : (tensor<6xf32>) -> tensor<6x1xf32>

  // mean over dim=1 keepdim=True: input shape [6x1], mean over dim=1 size=1 is identity
  // But implement mean as sum / size
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %size = stablehlo.constant dense<1.0> : tensor<f32>  // size of dim=1 is 1
  // sum over dim=1 of max_keepdim (shape [6x1]) is same as max_keepdim itself
  // So mean = sum / size = max_keepdim / 1 = max_keepdim
  %mean = stablehlo.divide %max_keepdim, %size : tensor<6x1xf32>

  // logsumexp over dim=1 keepdim=True: input shape [6x1], logsumexp over dim=1 size=1 is log(exp(x))=x
  // But implement logsumexp properly:
  // logsumexp(x) = log(sum(exp(x)))
  // sum over dim=1 of exp(x)
  %exp = stablehlo.exponential %mean : tensor<6x1xf32>
  %zero_6x1 = stablehlo.constant dense<0.0> : tensor<f32>
  %sum_exp = "stablehlo.reduce"(%exp, %zero_6x1) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>): 
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x1xf32>, tensor<f32>) -> tensor<6xf32>
  // reshape sum_exp [6] to [6x1]
  %sum_exp_keepdim = "stablehlo.broadcast_in_dim"(%sum_exp) {broadcast_dimensions = array<i64: 0>} : (tensor<6xf32>) -> tensor<6x1xf32>
  %logsumexp1 = stablehlo.log %sum_exp_keepdim : tensor<6x1xf32>

  // second logsumexp over dim=1 keepdim=True: input shape [6x1], same as above
  %exp2 = stablehlo.exponential %logsumexp1 : tensor<6x1xf32>
  %sum_exp2 = "stablehlo.reduce"(%exp2, %zero_6x1) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>): 
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x1xf32>, tensor<f32>) -> tensor<6xf32>
  %sum_exp2_keepdim = "stablehlo.broadcast_in_dim"(%sum_exp2) {broadcast_dimensions = array<i64: 0>} : (tensor<6xf32>) -> tensor<6x1xf32>
  %logsumexp2 = stablehlo.log %sum_exp2_keepdim : tensor<6x1xf32>

  "stablehlo.return"(%logsumexp2) : tensor<6x1xf32>
}

func.func @main(%arg0: tensor<7x7xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x7xf32>) -> tensor<6x1xf32> {
  // Linear layer: y = x @ W^T + b
  // %arg0 = linear.weight (7x7), %arg1 = linear.bias (7), %arg2 = input (6x7)
  // We want: (6x7) @ (7x7)^T = (6x7) @ (7x7) -> (6x7)
  // So transpose weight to (7x7) (actually same shape), but we want to contract last dim of input with last dim of weight transposed.
  // We'll do dot_general with contracting dims: input dim 1 and weight dim 1 (weight transposed dims 1 and 0 swapped)
  // Actually, weight shape is (7x7), input (6x7), so to do input @ weight^T:
  // weight^T shape: (7x7) transpose dims [1,0]
  %weight_t = "stablehlo.transpose"(%arg0) {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>
  %linear = "stablehlo.dot_general"(%arg2, %weight_t) {dot_dimension_numbers = #stablehlo.dot<lhs_batching_dimensions = [], rhs_batching_dimensions = [], lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [1]>} : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>
  // Add bias: broadcast bias (7) to (6x7)
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %linear_bias = stablehlo.add %linear, %bias_broadcast : tensor<6x7xf32>

  // sum over dim=1 keepdim=True: reduce sum over dim 1
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %sum = "stablehlo.reduce"(%linear_bias, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<6xf32>
  // keepdim=True means output shape is (6,1), so reshape sum (6) to (6x1)
  // But reduce returns shape with dim 1 removed, so shape is (6), we need to broadcast to (6x1)
  %sum_reshape = "stablehlo.broadcast_in_dim"(%sum) {broadcast_dimensions = array<i64: 0>} : (tensor<6xf32>) -> tensor<6x1xf32>

  // max over dim=1 keepdim=True: input shape (6x1), max over dim=1 means dim=1 size=1, so max over dim=1 is trivial (only one element)
  // But original code does max over dim=1 keepdim=True on (batch_size,1), so max over dim=1 of (6x1) -> (6x1)
  // So max over dim=1 of (6x1) is just the same tensor (max of single element)
  // We'll implement max reduce over dim=1 with initial value -inf
  %neg_inf = stablehlo.constant dense<0xFF800000> : tensor<f32>  // -inf
  %max = "stablehlo.reduce"(%sum_reshape, %neg_inf) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.maximum %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x1xf32>, tensor<f32>) -> tensor<6xf32>
  // reshape max (6) to (6x1)
  %max_reshape = "stablehlo.broadcast_in_dim"(%max) {broadcast_dimensions = array<i64: 0>} : (tensor<6xf32>) -> tensor<6x1xf32>

  // mean over dim=1 keepdim=True: input shape (6x1), mean over dim=1 is same as input (only one element)
  // But we implement mean as sum / size
  %one_f32 = stablehlo.constant dense<1.0> : tensor<f32>
  %sum_for_mean = "stablehlo.reduce"(%max_reshape, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x1xf32>, tensor<f32>) -> tensor<6xf32>
  // divide sum by 1 (dim size)
  %mean = stablehlo.divide %sum_for_mean, %one_f32 : tensor<6xf32>
  // reshape mean (6) to (6x1)
  %mean_reshape = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = array<i64: 0>} : (tensor<6xf32>) -> tensor<6x1xf32>

  // logsumexp over dim=1 keepdim=True: input shape (6x1)
  // logsumexp(x) = log(sum(exp(x)))
  // exp
  %exp = stablehlo.exponential %mean_reshape : tensor<6x1xf32>
  // sum over dim=1 keepdim=True
  %zero_f32_2 = stablehlo.constant dense<0.0> : tensor<f32>
  %sum_exp = "stablehlo.reduce"(%exp, %zero_f32_2) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x1xf32>, tensor<f32>) -> tensor<6xf32>
  // reshape sum_exp (6) to (6x1)
  %sum_exp_reshape = "stablehlo.broadcast_in_dim"(%sum_exp) {broadcast_dimensions = array<i64: 0>} : (tensor<6xf32>) -> tensor<6x1xf32>
  // log
  %logsumexp = stablehlo.log %sum_exp_reshape : tensor<6x1xf32>

  // second logsumexp over dim=1 keepdim=True: input shape (6x1)
  %exp2 = stablehlo.exponential %logsumexp : tensor<6x1xf32>
  %sum_exp2 = "stablehlo.reduce"(%exp2, %zero_f32_2) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x1xf32>, tensor<f32>) -> tensor<6xf32>
  %sum_exp2_reshape = "stablehlo.broadcast_in_dim"(%sum_exp2) {broadcast_dimensions = array<i64: 0>} : (tensor<6xf32>) -> tensor<6x1xf32>
  %logsumexp2 = stablehlo.log %sum_exp2_reshape : tensor<6x1xf32>

  return %logsumexp2 : tensor<6x1xf32>
}

