func.func @main(%bias: tensor<16xf32>, %gemm_weight: tensor<16x16xf32>, %gemm_bias: tensor<16xf32>, %groupnorm_weight: tensor<16xf32>, %groupnorm_bias: tensor<16xf32>, %input: tensor<16x16xf32>) -> tensor<16x16xf32> {
  // %x = gemm(input, gemm_weight) + gemm_bias
  %x0 = "stablehlo.dot_general"(%input, %gemm_weight) {dot_dimension_numbers = #stablehlo.dot<lhs_batching_dimensions = [0], rhs_batching_dimensions = [1], lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>} : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
  %x1 = "stablehlo.broadcast_in_dim"(%gemm_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %x2 = stablehlo.add %x0, %x1 : tensor<16x16xf32>

  // + bias (bias shape is [16], broadcast on dim 1)
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%bias) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %x3 = stablehlo.add %x2, %bias_broadcast : tensor<16x16xf32>

  // hardtanh clamp between 0 and 1
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %zero_bcast = "stablehlo.broadcast_in_dim"(%zero) {broadcast_dimensions = array<i64: {}} : () -> tensor<f32>
  %one_bcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: {}} : () -> tensor<f32>
  %x4 = stablehlo.maximum %x3, %zero : tensor<16x16xf32>
  %x5 = stablehlo.minimum %x4, %one : tensor<16x16xf32>

  // mish: x * tanh(softplus(x)) = x * tanh(log(1 + exp(x)))
  %exp_x = stablehlo.exponential %x5 : tensor<16x16xf32>
  %one_bcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: {}} : () -> tensor<f32>
  %exp_plus_one = stablehlo.add %exp_x, %one : tensor<16x16xf32>
  %softplus = stablehlo.log %exp_plus_one : tensor<16x16xf32>
  %tanh_softplus = stablehlo.tanh %softplus : tensor<16x16xf32>
  %x6 = stablehlo.multiply %x5, %tanh_softplus : tensor<16x16xf32>

  // groupnorm: reshape to (N=16, C=16, H=1, W=1)
  %x7 = stablehlo.reshape %x6 : (tensor<16x16xf32>) -> tensor<16x16x1x1xf32>

  // compute mean over H and W dims (dims 2 and 3)
  %zero_init = stablehlo.constant dense<0.0> : tensor<f32>
  %zero_init_4d = "stablehlo.broadcast_in_dim"(%zero_init) {broadcast_dimensions = array<i64: {}} : () -> tensor<f32>
  %mean = "stablehlo.reduce"(%x7, %zero_init_4d) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2, 3>} : (tensor<16x16x1x1xf32>, tensor<f32>) -> tensor<16x16xf32>

  // mean /= (1*1) = 1, so mean unchanged

  // compute variance: mean of (x - mean)^2 over dims 2 and 3
  %mean_bcast = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = array<i64: 0,1>} : (tensor<16x16xf32>) -> tensor<16x16x1x1xf32>
  %diff = stablehlo.subtract %x7, %mean_bcast : tensor<16x16x1x1xf32>
  %sq_diff = stablehlo.multiply %diff, %diff : tensor<16x16x1x1xf32>
  %var = "stablehlo.reduce"(%sq_diff, %zero_init_4d) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2, 3>} : (tensor<16x16x1x1xf32>, tensor<f32>) -> tensor<16x16xf32>

  // variance /= 1, so var unchanged

  // epsilon constant for numerical stability
  %eps = stablehlo.constant dense<1.000000e-05> : tensor<f32>
  %eps_bcast = "stablehlo.broadcast_in_dim"(%eps) {broadcast_dimensions = array<i64: {}} : () -> tensor<f32>

  // var + eps
  %var_eps = stablehlo.add %var, %eps : tensor<16x16xf32>

  // rsqrt(var + eps)
  %inv_std = stablehlo.rsqrt %var_eps : tensor<16x16xf32>

  // groupnorm.weight and bias broadcast to (N,C,H,W)
  %groupnorm_weight_bcast = "stablehlo.broadcast_in_dim"(%groupnorm_weight) {broadcast_dimensions = array<i64: 1} : (tensor<16xf32>) -> tensor<16x16x1x1xf32>
  %groupnorm_bias_bcast = "stablehlo.broadcast_in_dim"(%groupnorm_bias) {broadcast_dimensions = array<i64: 1} : (tensor<16xf32>) -> tensor<16x16x1x1xf32>

  // inv_std broadcast to (N,C,H,W)
  %inv_std_bcast = "stablehlo.broadcast_in_dim"(%inv_std) {broadcast_dimensions = array<i64: 0,1>} : (tensor<16x16xf32>) -> tensor<16x16x1x1xf32>

  // normalize: (x - mean) * inv_std
  %norm = stablehlo.multiply %diff, %inv_std_bcast : tensor<16x16x1x1xf32>

  // scale and shift: norm * weight + bias
  %scaled = stablehlo.multiply %norm, %groupnorm_weight_bcast : tensor<16x16x1x1xf32>
  %shifted = stablehlo.add %scaled, %groupnorm_bias_bcast : tensor<16x16x1x1xf32>

  // reshape back to (16,16)
  %output = stablehlo.reshape %shifted : (tensor<16x16x1x1xf32>) -> tensor<16x16xf32>

  return %output : tensor<16x16xf32>
}

func.func @main(%arg0: tensor<16xf32>, %arg1: tensor<16x16xf32>, %arg2: tensor<16xf32>, %arg3: tensor<16xf32>, %arg4: tensor<16xf32>, %arg5: tensor<16x16xf32>) -> tensor<16x16xf32> {
  // %arg0: bias (tensor<16xf32>)
  // %arg1: gemm.weight (tensor<16x16xf32>)
  // %arg2: gemm.bias (tensor<16xf32>) -- unused in PyTorch forward, so ignored here
  // %arg3: groupnorm.weight (tensor<16xf32>)
  // %arg4: groupnorm.bias (tensor<16xf32>)
  // %arg5: input x (tensor<16x16xf32>)

  // Step 1: gemm: x @ weight^T + bias
  // PyTorch Linear does x @ weight^T + bias
  // %arg1 is weight (out_features x in_features) = 16x16
  // input x is batch_size x in_features = 16x16
  // So we do dot_general with contracting dims: input dim 1 and weight dim 1
  // But weight needs to be transposed to shape 16x16 (same shape), but we want weight^T
  // So transpose weight to 16x16 (swap dims 0 and 1)
  %weight_t = "stablehlo.transpose"(%arg1) {permutation = array<i64: 1, 0>} : (tensor<16x16xf32>) -> tensor<16x16xf32>

  // dot_general: batch dims empty, contracting dims input dim 1 and weight_t dim 0
  %gemm = "stablehlo.dot_general"(%arg5, %weight_t) {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [],
      rhs_batching_dimensions = [],
      lhs_contracting_dimensions = [1],
      rhs_contracting_dimensions = [0]>
  } : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Step 2: add bias (broadcast bias shape [16] to [16x16])
  // Broadcast bias on dimension 1 (features)
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg0) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %add_bias = stablehlo.add %gemm, %bias_broadcast : tensor<16x16xf32>

  // Step 3: Hardtanh clamp between 0 and 1
  // clamp(x, 0, 1) = min(max(x, 0), 1)
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %zero_bcast = "stablehlo.broadcast_in_dim"(%zero) {broadcast_dimensions = array<i64:>} : (tensor<f32>) -> tensor<16x16xf32>
  %one_bcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64:>} : (tensor<f32>) -> tensor<16x16xf32>
  %max0 = stablehlo.maximum %add_bias, %zero_bcast : tensor<16x16xf32>
  %hardtanh = stablehlo.minimum %max0, %one_bcast : tensor<16x16xf32>

  // Step 4: Mish activation: x * tanh(softplus(x))
  // softplus(x) = log(1 + exp(x))
  %exp_hardtanh = stablehlo.exponential %hardtanh : tensor<16x16xf32>
  %one_bcast2 = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64:>} : (tensor<f32>) -> tensor<16x16xf32>
  %exp_plus_one = stablehlo.add %exp_hardtanh, %one_bcast2 : tensor<16x16xf32>
  %softplus = stablehlo.log %exp_plus_one : tensor<16x16xf32>
  %tanh_softplus = stablehlo.tanh %softplus : tensor<16x16xf32>
  %mish = stablehlo.multiply %hardtanh, %tanh_softplus : tensor<16x16xf32>

  // Step 5: GroupNorm
  // num_groups = 16, num_channels = 16, so each group has 1 channel
  // Input shape: [batch=16, channels=16]
  // Reshape to [batch=16, groups=16, channels_per_group=1]
  %reshape1 = stablehlo.reshape %mish : (tensor<16x16xf32>) -> tensor<16x16x1xf32>

  // Compute mean over channels_per_group dim (dim=2)
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %zero_f32_bcast = "stablehlo.broadcast_in_dim"(%zero_f32) {broadcast_dimensions = array<i64:>} : (tensor<f32>) -> tensor<1xf32>
  %mean = "stablehlo.reduce"(%reshape1, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2>} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>

  // mean shape: [16,16] (batch, groups)
  // channels_per_group = 1, so divide sum by 1 = no-op, mean = sum

  // Compute variance: mean((x - mean)^2)
  // Broadcast mean to shape [16,16,1]
  %mean_bcast = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = array<i64: 0,1>} : (tensor<16x16xf32>) -> tensor<16x16x1xf32>
  %diff = stablehlo.subtract %reshape1, %mean_bcast : tensor<16x16x1xf32>
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<16x16x1xf32>

  %zero_f322 = stablehlo.constant dense<0.0> : tensor<f32>
  %var = "stablehlo.reduce"(%diff_sq, %zero_f322) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2>} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>

  // variance mean over 1 element = no-op

  // Add epsilon for numerical stability
  %eps = stablehlo.constant dense<1.000000e-05> : tensor<f32>
  %eps_bcast = "stablehlo.broadcast_in_dim"(%eps) {broadcast_dimensions = array<i64:>} : (tensor<f32>) -> tensor<16x16xf32>
  %var_eps = stablehlo.add %var, %eps_bcast : tensor<16x16xf32>

  // sqrt(var + eps)
  %stddev = stablehlo.sqrt %var_eps : tensor<16x16xf32>

  // Normalize: (x - mean) / stddev
